async function loadPostDeployChecklist(projectName, sessionId) {
    const contentDiv = document.getElementById(`${sessionId}-checklist-content`);
    if (!contentDiv) return;
    const text = contentDiv.textContent.trim();
    if (text !== 'Loading checklist...' && text !== '') return;
    const projectData = await loadProjectData(projectName);
    const html = buildPostDeployChecklist(sessionId, projectData);
    contentDiv.innerHTML = html || '<div class="t-secondary">No checklist data available.</div>';
}
window.loadPostDeployChecklist = loadPostDeployChecklist;

/**
 * Copy text to clipboard
 */
function copyToClipboard(text, button) {
    // Handle both direct text and event-based calls
    let textToCopy = text;
    let buttonElement = button;
    
    // If called from onclick with just text, button will be the element
    if (typeof text === 'string' && button && button.tagName) {
        textToCopy = text;
        buttonElement = button;
    }
    
    navigator.clipboard.writeText(textToCopy).then(() => {
        if (buttonElement && buttonElement.innerHTML !== undefined) {
            const originalText = buttonElement.innerHTML;
            buttonElement.innerHTML = '✅ Copied!';
            buttonElement.style.background = 'var(--success)';
            buttonElement.style.color = 'var(--text-primary)';
            setTimeout(() => {
                buttonElement.innerHTML = originalText;
                buttonElement.style.background = 'var(--bg-elevated)';
                buttonElement.style.color = 'var(--text-secondary)';
            }, 2000);
        }
    }).catch(err => {
        console.error('Failed to copy:', err);
        alert('Failed to copy to clipboard. Please copy manually.');
    });
}

// Make copyToClipboard available globally for onclick handlers
window.copyToClipboard = copyToClipboard;

