// COST TRACKER — Settings page cost management + Deployment Manager budget alert
// ============================================================================

async function loadCostSettings() {
    try {
        const resp = await fetch('/api/costs/settings');
        const data = await resp.json();
        if (data.success) {
            const budgetInput = document.getElementById('budget-threshold');
            if (budgetInput) budgetInput.value = data.budget_threshold || 500;
        }
    } catch (e) {
        console.error('Error loading cost settings:', e);
    }
}

async function saveCostSettings() {
    const budgetInput = document.getElementById('budget-threshold');
    const payload = {
        budget_threshold: parseFloat(budgetInput?.value) || 500,
    };
    try {
        const resp = await fetch('/api/costs/settings', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });
        if (resp.ok && typeof showMessage === 'function') {
            showMessage('Cost settings saved', 'success');
        }
    } catch (e) {
        console.error('Error saving cost settings:', e);
    }
}

async function loadCostProjectSelector() {
    const selector = document.getElementById('cost-project-selector');
    if (!selector) return;

    // Restore last-refreshed timestamp from cache
    const btn = document.getElementById('cost-refresh-btn');
    const cachedTime = localStorage.getItem('cost_last_refreshed');
    if (btn && cachedTime) {
        btn.textContent = `Refresh Costs — last updated ${cachedTime}`;
    }

    try {
        const resp = await fetch('/api/costs/projects');
        const data = await resp.json();
        if (!data.success || !data.projects.length) {
            selector.innerHTML = '<option value="">No projects found</option>';
            _showCostEmptyState(true);
            return;
        }

        _showCostEmptyState(false);
        let html = '';
        const active = data.projects.filter(p => p.status === 'active');
        const destroyed = data.projects.filter(p => p.status === 'destroyed');

        if (active.length) {
            html += '<optgroup label="Active">';
            active.forEach(p => {
                html += `<option value="${p.name}" data-status="active">[Active] ${p.name} (${p.deployment_type})</option>`;
            });
            html += '</optgroup>';
        }
        if (destroyed.length) {
            html += '<optgroup label="Destroyed">';
            destroyed.forEach(p => {
                html += `<option value="${p.name}" data-status="destroyed">[Destroyed] ${p.name} (${p.deployment_type})</option>`;
            });
            html += '</optgroup>';
        }

        selector.innerHTML = html;
        // Auto-select first active, or first overall
        if (active.length) selector.value = active[0].name;

        // Show awaiting message immediately if a project is selected
        if (selector.value) {
            const container = document.getElementById('cost-summary-cards');
            if (container && !container.innerHTML.trim()) {
                container.innerHTML = `
                    <div class="callout callout--warning" style="margin: 0; grid-column: 1 / -1;">
                        <strong>Awaiting cost data from AWS Cost Explorer.</strong><br>
                        Cost data typically takes 24-48 hours to appear after deployment. Click "Refresh Costs" to check for updates.
                    </div>
                `;
            }
        }
    } catch (e) {
        console.error('Error loading cost projects:', e);
        selector.innerHTML = '<option value="">Error loading projects</option>';
    }
}

async function loadProjectCosts(forceRefresh = false) {
    const selector = document.getElementById('cost-project-selector');
    const project = (selector && selector.value) || 'account';
    const btn = document.getElementById('cost-refresh-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Refreshing...'; }

    try {
        const url = `/api/costs/summary?project=${encodeURIComponent(project)}${forceRefresh ? '&force=true' : ''}`;
        const resp = await fetch(url);
        const data = await resp.json();

        if (!data.success) {
            if (btn) { btn.disabled = false; btn.textContent = 'Refresh Costs — failed'; }
            return;
        }

        renderCostSummaryCards(data);

        const actualHasData = data.actual_costs?.available && data.actual_costs.total > 0.01;
        const untrackedCallout = document.getElementById('cost-untracked-callout');
        if (actualHasData) {
            renderBudgetProgressBar(data.budget);
            renderCostTrend(data.actual_costs);
            renderCostBreakdown(data);
            if (untrackedCallout) untrackedCallout.style.display = '';
        } else {
            if (untrackedCallout) untrackedCallout.style.display = 'none';
            // Hide budget bar, trend, breakdown when no actual data
            const budgetSection = document.getElementById('cost-budget-bar-section');
            const trendSection = document.getElementById('cost-trend-section');
            const breakdownSection = document.getElementById('cost-breakdown-section');
            if (budgetSection) budgetSection.style.display = 'none';
            if (trendSection) trendSection.style.display = 'none';
            if (breakdownSection) breakdownSection.style.display = 'none';
        }
        // Remove stale error callouts
        const oldCallout = document.getElementById('cost-error-callout');
        if (oldCallout) oldCallout.remove();

        if (btn) {
            btn.disabled = false;
            const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            btn.textContent = `Refresh Costs — last updated ${now}`;
            localStorage.setItem('cost_last_refreshed', now);
        }
        // M-Redesign Agent 3 — operator-facing toast only on explicit
        // refreshes (forceRefresh=true), not silent auto-loads.
        if (forceRefresh && APP && APP.toast) APP.toast('Cost data refreshed', 'success', 2000);
    } catch (e) {
        console.error('Error loading project costs:', e);
        if (btn) { btn.disabled = false; btn.textContent = 'Refresh Costs — error'; }
        if (forceRefresh && APP && APP.toast) APP.toast('Cost refresh failed', 'danger', 6000);
    }
}

function refreshCosts() {
    loadProjectCosts(true);
}

function renderCostSummaryCards(data) {
    const container = document.getElementById('cost-summary-cards');
    if (!container) return;

    const actual = data.actual_costs || {};
    const budget = data.budget || {};
    const actualHasData = actual.available && actual.total > 0.01;

    // If no actual Cost Explorer data, show a waiting state instead of estimates
    if (!actualHasData) {
        container.innerHTML = `
            <div class="callout callout--warning" style="margin: 0;">
                <strong>Awaiting cost data from AWS Cost Explorer.</strong><br>
                Cost data typically takes 24-48 hours to appear after deployment. Click "Refresh Costs" to check for updates.
            </div>
        `;
        return;
    }

    // Actual Cost Explorer data is available — render real figures
    const totalSpend = actual.total;
    const daysWithCost = (actual.daily_costs || []).filter(d => d.total > 0).length;
    const dailyAvg = daysWithCost > 0 ? totalSpend / daysWithCost : 0;

    const budgetRemaining = budget.threshold > 0 ? budget.remaining : null;
    const budgetState = budget.used_percent >= 100 ? 'danger'
        : budget.used_percent >= 80 ? 'warning'
        : (budget.threshold > 0 ? 'success' : '');

    // Projected monthly based on actual daily average
    const estMonthly = dailyAvg * 30;

    // Phase 3d — render four-up summary as a spec-list (replaces the
    // legacy 4-card grid). Each row is read-only; the value column gets
    // the cost figure (mono / tabular-nums) and the hint column gets the
    // supporting context (e.g. "Actual (Cost Explorer)" or
    // "12 days with charges"). The Budget Remaining row carries a
    // data-cost-state so the value paints success/warning/danger.
    const row = (key, value, hint, opts) => {
        opts = opts || {};
        const stateAttr = opts.state ? ` data-cost-state="${opts.state}"` : '';
        return `
            <div class="spec-row" data-readonly="true" data-cost-row="${escapeHtml(opts.dataKey || key.toLowerCase().replace(/\s+/g, '_'))}"${stateAttr}>
                <div class="spec-row__head">
                    <dt class="spec-row__key">${escapeHtml(key)}</dt>
                    <dd class="spec-row__value spec-row__value--mono spec-row__value--strong">${value}</dd>
                    <dd class="spec-row__hint">${escapeHtml(hint)}</dd>
                    <span class="spec-row__action" aria-hidden="true"></span>
                </div>
            </div>`;
    };

    container.innerHTML = `
        <dl class="spec-list spec-list--inset" aria-label="Cost summary">
            ${row('Total Spend', `$${totalSpend.toFixed(2)}`, 'Actual (Cost Explorer)', { dataKey: 'total' })}
            ${row('Daily Average', `$${dailyAvg.toFixed(2)}`, `${daysWithCost} day${daysWithCost !== 1 ? 's' : ''} with charges`, { dataKey: 'daily_avg' })}
            ${row('Budget Remaining',
                budgetRemaining !== null ? `$${budgetRemaining.toFixed(2)}` : 'No budget set',
                budget.threshold > 0 ? `of $${budget.threshold} budget` : 'Set in settings above',
                { dataKey: 'budget_remaining', state: budgetState })}
            ${row('Est. Monthly', `$${estMonthly.toFixed(2)}`, 'projected from actual daily avg', { dataKey: 'est_monthly' })}
        </dl>
    `;
}

function renderBudgetProgressBar(budget) {
    const section = document.getElementById('cost-budget-bar-section');
    if (!section || !budget || budget.threshold <= 0) {
        if (section) section.style.display = 'none';
        return;
    }

    section.style.display = 'block';
    const pct = Math.min(budget.used_percent, 100);
    const fillClass = budget.used_percent >= 100 ? 'cost-budget-bar__fill--danger'
        : budget.used_percent >= 80 ? 'cost-budget-bar__fill--warning'
        : 'cost-budget-bar__fill--ok';

    const fill = document.getElementById('cost-budget-fill');
    const label = document.getElementById('cost-budget-label');
    const pctSpan = document.getElementById('cost-budget-pct');

    if (fill) {
        fill.style.width = pct + '%';
        fill.className = 'cost-budget-bar__fill ' + fillClass;
    }
    if (label) {
        label.textContent = `$${(budget.threshold - budget.remaining).toFixed(2)} of $${budget.threshold}`;
    }
    if (pctSpan) {
        pctSpan.textContent = budget.used_percent.toFixed(1) + '%';
    }
}

function renderCostTrend(actualCosts) {
    const section = document.getElementById('cost-trend-section');
    const chart = document.getElementById('cost-trend-chart');
    if (!section || !chart) return;

    if (!actualCosts?.available || !actualCosts.daily_costs?.length) {
        section.style.display = 'none';
        return;
    }

    // Show last 14 days — but hide if all days are $0
    const days = actualCosts.daily_costs.slice(-14);
    const hasNonZero = days.some(d => d.total > 0.001);
    if (!hasNonZero) {
        section.style.display = 'none';
        return;
    }

    const maxCost = Math.max(...days.map(d => d.total), 0.01);

    section.style.display = 'block';
    chart.innerHTML = days.map(day => {
        const pct = (day.total / maxCost) * 100;
        const dateLabel = new Date(day.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        return `
            <div class="cost-trend-row">
                <span class="cost-trend-date">${dateLabel}</span>
                <div class="cost-trend-bar-container">
                    <div class="cost-trend-bar" style="width: ${pct}%;"></div>
                </div>
                <span class="cost-trend-value">$${day.total.toFixed(2)}</span>
            </div>
        `;
    }).join('');
}

function renderCostBreakdown(data) {
    const section = document.getElementById('cost-breakdown-section');
    const tableDiv = document.getElementById('cost-breakdown-table');
    if (!section || !tableDiv) return;

    const actual = data.actual_costs || {};
    const serviceBreakdown = actual?.available ? _aggregateServiceCosts(actual.daily_costs) : {};

    if (!Object.keys(serviceBreakdown).length) {
        section.style.display = 'none';
        return;
    }

    section.style.display = 'block';
    const serviceTotal = Object.values(serviceBreakdown).reduce((s, v) => s + v, 0);
    let rows = '';

    Object.entries(serviceBreakdown)
        .sort((a, b) => b[1] - a[1])
        .forEach(([service, total]) => {
            const pct = serviceTotal > 0 ? ((total / serviceTotal) * 100) : 0;
            const daily = total / 30;
            rows += `
                <tr>
                    <td>${service}</td>
                    <td>$${daily.toFixed(2)}</td>
                    <td>$${total.toFixed(2)}</td>
                    <td>
                        <span class="cost-pct-bar" style="width: ${pct}px;"></span>
                        ${pct.toFixed(0)}%
                    </td>
                </tr>
            `;
        });

    tableDiv.innerHTML = `
        <table class="cost-breakdown-table">
            <thead>
                <tr>
                    <th>Service</th>
                    <th>Daily Avg</th>
                    <th>Total (30d)</th>
                    <th>%</th>
                </tr>
            </thead>
            <tbody>${rows}</tbody>
        </table>
    `;
}

function renderCostErrors(data) {
    // Remove any existing error callout
    const existing = document.getElementById('cost-error-callout');
    if (existing) existing.remove();

    const actual = data.actual_costs || {};
    const container = document.getElementById('cost-summary-cards');
    if (!container) return;

    let html = '';
    if (actual.error === 'cost_explorer_not_enabled') {
        html = `<div id="cost-error-callout" class="callout callout--warning" style="margin-top: 15px;">
            <strong>AWS Cost Explorer not enabled.</strong> ${actual.error_message || ''}
            <br><a href="https://console.aws.amazon.com/cost-management/home#/cost-explorer" target="_blank" style="color: inherit;">Enable Cost Explorer in AWS Console</a> — data appears after 24 hours. Showing estimates only.
        </div>`;
    } else if (actual.error === 'access_denied') {
        html = `<div id="cost-error-callout" class="callout callout--warning" style="margin-top: 15px;">
            <strong>Missing IAM permission.</strong> Add <code>ce:GetCostAndUsage</code> to your IAM policy. Showing estimates only.
        </div>`;
    } else if (actual.stale) {
        html = `<div id="cost-error-callout" class="callout callout--info" style="margin-top: 15px;">
            <strong>Stale data</strong> — cached from ${actual.cache_age_minutes} minutes ago. ${actual.error || ''}
        </div>`;
    } else if (actual.available && (!actual.daily_costs || actual.daily_costs.every(d => d.total === 0))) {
        const est = data.estimated_costs || {};
        const isActive = est.is_active;
        const hoursRunning = est.hours_running || 0;

        if (!isActive && hoursRunning > 0) {
            // Destroyed project with no Cost Explorer data — likely deployed before tagging was added
            html = `<div id="cost-error-callout" class="callout callout--info" style="margin-top: 15px;">
                <strong>No Cost Explorer data for this project.</strong> Resources may not have been tagged with the <code>Project</code> tag during this engagement. Showing estimates calculated from instance types and uptime.
            </div>`;
        } else if (isActive && hoursRunning < 48) {
            // New active deployment — Cost Explorer has 24-48h delay
            html = `<div id="cost-error-callout" class="callout callout--info" style="margin-top: 15px;">
                <strong>No actual cost data yet.</strong> AWS Cost Explorer data typically takes 24-48 hours to appear for new deployments. Showing estimates below.
            </div>`;
        } else if (isActive) {
            // Active deployment past 48h with no data — tag mismatch
            html = `<div id="cost-error-callout" class="callout callout--warning" style="margin-top: 15px;">
                <strong>No Cost Explorer data found.</strong> Verify that deployed resources have the <code>Project</code> tag matching this project name. Showing estimates below.
            </div>`;
        }
    }

    if (html) {
        container.insertAdjacentHTML('afterend', html);
    }
}

function _aggregateServiceCosts(dailyCosts) {
    const totals = {};
    (dailyCosts || []).forEach(day => {
        Object.entries(day.by_service || {}).forEach(([svc, amt]) => {
            totals[svc] = (totals[svc] || 0) + amt;
        });
    });
    return totals;
}

function _showCostEmptyState(show) {
    const empty = document.getElementById('cost-empty-state');
    const cards = document.getElementById('cost-summary-cards');
    const budgetBar = document.getElementById('cost-budget-bar-section');
    const trend = document.getElementById('cost-trend-section');
    const breakdown = document.getElementById('cost-breakdown-section');

    if (empty) empty.style.display = show ? 'block' : 'none';
    if (cards) cards.style.display = show ? 'none' : '';
    // These stay hidden until render functions explicitly show them with data
    if (show) {
        if (budgetBar) budgetBar.style.display = 'none';
        if (trend) trend.style.display = 'none';
        if (breakdown) breakdown.style.display = 'none';
    }
}

/**
 * Budget alert banner for Deployment Manager page.
 * Lightweight — just fetches budget status and shows/hides a callout.
 */
async function loadBudgetAlert() {
    const alertDiv = document.getElementById('cost-budget-alert');
    if (!alertDiv) return;

    try {
        const resp = await fetch('/api/costs/budget-alert');
        const data = await resp.json();

        if (!data.success || !data.enabled || data.level === 'ok') {
            alertDiv.style.display = 'none';
            return;
        }

        const isOver = data.level === 'danger';
        const cls = isOver ? 'callout--danger' : 'callout--warning';
        const msg = isOver
            ? `Budget Exceeded: Spending ($${data.total_spend.toFixed(2)}) has exceeded your $${data.threshold} monthly budget by $${Math.abs(data.remaining).toFixed(2)}.`
            : `Budget Warning: ${data.used_percent.toFixed(0)}% of your $${data.threshold} monthly budget used ($${data.total_spend.toFixed(2)}).`;

        alertDiv.innerHTML = `
            <div class="callout ${cls}">
                <strong>${isOver ? 'Budget Exceeded' : 'Budget Warning'}</strong> — ${msg}
                <a href="#" onclick="APP.navigateTo('settings'); return false;" style="color: inherit; text-decoration: underline; margin-left: 8px;">View details in Settings</a>
            </div>
        `;
        alertDiv.style.display = 'block';
    } catch (e) {
        alertDiv.style.display = 'none';
    }
}

// ============================================================================
// HOST SETUP CHECK (SSM-based bootstrap validation)
// ============================================================================

let _setupCheckPollTimer = null;

/**
 * Load cached setup check results from localStorage (lightweight, no SSM).
 */
async function loadCachedSetupCheck() {
    const contentEl = document.getElementById('setup-check-content');
    if (!contentEl) return;

    // Don't reload from cache if a check is currently running -- would wipe the spinner
    if (_setupCheckPollTimer) return;
    const btn = document.getElementById('setup-check-btn');
    if (btn && btn.disabled) return;

    // Don't reload if content is already rendered with hosts -- avoids re-render flashing
    // which makes the list "disappear" during scrolling/interaction
    if (contentEl.querySelector('details')) return;

    // Try localStorage first
    const activeSession = document.querySelector('[data-details-id$="-setup-check"]');
    if (!activeSession) return;

    const project = _getSetupCheckProject();
    if (!project) return;

    const cacheKey = `setupCheck_${project}`;
    const cached = localStorage.getItem(cacheKey);
    if (cached) {
        try {
            const data = JSON.parse(cached);
            renderSetupCheckResults(data);
        } catch (e) { /* ignore bad cache */ }
        return;
    }

    // Try server cache
    try {
        const resp = await fetch(`${API_BASE}/setup-check/status?project=${encodeURIComponent(project)}`);
        const data = await resp.json();
        if (data.success && data.cached && data.hosts && data.hosts.length > 0) {
            localStorage.setItem(cacheKey, JSON.stringify(data));
            renderSetupCheckResults(data);
        }
    } catch (e) {
        console.log('[SetupCheck] No cached results available');
    }
}

/**
 * Trigger a fresh SSM setup check.
 */
async function runSetupCheck(projectNameArg) {
    const contentEl = document.getElementById('setup-check-content');
    const btn = document.getElementById('setup-check-btn');
    if (!contentEl) return;

    const project = projectNameArg || contentEl.dataset?.projectName || _getSetupCheckProject();
    if (!project) {
        contentEl.innerHTML = '<p class="t-muted">No active deployment found.</p>';
        return;
    }

    // Get region from per-project cache or use default
    let region = 'eu-central-1';
    try {
        const pd = getProjectData(project);
        if (pd && pd.outputs && pd.outputs.region) {
            region = pd.outputs.region;
        }
    } catch (e) { /* use default */ }

    if (btn) { btn.disabled = true; btn.textContent = 'Checking...'; }
    contentEl.innerHTML = `
        <div style="display: flex; align-items: center; gap: 8px; padding: 10px 0;">
            <div style="width: 16px; height: 16px; border: 2px solid var(--accent); border-top-color: transparent; border-radius: 50%; animation: spin 1s linear infinite;"></div>
            <span>Sending SSM commands to all instances... This may take 15-30 seconds.</span>
        </div>`;

    try {
        const resp = await fetch(`${API_BASE}/setup-check/run`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ project, region }),
        });
        const data = await resp.json();
        if (data.success && data.check_id) {
            pollSetupCheck(data.check_id, project);
        } else {
            contentEl.innerHTML = `<p style="color: var(--error);">Failed to start check: ${data.error || 'Unknown error'}</p>`;
            if (btn) { btn.disabled = false; btn.textContent = 'Check Setup'; }
        }
    } catch (e) {
        contentEl.innerHTML = `<p style="color: var(--error);">Network error: ${e.message}</p>`;
        if (btn) { btn.disabled = false; btn.textContent = 'Check Setup'; }
    }
}

/**
 * Poll for in-flight check results.
 */
function pollSetupCheck(checkId, project) {
    if (_setupCheckPollTimer) clearTimeout(_setupCheckPollTimer);

    const contentEl = document.getElementById('setup-check-content');
    const btn = document.getElementById('setup-check-btn');

    const doPoll = async () => {
        try {
            const resp = await fetch(`${API_BASE}/setup-check/poll?check_id=${encodeURIComponent(checkId)}`);
            const data = await resp.json();

            if (data.status === 'running') {
                _setupCheckPollTimer = setTimeout(doPoll, 5000);
                return;
            }

            // Complete -- clear poll timer so future cache loads aren't blocked
            _setupCheckPollTimer = null;
            if (data.success && data.hosts) {
                const cacheKey = `setupCheck_${project}`;
                localStorage.setItem(cacheKey, JSON.stringify(data));
                renderSetupCheckResults(data);
            } else {
                if (contentEl) contentEl.innerHTML = `<p style="color: var(--danger-text);">Check failed: ${data.error || 'Unknown error'}</p>`;
            }
        } catch (e) {
            _setupCheckPollTimer = null;
            if (contentEl) contentEl.innerHTML = `<p style="color: var(--danger-text);">Poll error: ${e.message}</p>`;
        }
        if (btn) { btn.disabled = false; btn.textContent = 'Check Setup'; }
    };

    _setupCheckPollTimer = setTimeout(doPoll, 5000);
}

/**
 * Render setup check results into the UI.
 */
function renderSetupCheckResults(data) {
    const contentEl = document.getElementById('setup-check-content');
    const badgeEl = document.getElementById('setup-check-badge');
    const lastCheckedEl = document.getElementById('setup-check-last-checked');
    const btn = document.getElementById('setup-check-btn');

    if (!contentEl) return;
    if (btn) { btn.disabled = false; btn.textContent = 'Check Setup'; }

    const hosts = data.hosts || [];
    const summary = data.summary || {};
    const checkedAt = data.checked_at;

    // Update badge
    if (badgeEl && summary.total) {
        const healthy = summary.healthy || 0;
        const total = summary.total || 0;
        let badgeColor = 'var(--success)';
        if (healthy === 0) badgeColor = 'var(--error)';
        else if (healthy < total) badgeColor = 'var(--warning)';
        badgeEl.innerHTML = `<span style="background: ${badgeColor}; color: var(--text-inverse); padding: 2px 10px; border-radius: 10px;">${healthy}/${total} healthy</span>`;
    }

    // Update last checked
    if (lastCheckedEl && checkedAt) {
        const d = new Date(checkedAt);
        lastCheckedEl.textContent = `Last checked: ${d.toLocaleString()}`;
    }

    if (hosts.length === 0) {
        contentEl.innerHTML = '<p style="color: var(--text-muted); font-style: italic;">No instances found.</p>';
        return;
    }

    // Role display names
    const roleLabels = {
        'c2_server': 'Team Server', 'teamserver': 'Team Server',
        'redirector': 'Redirector', 'bastion': 'Bastion',
        'attackbox': 'Attack Box', 'attack_box': 'Attack Box',
        'jumpbox': 'Jumpbox', 'dc': 'Domain Controller',
    };

    let html = '';
    for (const host of hosts) {
        const sd = host.setup_data;
        const roleLabel = roleLabels[host.role] || host.role;

        // Determine host-level icon and status
        let icon, statusText, rowColor;
        if (host.check_status === 'no_status_file') {
            icon = '⏳'; statusText = 'Bootstrap not started yet'; rowColor = 'var(--text-muted)';
        } else if (host.check_status === 'ssm_timeout') {
            icon = '⚠️'; statusText = 'SSM timed out'; rowColor = 'var(--warning)';
        } else if (host.check_status === 'ssm_send_failed' || host.check_status === 'ssm_error') {
            icon = '🔘'; statusText = 'SSM not responding'; rowColor = 'var(--text-muted)';
        } else if (host.check_status === 'ssm_failed') {
            icon = '🔘'; statusText = host.message || 'Instance not reachable'; rowColor = 'var(--text-muted)';
        } else if (host.check_status === 'parse_error') {
            icon = '⚠️'; statusText = 'Could not parse status'; rowColor = 'var(--warning)';
        } else if (host.check_status === 'ok') {
            icon = '✅'; statusText = host.message || 'Healthy'; rowColor = 'var(--success)';
        } else if (host.check_status === 'warning') {
            icon = '⚠️'; statusText = host.message || 'Warning'; rowColor = 'var(--warning)';
        } else if (sd) {
            if (sd.status === 'complete') { icon = '✅'; statusText = ''; rowColor = 'var(--success)'; }
            else if (sd.status === 'partial') { icon = '❌'; statusText = `${sd.failed} step(s) failed`; rowColor = 'var(--error)'; }
            else if (sd.status === 'running') { icon = '🔄'; statusText = 'Setup running...'; rowColor = 'var(--accent)'; }
            else { icon = '⚠️'; statusText = sd.status; rowColor = 'var(--warning)'; }
        } else {
            icon = '🔘'; statusText = host.message || 'Unknown'; rowColor = 'var(--text-muted)';
        }

        // Step count and duration
        let stepInfo = '';
        let durationInfo = '';
        if (sd && sd.steps) {
            const ok = sd.steps.filter(s => s.status === 'ok' || s.status === 'warning').length;
            stepInfo = `${ok}/${sd.total_steps} steps`;
            const totalSecs = sd.steps.reduce((sum, s) => sum + (s.duration_s || 0), 0);
            if (totalSecs >= 60) {
                durationInfo = `${Math.floor(totalSecs / 60)}m ${totalSecs % 60}s`;
            } else {
                durationInfo = `${totalSecs}s`;
            }
        }

        // Build expandable step detail
        let stepDetailHtml = '';
        if (sd && sd.steps && sd.steps.length > 0) {
            stepDetailHtml = '<div style="margin-top: 8px; padding-left: 24px;">';
            for (const step of sd.steps) {
                let sIcon = '✅';
                if (step.status === 'failed') sIcon = '❌';
                else if (step.status === 'warning') sIcon = '⚠️';
                else if (step.status === 'skipped') sIcon = '⏭️';
                else if (step.status === 'running') sIcon = '🔄';

                const dur = step.duration_s != null ? `${step.duration_s}s` : '';
                const msg = step.message ? `<span style="color: var(--danger-text); margin-left: 8px;">${step.message}</span>` : '';
                stepDetailHtml += `
                    <div style="display: flex; align-items: center; gap: 8px; padding: 4px 0;">
                        <span>${sIcon}</span>
                        <span style="min-width: 24px; color: var(--text-muted);">${step.step}.</span>
                        <span style="color: var(--text-primary);">${step.name}</span>
                        <span style="color: var(--text-muted); margin-left: auto;">${dur}</span>
                        ${msg}
                    </div>`;
            }
            stepDetailHtml += '</div>';
        }

        // Build detail from live check or status file when no steps exist
        if (!stepDetailHtml && sd) {
            const services = sd.detected_services || (typeof sd.services === 'string' ? sd.services.split(',').filter(Boolean) : sd.services) || [];
            // Also show key=value fields from bootstrap status files
            if (services.length === 0 && sd.status === 'found') {
                stepDetailHtml = '<div style="margin-top: 8px; padding-left: 24px;">';
                for (const [k, v] of Object.entries(sd)) {
                    if (['status', 'status_file', 'detected_services', 'services'].includes(k)) continue;
                    const valDisplay = v || '(empty)';
                    const valColor = v === 'needs_activation' ? 'var(--warning-text)' : 'var(--text-secondary)';
                    stepDetailHtml += `
                        <div style="display: flex; align-items: center; gap: 8px; padding: 4px 0;">
                            <span>${v ? '✅' : '⚠️'}</span>
                            <span style="color: var(--text-primary);">${k}:</span>
                            <span style="color: ${valColor};">${valDisplay}</span>
                        </div>`;
                }
                if (sd.status_file) {
                    stepDetailHtml += `
                        <div style="display: flex; align-items: center; gap: 8px; padding: 4px 0;">
                            <span>📄</span>
                            <span style="color: var(--text-muted);">Status file: ${sd.status_file}</span>
                        </div>`;
                }
                stepDetailHtml += '</div>';
            }
            if (services.length > 0) {
                const serviceLabels = {
                    teamserver: 'Cobalt Strike Team Server', csrestapi: 'CS REST API',
                    nginx: 'Nginx Redirector', sshd: 'SSH Server', ssh: 'SSH Server',
                    rdp: 'Remote Desktop (RDP)', winrm: 'WinRM',
                    cs_installed: 'Cobalt Strike Installed', cs_client: 'CS Client Installed',
                    goad_installed: 'GOAD Installed', tools_dir: 'Tools Directory (C:\\Tools)',
                    powersploit: 'PowerSploit',
                };
                stepDetailHtml = '<div style="margin-top: 8px; padding-left: 24px;">';
                for (const svc of services) {
                    const label = serviceLabels[svc] || svc;
                    stepDetailHtml += `
                        <div style="display: flex; align-items: center; gap: 8px; padding: 4px 0;">
                            <span>✅</span>
                            <span style="color: var(--text-primary);">${label}</span>
                        </div>`;
                }
                if (sd.uptime) {
                    stepDetailHtml += `
                        <div style="display: flex; align-items: center; gap: 8px; padding: 4px 0;">
                            <span>🕐</span>
                            <span style="color: var(--text-muted);">Up since: ${sd.uptime}</span>
                        </div>`;
                }
                if (sd.status_file) {
                    stepDetailHtml += `
                        <div style="display: flex; align-items: center; gap: 8px; padding: 4px 0;">
                            <span>📄</span>
                            <span style="color: var(--text-muted);">Status file: ${sd.status_file}</span>
                        </div>`;
                }
                stepDetailHtml += '</div>';
            }
        }

        const hasDetail = stepDetailHtml !== '';
        const rowTextColor = host.check_status === 'ok' ? 'var(--success-text)' :
                             host.check_status === 'warning' || host.check_status === 'parse_error' || host.check_status === 'ssm_timeout' ? 'var(--warning-text)' :
                             host.check_status === 'no_status_file' ? 'var(--text-muted)' :
                             rowColor.includes('success') ? 'var(--success-text)' :
                             rowColor.includes('warning') ? 'var(--warning-text)' :
                             rowColor.includes('error') ? 'var(--danger-text)' :
                             rowColor.includes('accent') ? 'var(--info-text)' : 'var(--text-muted)';
        html += `
            <details style="margin-bottom: 6px; border-bottom: 1px solid var(--border); padding-bottom: 6px;">
                <summary style="cursor: pointer; display: flex; align-items: center; gap: 10px; padding: 8px 4px; list-style: none; flex-wrap: wrap;">
                    <span>${icon}</span>
                    <strong style="color: var(--text-primary);">${host.name}</strong>
                    <span style="background: var(--bg-elevated); padding: 2px 8px; border-radius: 4px; color: var(--text-secondary);">${roleLabel}</span>
                    ${stepInfo ? `<span style="color: var(--text-secondary);">${stepInfo}</span>` : ''}
                    ${durationInfo ? `<span style="color: var(--text-muted);">${durationInfo}</span>` : ''}
                    ${statusText ? `<span style="color: ${rowTextColor};">${statusText}</span>` : ''}
                </summary>
                ${hasDetail ? stepDetailHtml : '<div style="padding: 8px 0 8px 24px; color: var(--text-muted);">No step details available</div>'}
            </details>`;
    }

    contentEl.innerHTML = html;
}

/**
 * Get the project name for setup check from the current session context.
 */
function _getSetupCheckProject() {
    // Try data-project-name on the setup check content div
    const setupDiv = document.getElementById('setup-check-content');
    if (setupDiv?.dataset?.projectName) return setupDiv.dataset.projectName;

    // Try the current deployment project
    if (window.currentDeploymentProject) return window.currentDeploymentProject;

    // Try per-project cache — return first cached project name
    try {
        const keys = Object.keys(projectDataCache);
        if (keys.length > 0) return keys[0];
    } catch (e) { /* ignore */ }

    // Try sessionStorage
    const stored = sessionStorage.getItem('activeDeploymentProject');
    if (stored) return stored;

    // Try to extract from session details card
    const cards = document.querySelectorAll('[data-details-id]');
    for (const card of cards) {
        const id = card.getAttribute('data-details-id') || '';
        if (id.endsWith('-setup-check')) {
            const sessionId = id.replace('-setup-check', '');
            const resourceDiv = document.getElementById(`${sessionId}-resources`);
            if (resourceDiv) {
                const loadBtn = resourceDiv.querySelector('button[onclick*="loadProjectResources"]');
                if (loadBtn) {
                    const match = loadBtn.getAttribute('onclick').match(/loadProjectResources\('([^']+)'/);
                    if (match) return match[1];
                }
            }
        }
    }
    return null;
}

// ============================================================================
// TERMINAL — Local shell + SSH sessions via WebSocket + xterm.js
// ============================================================================

const TERMINAL = {
    sessions: {},       // id → { term, ws, type, label }
    activeId: null,
    nextId: 1,
    maxSessions: 10,
    deployments: [],
    selectedDeployment: null,
    _initialized: false,
    // Uses shared global cache: _globalOutputsCache
    get _outputsCache() { return _globalOutputsCache; },

    _refreshInterval: null,

    async init() {
        // Reset instance buttons and selection on every init
        const btnContainer = document.getElementById('terminal-instance-buttons');
        const btnRow = document.getElementById('terminal-instance-btn-row');
        if (btnContainer) btnContainer.style.display = 'none';
        if (btnRow) btnRow.innerHTML = '';
        this.selectedDeployment = null;

        // Load deployments and pre-fetch all outputs in parallel
        await this._loadDeployments();
        this._prefetchAllOutputs();

        // Start background refresh (every 60s while on Terminal page)
        this._startBackgroundRefresh();

        // Check if xterm.js loaded
        if (typeof Terminal === 'undefined') {
            const warn = document.getElementById('terminal-dep-warning');
            if (warn) { warn.style.display = 'block'; warn.innerHTML = '<strong>xterm.js not loaded.</strong> Check your internet connection (loaded from CDN).'; }
        }

        // Re-focus active session if returning to tab, or auto-open local shell on first visit
        if (this.activeId && this.sessions[this.activeId]) {
            this.sessions[this.activeId].term.focus();
        } else if (Object.keys(this.sessions).length === 0 && typeof Terminal !== 'undefined') {
            this.openLocal();
        }
        this._initialized = true;
    },

    _prefetchAllOutputs() {
        // Fetch outputs for every deployment in parallel — populates cache silently
        this.deployments.forEach(d => {
            const name = d._filename || '';
            if (name && !this._outputsCache[name]) {
                this._fetchOutputs(name); // fire-and-forget, populates cache
            }
        });
    },

    _startBackgroundRefresh() {
        if (this._refreshInterval) clearInterval(this._refreshInterval);
        this._refreshInterval = setInterval(() => {
            // Only refresh if we're on the terminal page
            if (APP.currentPage !== 'terminal') return;
            this.deployments.forEach(d => {
                const name = d._filename || '';
                if (name) this._fetchOutputs(name); // silent background update
            });
        }, 60000);
    },

    stopBackgroundRefresh() {
        if (this._refreshInterval) {
            clearInterval(this._refreshInterval);
            this._refreshInterval = null;
        }
    },

    async _checkRestApiBanner() {
        const banner = document.getElementById('terminal-rest-api-banner');
        const textEl = document.getElementById('terminal-rest-api-text');
        if (!banner || !textEl) return;

        try {
            const resp = await fetch('/api/beacon/health');
            const data = await resp.json();
            if (data.status === 'connected' && data.authenticated) {
                banner.style.display = 'none';
                return;
            }
        } catch { /* not connected */ }

        // REST API not connected — find a C2 deployment to build the tunnel command
        let tunnelCmd = '';
        for (const dep of this.deployments) {
            const type = dep.deployment_type || '';
            if (!type.startsWith('c2-') && !type.startsWith('combined-')) continue;
            const name = dep._filename || '';
            const outputs = _getCachedOutputs(name);
            if (!outputs) continue;
            const tsIp = (outputs.c2_servers && outputs.c2_servers[0]?.private_ip) || outputs.teamserver_private_ip;
            const jumpHost = outputs.bastion_public_ip || outputs.jumpbox_public_ip;
            if (tsIp && jumpHost) {
                tunnelCmd = `ssh -L 50443:${tsIp}:50443 -i ~/.ssh/id_ed25519 -o StrictHostKeyChecking=no ubuntu@${jumpHost}`;
                break;
            }
        }

        banner.style.display = 'flex';
        if (tunnelCmd) {
            const escapedCmd = tunnelCmd.replace(/'/g, "\\'");
            textEl.innerHTML = `CS REST API not connected — <button class="btn btn-sm btn-warning" onclick="TERMINAL.openTunnel('REST API Tunnel', '${escapedCmd}')" style="margin-left: 8px;">Open REST API Tunnel</button>`;
        } else {
            textEl.textContent = 'CS REST API not connected — select a C2 deployment to see the tunnel command';
        }
    },

    async _loadDeployments() {
        const select = document.getElementById('terminal-deployment-select');
        if (!select) return;
        try {
            const resp = await fetch('/api/deploy/active');
            const data = await resp.json();
            this.deployments = data.deployments || [];

            select.innerHTML = '<option value="">-- Select a deployment --</option>';
            this.deployments.forEach((d, i) => {
                const name = d._filename || `Deployment ${i + 1}`;
                const type = d.deployment_type || 'unknown';
                const opt = document.createElement('option');
                opt.value = i;
                // 2026-05-19 — Fix 1: tag the filename so _syncSubPillSelectorToActive
                // can match by data-filename (the dropdown value is the array index).
                opt.dataset.filename = d._filename || '';
                opt.textContent = `${name} (${type})`;
                select.appendChild(opt);
            });
        } catch {
            select.innerHTML = '<option value="">Failed to load deployments</option>';
        }
    },

    // ── Cache management (delegates to shared global cache) ──
    _getCachedOutputs(projectName) {
        return _getCachedOutputs(projectName);
    },

    async _fetchOutputs(projectName) {
        return (await _fetchAndCacheOutputs(projectName)) || {};
    },

    invalidateCache(projectName) {
        _invalidateOutputsCache(projectName);
    },

    async onDeploymentSelected() {
        const select = document.getElementById('terminal-deployment-select');
        const btnContainer = document.getElementById('terminal-instance-buttons');
        const btnRow = document.getElementById('terminal-instance-btn-row');
        const idx = select?.value;

        if (!idx || idx === '') {
            this.selectedDeployment = null;
            if (btnContainer) btnContainer.style.display = 'none';
            return;
        }

        const deployment = this.deployments[parseInt(idx)];
        if (!deployment) return;
        this.selectedDeployment = deployment;

        const projectName = deployment._filename || '';

        // Always try cache first (pre-fetched on page load)
        const cached = this._getCachedOutputs(projectName);
        if (btnContainer) btnContainer.style.display = '';

        if (cached) {
            this._renderInstanceButtons(cached, btnRow);
            // Silent background refresh to catch state changes
            this._fetchOutputs(projectName).then(fresh => {
                if (this.selectedDeployment?._filename === projectName) {
                    this._renderInstanceButtons(fresh, btnRow);
                }
            });
            return;
        }

        // Cache miss (rare — prefetch hasn't completed yet). Fetch now.
        if (btnRow) btnRow.innerHTML = '<span style="color: var(--text-muted); font-size: 0.85em;">Fetching instances...</span>';
        const outputs = await this._fetchOutputs(projectName);

        this._renderInstanceButtons(outputs, btnRow);
    },

    // ── Open a local shell and execute a command ──
    openTunnel(label, command) {
        if (typeof Terminal === 'undefined') return;

        if (Object.keys(this.sessions).length >= this.maxSessions) {
            alert(`Session limit reached (max ${this.maxSessions}). Close a tab first.`);
            return;
        }

        const id = 'term_' + (this.nextId++);
        const wsProto = location.protocol === 'https:' ? 'wss:' : 'ws:';
        const ws = new WebSocket(`${wsProto}//${location.host}/api/terminal/local`);
        const term = this._createTerm(id, ws);

        ws.onopen = () => {
            ws.send(JSON.stringify({ type: 'init' }));
            this._sendResize(ws, term);
            // Wait for shell to be ready, then send the command
            setTimeout(() => {
                if (ws.readyState === WebSocket.OPEN) {
                    ws.send(command + '\n');
                }
            }, 500);
        };

        // Phase 3B.2 — record the operator that opened this session for
        // attribution in the tab strip.
        const opener = (APP.operator && APP.operator.current && APP.operator.current.id) || null;
        this.sessions[id] = { term, ws, type: 'tunnel', label, opener };
        this._addTab(id, label, opener);
        this._switchTo(id);
    },

    _renderInstanceButtons(outputs, btnRow) {
        if (!btnRow) return;
        const instances = [];
        const bastionIp = outputs.bastion_public_ip;
        // Prefer private IP for SSH (works via VPC peering on server, avoids SG restrictions on public IP)
        const bastionSshIp = outputs.bastion_private_ip || bastionIp;
        const jumpboxSshIp = outputs.jumpbox_private_ip || outputs.jumpbox_public_ip;

        if (bastionSshIp) {
            instances.push({ label: 'Bastion', host: bastionSshIp, user: 'ubuntu', bastion: null, icon: '🛡', state: outputs.bastion_state });
        }

        if (outputs.redirectors) {
            outputs.redirectors.forEach((r, i) => {
                if (r.private_ip) {
                    instances.push({ label: `Redir-${i + 1}`, host: r.private_ip, user: 'ubuntu', bastion: bastionSshIp, icon: '🔀', state: r.state });
                }
            });
        }

        if (outputs.c2_servers) {
            outputs.c2_servers.forEach((ts, i) => {
                if (ts.private_ip) {
                    instances.push({ label: `TeamSrv-${i + 1}`, host: ts.private_ip, user: 'ubuntu', bastion: bastionSshIp, icon: '🖥', state: ts.state });
                }
            });
        } else if (outputs.teamserver_private_ip) {
            instances.push({ label: 'Team Server', host: outputs.teamserver_private_ip, user: 'ubuntu', bastion: bastionSshIp || jumpboxSshIp, icon: '🖥', state: outputs.teamserver_state });
        }

        // Attack Box — Windows, no SSH. RDP access via the tunnel buttons.

        if (outputs.jumpbox_public_ip) {
            instances.push({ label: 'Jumpbox', host: jumpboxSshIp, user: 'ubuntu', bastion: null, icon: '🔑', state: outputs.jumpbox_state });
        }

        ['dc01', 'dc02', 'srv01', 'srv02', 'srv03', 'ws01'].forEach(vm => {
            if (outputs[vm + '_private_ip']) {
                instances.push({ label: vm.toUpperCase(), host: outputs[vm + '_private_ip'], user: 'ansible', bastion: outputs.jumpbox_public_ip, icon: '🏢', state: outputs[vm + '_state'] });
            }
        });

        function _esc(s) { return (s || '').replace(/'/g, "\\'").replace(/"/g, '&quot;'); }

        if (instances.length > 0) {
            let html = instances.map(inst => {
                const stateColor = inst.state === 'running' ? 'var(--terminal-success)' : inst.state === 'stopped' ? 'var(--terminal-danger)' : 'var(--terminal-warning)';
                const stateDot = inst.state ? `<span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${stateColor};margin-right:4px;" title="${inst.state}"></span>` : '';
                const disabled = inst.state === 'stopped' ? 'disabled style="opacity:0.5;pointer-events:none;"' : '';
                return `<button class="btn btn-sm btn-info" ${disabled} onclick="TERMINAL.openSSH('${_esc(inst.host)}', '${_esc(inst.user)}', ${inst.bastion ? "'" + _esc(inst.bastion) + "'" : 'null'}, '${_esc(inst.label)}')">${stateDot}${inst.icon} ${_esc(inst.label)}</button>`;
            }).join('');

            // Tunnel shortcut buttons — adapts to deployment type and server/local mode
            const tunnels = [];
            const keyPath = '~/.ssh/id_ed25519';
            const sshOpts = `-i ${keyPath} -o StrictHostKeyChecking=no`;
            const jumpboxIp = outputs.jumpbox_public_ip;

            const c2TsIp = outputs.c2_servers?.[0]?.private_ip || outputs.teamserver_private_ip;
            const goadTsIp = outputs.teamserver_private_ip;
            const tsIp = c2TsIp || goadTsIp;
            const abIp = outputs.attackbox_private_ip;

            // Tunnel commands adapt based on where they run:
            // - Laptop: SSH through bastion/jumpbox public IP (internet)
            // - Server: SSH through bastion/jumpbox private IP (VPC peering) or team server directly
            const bastionPrivate = outputs.bastion_private_ip;
            const jumpboxPrivate = outputs.jumpbox_private_ip;
            // Prefer private IP (works via peering on server), fall back to public (works from laptop)
            const tunnelHost = bastionPrivate || bastionIp || jumpboxPrivate || jumpboxIp;

            // RDP to Attack Box — tunnel through a Linux host that can reach it
            if (abIp && tunnelHost) {
                const cmd = `ssh -L 3389:${abIp}:3389 ${sshOpts} ubuntu@${tunnelHost}`;
                tunnels.push({ label: 'RDP Tunnel → Attack Box', cmd, color: 'btn-warning' });
            }

            // CS Client tunnel — forward local port to team server
            if (tsIp && tunnelHost) {
                const cmd50050 = `ssh -L 50050:${tsIp}:50050 ${sshOpts} ubuntu@${tunnelHost}`;
                tunnels.push({ label: 'CS Client Tunnel', cmd: cmd50050, color: 'btn-warning' });
            }

            // REST API tunnel — forward local port to team server REST API
            if (tsIp && tunnelHost) {
                const cmd50443 = `ssh -L 50443:${tsIp}:50443 ${sshOpts} ubuntu@${tunnelHost}`;
                tunnels.push({ label: 'REST API Tunnel', cmd: cmd50443, color: 'btn-warning' });
            }

            // Combined: GOAD tunnel via jumpbox if separate from C2
            if (goadTsIp && c2TsIp && goadTsIp !== c2TsIp) {
                const jbHost = jumpboxPrivate || jumpboxIp;
                if (jbHost) {
                    const cmd = `ssh -L 50050:${goadTsIp}:50050 ${sshOpts} ubuntu@${jbHost}`;
                    tunnels.push({ label: 'CS Client Tunnel (GOAD)', cmd, color: 'btn-warning' });
                }
            }

            if (tunnels.length > 0) {
                html += '<span style="display:inline-block; width:1px; height:24px; background:var(--border); margin:0 6px; vertical-align:middle;"></span>';
                html += tunnels.map(t =>
                    `<button class="btn btn-sm ${t.color}" onclick="TERMINAL.openTunnel('${_esc(t.label)}', '${_esc(t.cmd)}')" title="${_esc(t.cmd)}">🔗 ${_esc(t.label)}</button>`
                ).join('');
            }

            btnRow.innerHTML = html;
        } else {
            btnRow.innerHTML = '<span style="color: var(--text-muted); font-size: 0.85em;">No SSH-accessible instances found for this deployment.</span>';
        }
    },

    // ── Open a local shell ──
    openLocal() {
        if (typeof Terminal === 'undefined') return;

        if (Object.keys(this.sessions).length >= this.maxSessions) {
            alert(`Session limit reached (max ${this.maxSessions}). Close a tab first.`);
            return;
        }

        const id = 'term_' + (this.nextId++);
        const localCount = Object.values(this.sessions).filter(s => s.type === 'local').length;
        const label = localCount === 0 ? 'Local Shell' : `Local Shell ${localCount + 1}`;

        const wsProto = location.protocol === 'https:' ? 'wss:' : 'ws:';
        const ws = new WebSocket(`${wsProto}//${location.host}/api/terminal/local`);

        const term = this._createTerm(id, ws);

        ws.onopen = () => {
            ws.send(JSON.stringify({ type: 'init' }));
            this._sendResize(ws, term);
        };

        // Phase 3B.2 — record the operator that opened this session.
        const opener = (APP.operator && APP.operator.current && APP.operator.current.id) || null;
        this.sessions[id] = { term, ws, type: 'local', label, opener };
        this._addTab(id, label, opener);
        this._switchTo(id);
    },

    // ── Open SSH session ──
    openSSH(host, user, bastion, label) {
        if (typeof Terminal === 'undefined') return;

        // Check if session to this host already exists
        for (const [id, s] of Object.entries(this.sessions)) {
            if (s.type === 'ssh' && s.host === host) { this._switchTo(id); return; }
        }

        if (Object.keys(this.sessions).length >= this.maxSessions) {
            alert(`Session limit reached (max ${this.maxSessions}). Close a tab first.`);
            return;
        }

        const id = 'term_' + (this.nextId++);
        const wsProto = location.protocol === 'https:' ? 'wss:' : 'ws:';
        const ws = new WebSocket(`${wsProto}//${location.host}/api/terminal/ssh`);

        const term = this._createTerm(id, ws);

        ws.onopen = () => {
            ws.send(JSON.stringify({ host, user, bastion: bastion || null }));
        };

        // Phase 3B.2 — record the operator that opened this session.
        const opener = (APP.operator && APP.operator.current && APP.operator.current.id) || null;
        this.sessions[id] = { term, ws, type: 'ssh', label: label || host, host, opener };
        this._addTab(id, label || host, opener);
        this._switchTo(id);
    },

    // ── Create xterm.js instance ──
    _createTerm(id, ws) {
        const container = document.getElementById('terminal-container');
        const workspace = document.getElementById('terminal-workspace');
        const emptyState = document.getElementById('terminal-empty-state');
        if (workspace) workspace.classList.remove('terminal-workspace-hidden');
        if (emptyState) emptyState.style.display = 'none';

        // Create session div
        const div = document.createElement('div');
        div.id = id;
        div.className = 'terminal-session';
        container.appendChild(div);

        // Create xterm
        const term = new Terminal({
            cursorBlink: true,
            fontSize: 14,
            fontFamily: "'SF Mono', 'Fira Code', 'Cascadia Code', Menlo, Monaco, monospace",
            theme: {
                background: '#0B0D14',
                foreground: '#B0B8CC',
                cursor: '#B0B8CC',
                cursorAccent: '#0B0D14',
                selectionBackground: '#3A4060',
                black: '#1C2031',
                red: '#F08A84',
                green: '#7ECF8C',
                yellow: '#F0CA4A',
                blue: '#82BBE8',
                magenta: '#C8A0E8',
                cyan: '#7AD4D4',
                white: '#EEF0F6',
                brightBlack: '#4A5168',
                brightRed: '#F08A84',
                brightGreen: '#7ECF8C',
                brightYellow: '#F0CA4A',
                brightBlue: '#82BBE8',
                brightMagenta: '#C8A0E8',
                brightCyan: '#7AD4D4',
                brightWhite: '#EEF0F6',
            },
            allowProposedApi: true,
        });

        const fitAddon = new FitAddon.FitAddon();
        term.loadAddon(fitAddon);
        term.open(div);

        // Fit after a tick (DOM needs to settle)
        requestAnimationFrame(() => {
            fitAddon.fit();
            this._sendResize(ws, term);
        });

        // Handle resize
        const resizeObserver = new ResizeObserver(() => {
            fitAddon.fit();
            this._sendResize(ws, term);
        });
        resizeObserver.observe(div);

        // Terminal → WebSocket (user input)
        term.onData(data => {
            if (ws.readyState === WebSocket.OPEN) {
                ws.send(data);
            }
        });

        // WebSocket → Terminal (output)
        ws.onmessage = (evt) => {
            if (evt.data instanceof Blob) {
                evt.data.arrayBuffer().then(buf => term.write(new Uint8Array(buf)));
            } else {
                term.write(evt.data);
            }
        };

        ws.onclose = () => {
            term.write('\r\n\x1b[33m[Session ended]\x1b[0m\r\n');
        };

        ws.onerror = () => {
            term.write('\r\n\x1b[31m[Connection error]\x1b[0m\r\n');
        };

        // Store fitAddon and observer for cleanup
        term._fitAddon = fitAddon;
        term._resizeObserver = resizeObserver;

        return term;
    },

    _sendResize(ws, term) {
        if (ws.readyState === WebSocket.OPEN) {
            try {
                ws.send(JSON.stringify({ type: 'resize', rows: term.rows, cols: term.cols }));
            } catch { /* ignore */ }
        }
    },

    // ── Tab management ──
    // Phase 3B.2 — V3-native chrome. Each tab carries an 8px operator color
    // dot (color from APP.operator.all lookup by `opener` id) plus an icon
    // close affordance. Active tab uses .seg-control-style inset under-rule
    // via the .active class (see PHASE 3B.2 in style.css).
    _addTab(id, label, opener) {
        const bar = document.getElementById('terminal-tab-bar');
        if (!bar) return;

        // Remove existing "+" button (we'll re-add it at the end)
        const existingPlus = bar.querySelector('.terminal-tab-new');
        if (existingPlus) existingPlus.remove();

        const tab = document.createElement('button');
        tab.className = 'terminal-tab';
        tab.dataset.termId = id;
        if (opener) tab.dataset.opener = opener;
        tab.setAttribute('role', 'tab');
        tab.setAttribute('aria-label', `Terminal session: ${label}`);

        // Operator dot — color resolved from APP.operator.all profile
        const op = opener && (APP.operator.all || []).find(o => o.id === opener);
        const dotColor = (op && op.color) || '';
        const dotClass = dotColor ? 'terminal-tab__op-dot' : 'terminal-tab__op-dot terminal-tab__op-dot--unknown';
        const dotStyle = dotColor ? ` style="background: ${this._esc(dotColor)}"` : '';
        const dotTitle = op ? `Opened by ${this._esc(op.display || op.id)}` : 'Opened by an unknown operator';

        tab.innerHTML = `
            <span class="${dotClass}"${dotStyle} title="${dotTitle}" aria-hidden="true"></span>
            <span class="terminal-tab__label tab-label">${this._esc(label)}</span>
            <span class="terminal-tab__close tab-close" role="button" tabindex="0"
                  aria-label="Close session ${this._esc(label)}"
                  onclick="event.stopPropagation(); TERMINAL.closeSession('${id}')"
                  onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();TERMINAL.closeSession('${id}')}">
                <svg class="icon icon--sm" aria-hidden="true"><use href="#icon-x"/></svg>
            </span>`;
        tab.onclick = () => this._switchTo(id);
        bar.appendChild(tab);

        // Add "+" button at the end
        const plus = document.createElement('button');
        plus.className = 'terminal-tab terminal-tab-new';
        plus.title = 'New local shell';
        plus.setAttribute('aria-label', 'Open a new local shell');
        plus.innerHTML = '<span class="tab-plus">+</span>';
        plus.onclick = () => this.openLocal();
        bar.appendChild(plus);
    },

    _switchTo(id) {
        // Hide all sessions, show the target
        Object.entries(this.sessions).forEach(([sid, s]) => {
            const div = document.getElementById(sid);
            if (div) div.classList.toggle('active', sid === id);
        });

        // Update tab active state
        document.querySelectorAll('#terminal-tab-bar .terminal-tab').forEach(tab => {
            tab.classList.toggle('active', tab.dataset.termId === id);
        });

        this.activeId = id;
        const session = this.sessions[id];
        if (session) {
            requestAnimationFrame(() => {
                session.term._fitAddon?.fit();
                session.term.focus();
            });
        }
    },

    closeSession(id) {
        const session = this.sessions[id];
        if (!session) return;

        // Send explicit close signal so backend kills the process immediately
        try {
            if (session.ws.readyState === WebSocket.OPEN) {
                session.ws.send(JSON.stringify({ type: 'close' }));
            }
            session.ws.close();
        } catch { /* ignore */ }

        // Dispose terminal
        try {
            session.term._resizeObserver?.disconnect();
            session.term.dispose();
        } catch { /* ignore */ }

        // Remove DOM
        const div = document.getElementById(id);
        if (div) div.remove();

        // Remove tab
        document.querySelectorAll(`#terminal-tab-bar .terminal-tab[data-term-id="${id}"]`).forEach(t => t.remove());

        delete this.sessions[id];

        // Switch to another tab or show empty state
        const remaining = Object.keys(this.sessions);
        if (remaining.length > 0) {
            this._switchTo(remaining[remaining.length - 1]);
        } else {
            this.activeId = null;
            const workspace = document.getElementById('terminal-workspace');
            const emptyState = document.getElementById('terminal-empty-state');
            if (workspace) workspace.classList.add('terminal-workspace-hidden');
            if (emptyState) emptyState.style.display = '';
        }
    },

    _esc(s) {
        if (!s) return '';
        const d = document.createElement('div');
        d.textContent = String(s);
        return d.innerHTML;
    },
};


// ============================================================================
// TOPOLOGY GRAPH — Full-screen infrastructure + beacon topology overlay
// ============================================================================

const TOPOLOGY = {
    overlay: null,
    canvas: null,
    ctx: null,
    sidePanel: null,
    sidePanelBody: null,
    nodes: [],
    edges: [],
    selectedNode: null,
    panX: 0, panY: 0,
    scale: 1,
    dragStart: null,
    isDragging: false,
    dragNode: null,        // Node being dragged (null = pan canvas)
    dragNodeStart: null,   // {x, y} of node at drag start
    projectName: '',
    beaconData: null,
    listenerData: null,
    beaconStatus: 'unknown', // 'connected' | 'no_beacons' | 'not_connected'
    infraData: null,
    configData: null, // parsed terraform.tfvars — drives dynamic port labels

    // ── Node type config ──
    // awsIcon = path under /assets/aws-icons/, fallbackIcon = emoji if image fails
    NODE_TYPES: {
        operator:    { color: '#F08A84', label: 'Operator',     w: 160, h: 52, awsIcon: null,            fallbackIcon: '👤' },
        dashboard:   { color: '#C8A0E8', label: 'Dashboard',   w: 170, h: 56, awsIcon: 'ec2.svg',       fallbackIcon: '🖥' },
        domain:      { color: '#82BBE8', label: 'Domain',      w: 160, h: 52, awsIcon: 'route53.svg',   fallbackIcon: '🌐' },
        cloudfront:  { color: '#F0CA4A', label: 'CloudFront',  w: 160, h: 52, awsIcon: 'cloudfront.svg', fallbackIcon: '☁' },
        redirector:  { color: '#7ECF8C', label: 'Redirector',  w: 165, h: 58, awsIcon: 'ec2.svg',       fallbackIcon: '🔀' },
        teamserver:  { color: '#F08A84', label: 'Team Server', w: 175, h: 62, awsIcon: 'ec2.svg',       fallbackIcon: '🖥' },
        bastion:     { color: '#F0CA4A', label: 'Bastion',     w: 155, h: 52, awsIcon: 'ec2.svg',       fallbackIcon: '🛡' },
        attackbox:   { color: '#F0CA4A', label: 'Attack Box',  w: 155, h: 52, awsIcon: 'ec2.svg',       fallbackIcon: '⚔' },
        listener:    { color: '#B0B8CC', label: 'Listener',    w: 130, h: 34, awsIcon: null,            fallbackIcon: '📡' },
        beacon:      { color: '#7ECF8C', label: 'Beacon',      w: 140, h: 54, awsIcon: null,            fallbackIcon: '💻' },
        jumpbox:     { color: '#B0B8CC', label: 'Jumpbox',     w: 150, h: 52, awsIcon: 'ec2.svg',       fallbackIcon: '🔑' },
        goad_vm:     { color: '#7A849E', label: 'GOAD VM',     w: 140, h: 48, awsIcon: 'ec2.svg',       fallbackIcon: '🏢' },
        s3_bucket:   { color: '#3B48CC', label: 'S3 Bucket',   w: 160, h: 48, awsIcon: 's3.svg',        fallbackIcon: '📦' },
        nat_gateway: { color: '#7ECF8C', label: 'NAT Gateway', w: 155, h: 48, awsIcon: 'nat.svg',       fallbackIcon: '🌐' },
    },

    // Preloaded Image objects keyed by filename
    _iconCache: {},
    _iconsLoaded: false,

    // ── Preload AWS icon SVGs into Image objects ──
    _preloadIcons() {
        const files = new Set();
        Object.values(this.NODE_TYPES).forEach(cfg => { if (cfg.awsIcon) files.add(cfg.awsIcon); });
        let loaded = 0;
        const total = files.size;
        if (total === 0) { this._iconsLoaded = true; return Promise.resolve(); }

        return new Promise(resolve => {
            files.forEach(file => {
                if (this._iconCache[file]) { loaded++; if (loaded >= total) { this._iconsLoaded = true; resolve(); } return; }
                const img = new Image();
                img.onload = () => { this._iconCache[file] = img; loaded++; if (loaded >= total) { this._iconsLoaded = true; resolve(); } };
                img.onerror = () => { loaded++; if (loaded >= total) { this._iconsLoaded = true; resolve(); } };
                img.src = `/assets/aws-icons/${file}`;
            });
        });
    },

    // ── Show topology overlay ──
    show(projectName) {
        this.projectName = projectName;
        this.selectedNode = null;
        this.panX = 0;
        this.panY = 0;
        this.scale = 1;
        this.nodes = [];
        this.edges = [];
        this.infraData = null;
        this.configData = null;
        this.beaconData = null;
        this.listenerData = null;
        this.beaconStatus = 'unknown';
        this._createOverlay();
        this._fetchData(projectName);
    },

    // ── Close overlay ──
    close() {
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
    },

    // ── Create full-screen overlay DOM ──
    _createOverlay() {
        if (this.overlay) this.overlay.remove();
        const div = document.createElement('div');
        div.className = 'topology-overlay';
        div.innerHTML = `
            <div class="topology-header">
                <h2>Infrastructure Topology — ${this._esc(this.projectName)}</h2>
                <button class="btn btn-sm btn-info" onclick="TOPOLOGY._refresh()">Refresh</button>
                <button class="btn btn-sm btn-secondary" onclick="TOPOLOGY._resetLayout()">Reset Layout</button>
                <button class="btn-close-topology" onclick="TOPOLOGY.close()">✕ Close</button>
            </div>
            <div class="topology-body">
                <div class="topology-canvas-wrap">
                    <canvas id="topology-canvas"></canvas>
                    <div class="topology-legend">
                        <span><span style="color:#82BBE8;">■</span> Domain</span>
                        <span><span style="color:#F0CA4A;">■</span> CDN / Bastion</span>
                        <span><span style="color:#7ECF8C;">■</span> Redirector</span>
                        <span><span style="color:#F08A84;">■</span> Team Server</span>
                        <span><span style="color:#B0B8CC;">■</span> Listener</span>
                        <span>── Link</span>
                        <span>╌╌ Pivot</span>
                        <span style="border: 1px dashed #F08A84; padding: 0 4px; border-radius: 3px; font-size: 0.9em; color: #F08A84;">★</span> Admin/SYSTEM
                    </div>
                    <div id="topology-beacon-banner" class="topology-beacon-banner" style="display: none;"></div>
                </div>
                <div class="topology-side-panel" id="topology-side-panel">
                    <div class="topology-side-panel-header">
                        <h3 id="topology-side-title">Details</h3>
                        <button class="btn-close-side" onclick="TOPOLOGY._closeSide()">✕</button>
                    </div>
                    <div class="topology-side-panel-body" id="topology-side-body"></div>
                </div>
            </div>
        `;
        document.body.appendChild(div);
        this.overlay = div;
        this.sidePanel = div.querySelector('#topology-side-panel');
        this.sidePanelBody = div.querySelector('#topology-side-body');

        // Canvas setup
        this.canvas = div.querySelector('#topology-canvas');
        const wrap = div.querySelector('.topology-canvas-wrap');
        this.canvas.width = wrap.clientWidth * devicePixelRatio;
        this.canvas.height = wrap.clientHeight * devicePixelRatio;
        this.canvas.style.width = wrap.clientWidth + 'px';
        this.canvas.style.height = wrap.clientHeight + 'px';
        this.ctx = this.canvas.getContext('2d');
        this.ctx.scale(devicePixelRatio, devicePixelRatio);
        this.W = wrap.clientWidth;
        this.H = wrap.clientHeight;

        // Events
        this.canvas.addEventListener('wheel', e => this._handleWheel(e), { passive: false });
        this.canvas.addEventListener('mousedown', e => this._handleMouseDown(e));
        this.canvas.addEventListener('mousemove', e => this._handleMouseMove(e));
        this.canvas.addEventListener('mouseup', e => this._handleMouseUp(e));
        this.canvas.addEventListener('mouseleave', e => this._handleMouseUp(e));
        document.addEventListener('keydown', this._escHandler = e => { if (e.key === 'Escape') this.close(); });

        // Loading state
        this._drawLoading();
    },

    _drawLoading() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.W, this.H);
        ctx.fillStyle = '#7A849E';
        ctx.font = '14px system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Loading infrastructure data...', this.W / 2, this.H / 2);
    },

    // ── Fetch infra outputs + config + beacons ──
    async _fetchData(projectName) {
        // Use shared cache for outputs, fetch config in parallel
        const cached = _getCachedOutputs(projectName);
        const configPromise = fetch('/api/config/').then(r => r.json()).catch(() => null);

        if (cached) {
            this.infraData = cached;
            // Background refresh
            _fetchAndCacheOutputs(projectName).then(fresh => { if (fresh) this.infraData = fresh; });
        } else {
            const fresh = await _fetchAndCacheOutputs(projectName);
            this.infraData = fresh || null;
            if (!fresh) console.warn('Topology: could not load infra outputs');
        }

        const configResult = await configPromise;

        if (configResult && configResult.success) {
            this.configData = configResult.config;
        } else {
            this.configData = null;
        }

        // Fetch actual SG rules for accurate edge labels
        this._sgRules = null;
        try {
            const sgResp = await fetch(`/api/deploy/sg-rules?project=${encodeURIComponent(projectName)}`);
            const sgJson = await sgResp.json();
            if (sgJson.success) this._sgRules = sgJson.connections;
        } catch { /* ignore — fall back to static labels */ }

        // Check if CS REST API is actually connected via the health endpoint
        this.beaconStatus = 'not_connected';
        this.beaconData = null;
        try {
            const healthResp = await fetch('/api/beacon/health');
            const healthJson = await healthResp.json();
            const apiConnected = healthJson.status === 'connected' && healthJson.authenticated;

            if (apiConnected) {
                // API is authenticated — now get beacons (use cached if available)
                if (BEACON && BEACON.cachedBeacons && BEACON.cachedBeacons.length > 0) {
                    this.beaconData = BEACON.cachedBeacons;
                    this.beaconStatus = 'connected';
                } else {
                    try {
                        await BEACON.refreshBeacons();
                    } catch { /* ignore */ }
                    if (BEACON.cachedBeacons && BEACON.cachedBeacons.length > 0) {
                        this.beaconData = BEACON.cachedBeacons;
                        this.beaconStatus = 'connected';
                    } else {
                        this.beaconStatus = 'no_beacons';
                    }
                }
            } else {
                // API reachable but not authenticated, or not configured
                this.beaconStatus = 'not_connected';
            }
        } catch {
            this.beaconStatus = 'not_connected';
        }

        // Fetch listener details if API is connected
        this.listenerData = null;
        this._connectedServerIp = null;
        if (this.beaconStatus !== 'not_connected') {
            try {
                const lResp = await fetch('/api/beacon/listeners');
                const lJson = await lResp.json();
                if (lJson.success && lJson.listeners) this.listenerData = lJson.listeners;
            } catch { /* ignore */ }

            // Get connected server IP to verify it belongs to this deployment
            try {
                const ipResp = await fetch('/api/beacon/server/ip');
                const ipJson = await ipResp.json();
                if (ipJson.success && ipJson.data) this._connectedServerIp = ipJson.data;
            } catch { /* ignore */ }
        }

        // Verify beacon data belongs to THIS deployment's team server
        if (this.beaconData && this.infraData && this._connectedServerIp) {
            const deployTsIps = [];
            if (this.infraData.c2_servers) {
                this.infraData.c2_servers.forEach(ts => {
                    if (ts.private_ip) deployTsIps.push(ts.private_ip);
                });
            }
            if (this.infraData.teamserver_private_ip) {
                deployTsIps.push(this.infraData.teamserver_private_ip);
            }

            if (deployTsIps.length > 0 && !deployTsIps.includes(this._connectedServerIp)) {
                // Connected to a DIFFERENT team server — don't show beacons on this topology
                this.beaconData = null;
                this.listenerData = null;
                this.beaconStatus = 'wrong_server';
            }
        }

        this._buildGraph();
        this._layoutNodes();
        await this._preloadIcons();
        this._render();
        this._updateBeaconBanner();
    },

    _refresh() {
        this._drawLoading();
        this._fetchData(this.projectName);
    },

    // ── Subnet visual config (CIDRs derived dynamically from node IPs) ──
    SUBNETS: {
        operator:   { label: 'Operator',              color: '#F08A8410', border: '#F08A8422' },
        dashboard:  { label: 'Dashboard Server VPC', color: '#C8A0E815', border: '#C8A0E833' },
        external:   { label: 'External / Internet',  color: '#82BBE822', border: '#82BBE844' },
        management: { label: 'Management Subnet',    color: '#F0CA4A15', border: '#F0CA4A33' },
        dmz:        { label: 'Public / DMZ Subnets', color: '#7ECF8C15', border: '#7ECF8C33' },
        private:    { label: 'Private Subnets',      color: '#F08A8415', border: '#F08A8433' },
        goad:       { label: 'GOAD Lab VPC',          color: '#7A849E15', border: '#7A849E33' },
    },

    // Derive CIDR-style label from actual node IPs in a subnet group
    _deriveSubnetCidr(subnetKey) {
        const nodeIds = this._subnetGroups?.[subnetKey] || [];
        const ips = [];
        for (const id of nodeIds) {
            const n = this.nodes.find(nd => nd.id === id);
            if (!n) continue;
            // Collect all private/public IPs from node data
            const d = n.data || {};
            if (d.private_ip) ips.push(d.private_ip);
            else if (d.public_ip) ips.push(d.public_ip);
        }
        if (ips.length === 0) return '';

        // Group IPs by their /24 prefix (first 3 octets)
        const prefixes = new Set();
        for (const ip of ips) {
            const parts = ip.split('.');
            if (parts.length === 4) prefixes.add(`${parts[0]}.${parts[1]}.${parts[2]}.0/24`);
        }
        return [...prefixes].join(' · ');
    },

    // ── Read a config value from tfvars, with default fallback ──
    _cfg(key, fallback) {
        if (this.configData && this.configData[key] !== undefined && this.configData[key] !== '') {
            return this.configData[key];
        }
        return fallback;
    },

    // ── Build nodes and edges from data ──
    _buildGraph() {
        this.nodes = [];
        this.edges = [];
        this._subnets = []; // [{key, nodes: [nodeIds]}]
        const d = this.infraData;
        if (!d) {
            this.nodes.push({ id: 'empty', type: 'domain', label: 'No data', sublabel: 'Check deployment outputs', x: 0, y: 0, subnet: 'external', data: {} });
            return;
        }

        let nodeId = 0;
        const nid = () => 'n' + (nodeId++);

        // Track node IDs per subnet for clustering
        const subnetNodes = { operator: [], dashboard: [], external: [], management: [], dmz: [], private: [], goad: [] };

        // Determine if this deployment uses C2 infrastructure (domain, redirectors, CloudFront)
        const deployType = d.deployment_type || this._cfg('deployment_type', '');
        const isC2Deploy = deployType.startsWith('c2-') || deployType.startsWith('combined-');
        const isGoadDeploy = deployType.startsWith('goad-') || deployType.startsWith('combined-');

        // Operator node — the red team operator connecting via SSH tunnel
        const operatorId = nid();
        // D1 — Prefer the new global header element; fall back to the hidden
        // legacy mirror so existing topology behaviour is preserved.
        const operatorName = document.getElementById('global-operator-name')?.textContent
            || document.getElementById('operator-badge')?.textContent
            || 'Operator';
        this.nodes.push({
            id: operatorId, type: 'operator',
            label: operatorName,
            sublabel: 'SSH tunnel → localhost:5000',
            x: 0, y: 0, subnet: 'operator',
            data: { access: 'SSH key + IP allowlist', port: 'SSH/22' }
        });
        subnetNodes.operator.push(operatorId);

        // Dashboard server — always show. This IS the server running the dashboard.
        let dashboardId = nid();
        const dashPubIp = window._dashboardServerIp || '';
        this.nodes.push({
            id: dashboardId, type: 'dashboard',
            label: 'Dashboard Server',
            sublabel: dashPubIp || 'Fetching IP...',
            x: 0, y: 0, subnet: 'dashboard',
            data: {
                public_ip: dashPubIp,
                vpc_cidr: '10.100.0.0/16',
                subnet: '10.100.1.0/24',
                instance_type: 't3.medium',
                access: 'ssh -L 5000:localhost:5000 harris@' + (dashPubIp || '<server-ip>'),
                state: 'running',
            }
        });
        subnetNodes.dashboard.push(dashboardId);

        // Operator → Dashboard edge
        this.edges.push({ from: operatorId, to: dashboardId, label: 'SSH/22 (tunnel)', dashed: false });

        // Fetch public IP in background for sublabel
        if (!window._dashboardServerIp) {
            fetch('/api/config/public-ip').then(r => r.json()).then(d => {
                if (d.success && d.ip) window._dashboardServerIp = d.ip;
            }).catch(() => {});
        }

        // Domain (external) — only for C2/combined deployments
        const domainId = nid();
        if (d.primary_domain_name && isC2Deploy) {
            this.nodes.push({ id: domainId, type: 'domain', label: d.primary_domain_name, sublabel: d.c2_subdomain ? `${d.c2_subdomain}.${d.primary_domain_name}` : '', x: 0, y: 0, subnet: 'external', data: { domain: d.primary_domain_name, nameservers: d.dns_nameservers, dns_domain: d.dns_domain } });
            subnetNodes.external.push(domainId);
        }

        // CloudFront (external) — only for C2/combined with domain fronting
        let cfId = null;
        if (d.enable_domain_fronting && isC2Deploy) {
            cfId = nid();
            this.nodes.push({ id: cfId, type: 'cloudfront', label: 'CloudFront CDN', sublabel: d.cloudfront_domain_name || '', x: 0, y: 0, subnet: 'external', data: { distribution_id: d.cloudfront_distribution_id, domain: d.cloudfront_domain_name } });
            subnetNodes.external.push(cfId);
            if (d.primary_domain_name) this.edges.push({ from: domainId, to: cfId, label: 'DNS CNAME' });
        }

        // Redirectors (DMZ) — only for C2/combined deployments
        const redirIds = [];
        if (isC2Deploy && d.redirectors && d.redirectors.length > 0) {
            d.redirectors.forEach((r, i) => {
                const rid = nid();
                redirIds.push(rid);
                const redirSub = r.private_ip ? `${r.private_ip} (${r.public_ip})` : (r.public_ip || '');
                this.nodes.push({ id: rid, type: 'redirector', label: `Redirector ${i + 1}`, sublabel: redirSub, x: 0, y: 0, subnet: 'dmz', data: { ...r, index: i + 1 } });
                subnetNodes.dmz.push(rid);
                if (cfId) {
                    // domain_fronting/main.tf: origin_protocol_policy = "http-only"
                    this.edges.push({ from: cfId, to: rid, label: 'HTTP/80 (CF origin)' });
                } else if (d.primary_domain_name) {
                    this.edges.push({ from: domainId, to: rid, label: this._getSgLabel('internet', 'redirector') || 'HTTPS/443' });
                }
            });
        } else if (isC2Deploy && d.redirector_public_ip) {
            const rid = nid();
            redirIds.push(rid);
            const singleRedirSub = d.redirector_private_ip ? `${d.redirector_private_ip} (${d.redirector_public_ip})` : d.redirector_public_ip;
            this.nodes.push({ id: rid, type: 'redirector', label: 'Redirector', sublabel: singleRedirSub, x: 0, y: 0, subnet: 'dmz', data: { public_ip: d.redirector_public_ip, private_ip: d.redirector_private_ip, instance_id: d.redirector_instance_id, state: d.redirector_state } });
            subnetNodes.dmz.push(rid);
            if (cfId) this.edges.push({ from: cfId, to: rid, label: 'HTTP/80 (CF origin)' });
            else if (d.primary_domain_name) this.edges.push({ from: domainId, to: rid, label: this._getSgLabel('internet', 'redirector') || 'HTTPS/443' });
        }

        // C2 Team Servers — C2 VPC private subnet (c2-* and combined-* deployments)
        const tsIds = [];
        if (isC2Deploy && d.c2_servers && d.c2_servers.length > 0) {
            d.c2_servers.forEach((ts, i) => {
                const tid = nid();
                tsIds.push(tid);
                this.nodes.push({ id: tid, type: 'teamserver', label: `Team Server ${i + 1}`, sublabel: ts.private_ip || '', x: 0, y: 0, subnet: 'private', data: { ...ts, index: i + 1, cs_password: d.cs_teamserver_password, profile: d.malleable_profile } });
                subnetNodes.private.push(tid);
                redirIds.forEach(rid => this.edges.push({ from: rid, to: tid, label: this._getSgLabel('redirector', 'teamserver') || `TCP/${this._cfg('c2_listener_port', 443)} (listener)` }));
            });
        } else if (isC2Deploy && d.teamserver_private_ip) {
            // Fallback: outputs return teamserver_private_ip but not c2_servers array
            const tid = nid();
            tsIds.push(tid);
            this.nodes.push({ id: tid, type: 'teamserver', label: 'Team Server', sublabel: d.teamserver_private_ip, x: 0, y: 0, subnet: 'private', data: { private_ip: d.teamserver_private_ip, instance_id: d.teamserver_instance_id, state: d.teamserver_state, cs_password: d.cs_teamserver_password, profile: d.malleable_profile } });
            subnetNodes.private.push(tid);
            redirIds.forEach(rid => this.edges.push({ from: rid, to: tid, label: this._getSgLabel('redirector', 'teamserver') || `TCP/${this._cfg('c2_listener_port', 443)} (listener)` }));
        }
        // GOAD Team Server — lives in GOAD VPC private subnet (goad-* and combined-* deployments)
        if (isGoadDeploy && d.teamserver_private_ip) {
            // Avoid duplicating if already added above for combined deployments
            const alreadyAdded = tsIds.length > 0 && this.nodes.some(n => n.type === 'teamserver' && n.data?.private_ip === d.teamserver_private_ip);
            if (!alreadyAdded) {
                const tid = nid();
                tsIds.push(tid);
                this.nodes.push({ id: tid, type: 'teamserver', label: 'Team Server (GOAD)', sublabel: d.teamserver_private_ip, x: 0, y: 0, subnet: 'goad', data: { private_ip: d.teamserver_private_ip, instance_id: d.teamserver_instance_id, state: d.teamserver_state } });
                subnetNodes.goad.push(tid);
            }
        }

        // Bastion (Management subnet — C2/combined only, GOAD-only has no bastion)
        let bastionId = null;
        if (d.bastion_public_ip && isC2Deploy) {
            bastionId = nid();
            const bastionSub = d.bastion_private_ip ? `${d.bastion_private_ip} (${d.bastion_public_ip})` : d.bastion_public_ip;
            this.nodes.push({ id: bastionId, type: 'bastion', label: 'Bastion', sublabel: bastionSub, x: 0, y: 0, subnet: 'management', data: { public_ip: d.bastion_public_ip, private_ip: d.bastion_private_ip, instance_id: d.bastion_instance_id, state: d.bastion_state } });
            subnetNodes.management.push(bastionId);
        }

        // Attack Box — C2 VPC private subnet for C2/combined, GOAD VPC for GOAD-only
        let attackboxId = null;
        if (d.attackbox_private_ip) {
            attackboxId = nid();
            const abSubnet = isGoadDeploy && !isC2Deploy ? 'goad' : 'private';
            this.nodes.push({ id: attackboxId, type: 'attackbox', label: 'Attack Box', sublabel: d.attackbox_private_ip, x: 0, y: 0, subnet: abSubnet, data: { private_ip: d.attackbox_private_ip, instance_id: d.attackbox_instance_id, state: d.attackbox_state, password: d.attackbox_password } });
            subnetNodes[abSubnet].push(attackboxId);
        }

        // Cross-subnet connections (from security/main.tf SG rules, ports from tfvars)
        const sshPort = this._cfg('ssh_port', 22);
        const csPort = this._cfg('c2_server_port', 50050);
        // REST API: show port if tfvars says enabled OR if we actually connected to it
        const restEnabled = this._cfg('enable_cs_rest_api', false) === true
            || this._cfg('enable_cs_rest_api', '') === 'true'
            || this.beaconStatus === 'connected'
            || this.beaconStatus === 'no_beacons';

        if (bastionId) {
            if (attackboxId) {
                const abLabel = this._getSgLabel('bastion', 'attackbox') || 'RDP/3389';
                this.edges.push({ from: bastionId, to: attackboxId, label: abLabel, dashed: true });
            }
            tsIds.forEach(tid => {
                const tsLabel = this._getSgLabel('bastion', 'teamserver') || `SSH/${sshPort} · CS/${csPort}`;
                this.edges.push({ from: bastionId, to: tid, label: tsLabel, dashed: true });
            });
            redirIds.forEach(rid => {
                const rLabel = this._getSgLabel('bastion', 'redirector') || `SSH/${sshPort}`;
                this.edges.push({ from: bastionId, to: rid, label: rLabel, dashed: true });
            });
        }
        if (attackboxId) {
            tsIds.forEach(tid => {
                const abTsLabel = this._getSgLabel('attackbox', 'teamserver') || `SSH/${sshPort} · CS/${csPort}`;
                this.edges.push({ from: attackboxId, to: tid, label: abTsLabel, dashed: true });
            });
        }

        // Jumpbox (GOAD public subnet — GOAD/combined only)
        let jumpboxId = null;
        if (d.jumpbox_public_ip && isGoadDeploy) {
            jumpboxId = nid();
            const jbSub = d.jumpbox_private_ip ? `${d.jumpbox_private_ip} (${d.jumpbox_public_ip})` : d.jumpbox_public_ip;
            this.nodes.push({ id: jumpboxId, type: 'jumpbox', label: 'Jumpbox', sublabel: jbSub, x: 0, y: 0, subnet: 'goad', data: { public_ip: d.jumpbox_public_ip, private_ip: d.jumpbox_private_ip, instance_id: d.jumpbox_instance_id, state: d.jumpbox_state } });
            subnetNodes.goad.push(jumpboxId);
        }

        // GOAD VMs (GOAD subnet)
        const goadVmIds = [];
        ['dc01', 'dc02', 'srv01', 'srv02', 'srv03', 'ws01'].forEach(vm => {
            if (d[vm + '_private_ip']) {
                const vid = nid();
                goadVmIds.push(vid);
                this.nodes.push({ id: vid, type: 'goad_vm', label: vm.toUpperCase(), sublabel: d[vm + '_private_ip'], x: 0, y: 0, subnet: 'goad', data: { private_ip: d[vm + '_private_ip'], instance_id: d[vm + '_instance_id'], state: d[vm + '_state'] } });
                subnetNodes.goad.push(vid);
            }
        });

        // GOAD connections (goad/security.tf: all traffic allowed within VPC CIDR)
        if (jumpboxId && goadVmIds.length > 0) {
            // Jumpbox runs Ansible provisioning — SSH/22 + WinRM/5985-5986 to AD VMs
            goadVmIds.forEach(vid => this.edges.push({ from: jumpboxId, to: vid, label: 'All (VPC internal)', dashed: true }));
        }
        if (attackboxId && goadVmIds.length > 0) {
            // Attack box → AD VMs: All traffic within GOAD VPC (SG allows all from VPC CIDR)
            goadVmIds.forEach(vid => this.edges.push({ from: attackboxId, to: vid, label: 'All (VPC internal)', dashed: true }));
        }

        // VPC peering edges — dashboard has direct access to all deployment instances
        if (dashboardId) {
            const allDeploymentNodes = [
                ...subnetNodes.management,
                ...subnetNodes.dmz,
                ...subnetNodes.private,
                ...subnetNodes.goad,
            ];
            // Only show peering edges to instances the dashboard can actually reach
            // Attack box is Windows (no SSH) — accessed via RDP tunnel through bastion, not direct
            const peerableTypes = ['bastion', 'redirector', 'teamserver', 'jumpbox', 'goad_vm'];
            allDeploymentNodes.forEach((targetId) => {
                const targetNode = this.nodes.find(n => n.id === targetId);
                if (!targetNode || !peerableTypes.includes(targetNode.type)) return;
                // Use live SG rules if available, otherwise fall back to static
                const portLabel = this._getSgLabel('dashboard', targetNode.type) || 'SSH/22';
                this.edges.push({ from: dashboardId, to: targetId, label: portLabel, dashed: true });
            });
        }

        // S3 deployment bucket (CS archive storage)
        if (d.cs_storage_bucket) {
            const s3Id = nid();
            // S3 is regional, place in DMZ subnet area for visual proximity to redirectors/TS
            const s3Subnet = isC2Deploy ? 'dmz' : (isGoadDeploy ? 'goad' : 'dmz');
            this.nodes.push({
                id: s3Id, type: 's3_bucket',
                label: 'S3 Deploy Bucket',
                sublabel: d.cs_storage_bucket.length > 25 ? d.cs_storage_bucket.slice(0, 22) + '...' : d.cs_storage_bucket,
                x: 0, y: 0, subnet: s3Subnet,
                data: {
                    bucket_name: d.cs_storage_bucket,
                    upload_command: d.cs_upload_command || '',
                    contents: 'CS archive, bootstrap scripts, client files',
                    encryption: 'AES-256 server-side',
                }
            });
            if (s3Subnet === 'dmz') subnetNodes.dmz.push(s3Id);
            else subnetNodes.goad.push(s3Id);
        }

        // NAT Gateway — lives in public subnet but serves private subnet
        // Place in private subnet visually (since that's what it serves)
        // Side panel explains it's physically in the public subnet
        if (d.enable_nat_gateway !== false && (subnetNodes.private.length > 0 || subnetNodes.goad.length > 0)) {
            const natId = nid();
            const natSubnet = isC2Deploy ? 'private' : 'goad';
            this.nodes.push({
                id: natId, type: 'nat_gateway',
                label: 'NAT Gateway',
                sublabel: 'Private → Internet (outbound)',
                x: 0, y: 0, subnet: natSubnet,
                data: {
                    purpose: 'Outbound internet for private subnets (updates, S3 access, package downloads)',
                    actual_placement: 'First public/DMZ subnet (requires EIP + internet access)',
                    serves: 'Private subnet instances (team server, attack box)',
                    cost: '~$32/month + data transfer',
                    note: 'AWS requires NAT in a public subnet, but it only handles outbound traffic from private instances. No inbound access.',
                }
            });
            subnetNodes[natSubnet].push(natId);
        }

        // Store subnet groupings (only subnets that have nodes)
        this._subnetGroups = {};
        for (const [key, ids] of Object.entries(subnetNodes)) {
            if (ids.length > 0) this._subnetGroups[key] = ids;
        }

        // Listeners + Beacons (if available, attach below team servers)
        if (this.beaconData && this.beaconData.length > 0 && tsIds.length > 0) {
            const parentTsId = tsIds[0];
            const profile = d.malleable_profile || '';

            // Build listener nodes — one per unique listener name
            const listenerIdMap = {}; // listener name → graph node id
            const uniqueListeners = [...new Set(this.beaconData.map(b => b.listener || 'Unknown'))];

            uniqueListeners.forEach(lName => {
                const lid = nid();
                listenerIdMap[lName] = lid;

                // Find matching listener detail from API data
                const detail = (this.listenerData || []).find(l => (l.name || l.Name) === lName) || {};
                const lType = detail.type || detail.payload || '';
                const lHost = detail.host || detail.Host || '';
                const lPort = detail.port || detail.Port || '';

                // Count beacons on this listener
                const beaconsOnListener = this.beaconData.filter(b => (b.listener || 'Unknown') === lName && !b.pbid);
                const aliveCount = beaconsOnListener.filter(b => {
                    const el = (b.lastCheckinMs || 0) + (Date.now() - (b.fetchedAt || Date.now()));
                    return BEACON.getElapsedClass(el, b.sleep, b.alive) === 'alive';
                }).length;
                const totalOnListener = beaconsOnListener.length;

                this.nodes.push({
                    id: lid, type: 'listener',
                    label: lName,
                    sublabel: lPort ? `${lType || 'HTTPS'}/${lPort}` : lType || '',
                    x: 0, y: 0,
                    data: {
                        name: lName,
                        type: lType,
                        host: lHost,
                        port: lPort,
                        profile: profile,
                        beacon_count: totalOnListener,
                        beacon_alive: aliveCount,
                        beacon_total: this.beaconData.filter(b => (b.listener || 'Unknown') === lName).length,
                        ...detail
                    }
                });
                this.edges.push({ from: parentTsId, to: lid, label: '' });
            });

            // Add beacon nodes
            const beaconIdMap = {};
            this.beaconData.forEach(b => {
                const bid = nid();
                beaconIdMap[b.bid] = bid;
                const elapsed = (b.lastCheckinMs || 0) + (Date.now() - (b.fetchedAt || Date.now()));
                const health = BEACON.getElapsedClass(elapsed, b.sleep, b.alive);
                this.nodes.push({ id: bid, type: 'beacon', label: b.computer || 'Unknown', sublabel: b.user || '', x: 0, y: 0, health, data: { ...b, health, elapsed } });
            });
            // Edges: pivot beacons connect to parent, root beacons connect to their listener
            this.beaconData.forEach(b => {
                const bid = beaconIdMap[b.bid];
                if (b.pbid && beaconIdMap[b.pbid]) {
                    this.edges.push({ from: beaconIdMap[b.pbid], to: bid, label: b.pivotHint ? 'Pivot' : '', dashed: true });
                } else {
                    const lNodeId = listenerIdMap[b.listener || 'Unknown'];
                    if (lNodeId) this.edges.push({ from: lNodeId, to: bid, label: '' });
                }
            });
        } else if (this.listenerData && this.listenerData.length > 0 && tsIds.length > 0) {
            // API connected, listeners exist, but no beacons — still show listeners
            const parentTsId = tsIds[0];
            const profile = d.malleable_profile || '';
            this.listenerData.forEach(l => {
                const lid = nid();
                const lName = l.name || l.Name || 'Unknown';
                const lType = l.type || l.payload || '';
                const lPort = l.port || l.Port || '';
                const lHost = l.host || l.Host || '';
                this.nodes.push({
                    id: lid, type: 'listener',
                    label: lName,
                    sublabel: lPort ? `${lType || 'HTTPS'}/${lPort}` : lType || '',
                    x: 0, y: 0,
                    data: { name: lName, type: lType, host: lHost, port: lPort, profile: profile, beacon_count: 0, beacon_alive: 0, beacon_total: 0, ...l }
                });
                this.edges.push({ from: parentTsId, to: lid, label: '' });
            });
        }
    },

    // ── Position nodes in layered top-down layout with subnet clustering ──
    _layoutNodes() {
        const padX = 60, padY = 70, subPadY = 35;

        // Multi-column layout:
        // LEFT column: Operator, Dashboard (access chain)
        // CENTER column: External, DMZ, Private (C2 traffic flow)
        // RIGHT column: Management (Bastion — separate access path)
        // BOTTOM: GOAD (if present, full width)

        const leftX = this.W * 0.22;    // Left column center
        const centerX = this.W * 0.50;  // Center column center
        const rightX = this.W * 0.78;   // Right column center

        // Column assignments
        const columnMap = {
            operator:   'left',
            dashboard:  'left',
            external:   'center',
            dmz:        'center',
            private:    'center',
            management: 'right',
            goad:       'center',  // Full width at bottom
        };

        // Row order within each column
        const rowOrder = {
            left:   ['operator', 'dashboard'],
            center: ['external', 'dmz', 'private', 'goad'],
            right:  ['management'],
        };

        const layerOrder = { domain: 0, cloudfront: 0, redirector: 0, s3_bucket: 0, jumpbox: 0, bastion: 0, teamserver: 0, attackbox: 0, nat_gateway: 0, listener: 1, beacon: 2, goad_vm: 0 };

        // Track Y position per column — stagger starts so VPCs don't overlap vertically
        const colY = { left: subPadY, center: subPadY, right: subPadY };

        // Layout helper: position a subnet group in a column
        const layoutSubnet = (subKey, colKey) => {
            const nodeIds = this._subnetGroups?.[subKey];
            if (!nodeIds || nodeIds.length === 0) return;

            const subNodes = this.nodes.filter(n => nodeIds.includes(n.id));
            if (subNodes.length === 0) return;

            const xCenter = colKey === 'left' ? leftX : colKey === 'right' ? rightX : centerX;

            // Group by layer
            const layers = {};
            subNodes.forEach(n => {
                const layer = layerOrder[n.type] ?? 0;
                if (!layers[layer]) layers[layer] = [];
                layers[layer].push(n);
            });

            Object.keys(layers).sort((a, b) => a - b).forEach(lk => {
                const nodes = layers[lk];
                const totalW = nodes.reduce((sum, n) => sum + (this.NODE_TYPES[n.type]?.w || 140), 0) + (nodes.length - 1) * padX;
                let startX = xCenter - totalW / 2;
                nodes.forEach(n => {
                    const nc = this.NODE_TYPES[n.type] || { w: 140, h: 48 };
                    n.x = startX + nc.w / 2;
                    n.y = colY[colKey] + nc.h / 2;
                    startX += nc.w + padX;
                });
                const tallest = Math.max(...nodes.map(n => this.NODE_TYPES[n.type]?.h || 48));
                colY[colKey] += tallest + subPadY;
            });

            colY[colKey] += padY;
        };

        // Layout left column first (operator + dashboard)
        rowOrder.left.forEach(subKey => layoutSubnet(subKey, 'left'));

        // Center and right columns start at the same Y as where left column's dashboard ends
        // This aligns DMZ with the dashboard horizontally
        const dmzStartY = colY.left;
        colY.center = Math.max(colY.center, dmzStartY);
        colY.right = Math.max(colY.right, dmzStartY);

        // Layout center column (external → DMZ → private → goad)
        rowOrder.center.forEach(subKey => layoutSubnet(subKey, 'center'));

        // Right column (management/bastion) — align with DMZ row
        rowOrder.right.forEach(subKey => layoutSubnet(subKey, 'right'));

        // Position beacon/listener nodes below the center column (C2 traffic flow)
        let beaconY = Math.max(colY.left, colY.center, colY.right) + padY * 0.3;
        const ungroupedTypes = ['listener', 'beacon'];
        const ungrouped = this.nodes.filter(n => ungroupedTypes.includes(n.type) && !Object.values(this._subnetGroups || {}).flat().includes(n.id));
        if (ungrouped.length > 0) {
            const layers = {};
            ungrouped.forEach(n => {
                let layer = n.type === 'listener' ? 0 : 1;
                if (n.type === 'beacon') {
                    const parentEdge = this.edges.find(e => e.to === n.id);
                    if (parentEdge) {
                        const pn = this.nodes.find(p => p.id === parentEdge.from);
                        if (pn && pn.type === 'beacon') layer = 2;
                    }
                }
                if (!layers[layer]) layers[layer] = [];
                layers[layer].push(n);
            });

            Object.keys(layers).sort((a, b) => a - b).forEach(lk => {
                const nodes = layers[lk];
                const totalW = nodes.reduce((sum, n) => sum + (this.NODE_TYPES[n.type]?.w || 140), 0) + (nodes.length - 1) * padX;
                let startX = centerX - totalW / 2;
                nodes.forEach(n => {
                    const nc = this.NODE_TYPES[n.type] || { w: 140, h: 48 };
                    n.x = startX + nc.w / 2;
                    n.y = beaconY + nc.h / 2;
                    startX += nc.w + padX;
                });
                const tallest = Math.max(...nodes.map(n => this.NODE_TYPES[n.type]?.h || 48));
                beaconY += tallest + subPadY;
            });
        }

        // Auto-fit: compute bounding box and adjust scale/pan
        const allX = this.nodes.map(n => n.x);
        const allY = this.nodes.map(n => n.y);
        if (allX.length > 0) {
            const minX = Math.min(...allX) - 120;
            const maxX = Math.max(...allX) + 120;
            const minY = Math.min(...allY) - 60;
            const maxY = Math.max(...allY) + 60;
            const graphW = maxX - minX;
            const graphH = maxY - minY;
            this.scale = Math.min(this.W / graphW, this.H / graphH, 1.2);
            this.panX = (this.W - graphW * this.scale) / 2 - minX * this.scale;
            this.panY = (this.H - graphH * this.scale) / 2 - minY * this.scale;
        }
    },

    // ── Render everything ──
    _render() {
        const ctx = this.ctx;
        ctx.save();
        ctx.clearRect(0, 0, this.W, this.H);

        // Dot grid background
        this._drawDotGrid();

        ctx.translate(this.panX, this.panY);
        ctx.scale(this.scale, this.scale);

        // Draw subnet cluster backgrounds
        this._drawSubnets();

        // Draw edges
        this.edges.forEach(e => this._drawEdge(e));

        // Draw nodes
        this.nodes.forEach(n => this._drawNode(n));

        ctx.restore();
    },

    // ── Dot grid background ──
    _drawDotGrid() {
        const ctx = this.ctx;
        const spacing = 25;
        const dotR = 0.8;
        ctx.fillStyle = '#2A2F40';

        // Offset grid by pan so dots move with the canvas
        const offX = this.panX % (spacing * this.scale);
        const offY = this.panY % (spacing * this.scale);
        const step = spacing * this.scale;

        for (let x = offX; x < this.W; x += step) {
            for (let y = offY; y < this.H; y += step) {
                ctx.beginPath();
                ctx.arc(x, y, dotR * this.scale, 0, Math.PI * 2);
                ctx.fill();
            }
        }
    },

    // ── Draw subnet cluster backgrounds ──
    _drawSubnets() {
        const ctx = this.ctx;
        if (!this._subnetGroups) return;

        for (const [key] of Object.entries(this._subnetGroups)) {
            const subCfg = this.SUBNETS[key];
            if (!subCfg) continue;
            const b = { color: subCfg.color, border: subCfg.border, label: subCfg.label, cidr: this._deriveSubnetCidr(key) };
            // Recalculate bounds from actual node positions (in case nodes were dragged)
            const nodeIds = this._subnetGroups?.[key] || [];
            const subNodes = this.nodes.filter(n => nodeIds.includes(n.id));
            if (subNodes.length === 0) continue;

            const marginX = 35, marginTop = 35, marginBottom = 15;
            const xs = subNodes.map(n => n.x - (n._w || this.NODE_TYPES[n.type]?.w || 140) / 2);
            const xe = subNodes.map(n => n.x + (n._w || this.NODE_TYPES[n.type]?.w || 140) / 2);
            const ys = subNodes.map(n => n.y - (this.NODE_TYPES[n.type]?.h || 48) / 2);
            const ye = subNodes.map(n => n.y + (this.NODE_TYPES[n.type]?.h || 48) / 2);

            const x = Math.min(...xs) - marginX;
            const y = Math.min(...ys) - marginTop - 16; // Extra top for label
            const w = Math.max(...xe) - Math.min(...xs) + marginX * 2;
            const h = Math.max(...ye) - Math.min(...ys) + marginTop + marginBottom + 16;

            // Background fill
            ctx.beginPath();
            ctx.roundRect(x, y, w, h, 10);
            ctx.fillStyle = b.color;
            ctx.fill();

            // Dashed border
            ctx.setLineDash([6, 4]);
            ctx.strokeStyle = b.border;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.setLineDash([]);

            // Label (top-left corner) — boost opacity for readability
            ctx.fillStyle = b.border.replace(/[0-9a-f]{2}$/i, 'DD');
            ctx.font = 'bold 10px system-ui, sans-serif';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'top';
            ctx.fillText(`${b.label}${b.cidr ? '  (' + b.cidr + ')' : ''}`, x + 10, y + 5);
        }
    },

    _drawNode(n) {
        const ctx = this.ctx;
        const cfg = this.NODE_TYPES[n.type] || { w: 140, h: 48, color: '#7A849E' };

        // Auto-size width to fit longest text (label or sublabel) + icon padding
        ctx.font = 'bold 11px system-ui, sans-serif';
        const labelW = ctx.measureText(n.label).width;
        ctx.font = '10px system-ui, sans-serif';
        const subW = n.sublabel ? ctx.measureText(n.sublabel).width : 0;
        const textW = Math.max(labelW, subW);
        const iconPad = (cfg.awsIcon || cfg.fallbackIcon) ? 30 : 0;
        const w = Math.max(cfg.w, textW + iconPad + 30);
        const h = cfg.h;
        const x = n.x - w / 2, y = n.y - h / 2;
        // Store computed width for hit-testing
        n._w = w;
        const r = 8;
        const selected = this.selectedNode && this.selectedNode.id === n.id;

        // Background
        ctx.beginPath();
        ctx.roundRect(x, y, w, h, r);
        ctx.fillStyle = selected ? '#2A3050' : '#1C2031';
        ctx.fill();

        // Border
        let borderColor = cfg.color;
        if (n.type === 'beacon') {
            borderColor = n.health === 'alive' ? '#7ECF8C' : n.health === 'stale' ? '#F0CA4A' : '#F08A84';
            if (n.health === 'dead') ctx.globalAlpha = 0.5;
        }
        ctx.strokeStyle = borderColor;
        ctx.lineWidth = selected ? 3 : 1.5;
        ctx.stroke();

        // Double border for SYSTEM / admin beacons (elevated privilege indicator)
        if (n.type === 'beacon' && n.data && n.data.isAdmin) {
            ctx.beginPath();
            ctx.roundRect(x - 3, y - 3, w + 6, h + 6, r + 2);
            ctx.strokeStyle = '#F08A84';
            ctx.lineWidth = 1.2;
            ctx.setLineDash([4, 3]);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        // Type badge (small colored bar at top)
        ctx.beginPath();
        ctx.roundRect(x, y, w, 4, [r, r, 0, 0]);
        ctx.fillStyle = borderColor;
        ctx.fill();

        // Icon (left side of card) — AWS SVG or emoji fallback
        const iconSize = 18;
        const iconDrawn = cfg.awsIcon && this._iconCache[cfg.awsIcon];
        if (iconDrawn) {
            try {
                ctx.drawImage(this._iconCache[cfg.awsIcon], x + 7, n.y - iconSize / 2, iconSize, iconSize);
            } catch { /* ignore draw errors */ }
        } else if (cfg.fallbackIcon) {
            ctx.font = '14px system-ui, sans-serif';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = borderColor;
            ctx.fillText(cfg.fallbackIcon, x + 8, n.y);
        }

        // Label (line 1) — offset right to make room for icon
        const hasIcon = iconDrawn || cfg.fallbackIcon;
        const textX = hasIcon ? n.x + 10 : n.x;
        ctx.fillStyle = '#EEF0F6';
        ctx.font = 'bold 11px system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const labelY = h > 50 ? y + h * 0.35 : y + h * 0.4;
        ctx.fillText(n.label, textX, labelY);

        // Sublabel (line 2)
        if (n.sublabel) {
            ctx.fillStyle = '#B0B8CC';
            ctx.font = '10px system-ui, sans-serif';
            const subY = h > 50 ? y + h * 0.58 : y + h * 0.65;
            ctx.fillText(n.sublabel, textX, subY);
        }

        // Health dot for beacons
        if (n.type === 'beacon' && n.health) {
            const dotColor = n.health === 'alive' ? '#7ECF8C' : n.health === 'stale' ? '#F0CA4A' : '#F08A84';
            ctx.beginPath();
            ctx.arc(x + 10, y + h - 10, 4, 0, Math.PI * 2);
            ctx.fillStyle = dotColor;
            ctx.fill();
        }

        // State dot for infra nodes
        if (n.data && n.data.state) {
            const stateColor = n.data.state === 'running' ? '#7ECF8C' : n.data.state === 'stopped' ? '#F08A84' : '#F0CA4A';
            ctx.beginPath();
            ctx.arc(x + w - 10, y + 12, 4, 0, Math.PI * 2);
            ctx.fillStyle = stateColor;
            ctx.fill();
        }

        // Floating label
        if (n.floating) {
            ctx.fillStyle = '#7A849E';
            ctx.font = '9px system-ui, sans-serif';
            ctx.fillText(cfg.label, n.x, y - 6);
        }

        ctx.globalAlpha = 1;
    },

    _drawEdge(e) {
        const ctx = this.ctx;
        const from = this.nodes.find(n => n.id === e.from);
        const to = this.nodes.find(n => n.id === e.to);
        if (!from || !to) return;

        const fromCfg = this.NODE_TYPES[from.type] || { h: 48 };
        const toCfg = this.NODE_TYPES[to.type] || { h: 48 };
        const x1 = from.x, y1 = from.y + fromCfg.h / 2;
        const x2 = to.x, y2 = to.y - toCfg.h / 2;

        ctx.beginPath();
        ctx.strokeStyle = '#4A5168';
        ctx.lineWidth = 1.2;
        if (e.dashed) ctx.setLineDash([6, 4]);
        else ctx.setLineDash([]);

        // Bezier curve
        const midY = (y1 + y2) / 2;
        ctx.moveTo(x1, y1);
        ctx.bezierCurveTo(x1, midY, x2, midY, x2, y2);
        ctx.stroke();
        ctx.setLineDash([]);

        // Arrow
        const angle = Math.atan2(y2 - midY, x2 - x2);
        const arrowSize = 6;
        ctx.beginPath();
        ctx.moveTo(x2, y2);
        ctx.lineTo(x2 - arrowSize, y2 - arrowSize * 1.5);
        ctx.lineTo(x2 + arrowSize, y2 - arrowSize * 1.5);
        ctx.closePath();
        ctx.fillStyle = '#4A5168';
        ctx.fill();

        // Edge label
        if (e.label) {
            ctx.fillStyle = '#7A849E';
            ctx.font = '9px system-ui, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(e.label, (x1 + x2) / 2 + 20, midY);
        }
    },

    // ── Hit test: find node under cursor (graph coordinates) ──
    _hitTest(mx, my) {
        // Iterate in reverse so top-drawn nodes are hit first
        for (let i = this.nodes.length - 1; i >= 0; i--) {
            const n = this.nodes[i];
            const cfg = this.NODE_TYPES[n.type] || { w: 140, h: 48 };
            const w = n._w || cfg.w;
            if (mx >= n.x - w / 2 && mx <= n.x + w / 2 &&
                my >= n.y - cfg.h / 2 && my <= n.y + cfg.h / 2) {
                return n;
            }
        }
        return null;
    },

    // ── Convert mouse event to graph coordinates ──
    _toGraph(e) {
        const rect = this.canvas.getBoundingClientRect();
        return {
            x: (e.clientX - rect.left - this.panX) / this.scale,
            y: (e.clientY - rect.top - this.panY) / this.scale,
        };
    },

    // ── Zoom ──
    _handleWheel(e) {
        e.preventDefault();
        const delta = e.deltaY > 0 ? 0.9 : 1.1;
        const rect = this.canvas.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        this.panX = mx - (mx - this.panX) * delta;
        this.panY = my - (my - this.panY) * delta;
        this.scale *= delta;
        this.scale = Math.max(0.2, Math.min(3, this.scale));
        this._render();
    },

    // ── Mouse down: decide if dragging a node or panning ──
    _handleMouseDown(e) {
        const gp = this._toGraph(e);
        const hit = this._hitTest(gp.x, gp.y);

        this.isDragging = false;
        this.dragNode = null;
        this.dragNodeStart = null;

        if (hit) {
            // Start dragging this node
            this.dragNode = hit;
            this.dragNodeStart = { x: hit.x, y: hit.y };
            this.dragStart = { x: e.clientX, y: e.clientY, px: this.panX, py: this.panY };
            this.canvas.style.cursor = 'grabbing';
        } else {
            // Start panning canvas
            this.dragStart = { x: e.clientX, y: e.clientY, px: this.panX, py: this.panY };
            this.canvas.style.cursor = 'grabbing';
        }
    },

    _handleMouseMove(e) {
        if (!this.dragStart) {
            // Hover cursor: show pointer over nodes
            const gp = this._toGraph(e);
            const hover = this._hitTest(gp.x, gp.y);
            this.canvas.style.cursor = hover ? 'pointer' : 'grab';
            return;
        }

        const dx = e.clientX - this.dragStart.x;
        const dy = e.clientY - this.dragStart.y;
        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) this.isDragging = true;

        if (this.dragNode) {
            // Move the node in graph space
            this.dragNode.x = this.dragNodeStart.x + dx / this.scale;
            this.dragNode.y = this.dragNodeStart.y + dy / this.scale;
            this._render();
        } else {
            // Pan the canvas
            this.panX = this.dragStart.px + dx;
            this.panY = this.dragStart.py + dy;
            this._render();
        }
    },

    _handleMouseUp(e) {
        const wasDragging = this.isDragging;
        const wasDragNode = this.dragNode;

        // If it was a click (no movement), select the node + show side panel
        if (!wasDragging && this.dragStart && e) {
            const gp = this._toGraph(e);
            const hit = this._hitTest(gp.x, gp.y);
            if (hit) {
                this.selectedNode = hit;
                this._showSidePanel(hit);
                this._render();
            }
        }

        this.dragStart = null;
        this.dragNode = null;
        this.dragNodeStart = null;
        this.canvas.style.cursor = 'grab';
        setTimeout(() => { this.isDragging = false; }, 50);
    },

    // ── Reset layout to computed positions ──
    _resetLayout() {
        this._layoutNodes();
        this._render();
    },

    // ── Beacon status banner ──
    _updateBeaconBanner() {
        const banner = this.overlay?.querySelector('#topology-beacon-banner');
        if (!banner) return;

        if (this.beaconStatus === 'connected') {
            banner.style.display = 'none';
        } else if (this.beaconStatus === 'no_beacons') {
            banner.style.display = '';
            banner.innerHTML = 'CS REST API connected — no active beacons to display';
            banner.style.borderColor = '#82BBE8';
        } else if (this.beaconStatus === 'wrong_server') {
            banner.style.display = '';
            banner.innerHTML = `REST API is connected to a different team server (${this._esc(this._connectedServerIp)}) — beacons not shown for this deployment`;
            banner.style.borderColor = '#F0CA4A';
        } else {
            banner.style.display = '';
            // Build the REST API tunnel command from infra data
            const d = this.infraData || {};
            const tsIp = (d.c2_servers && d.c2_servers[0]?.private_ip) || d.teamserver_private_ip || '';
            const bastionIp = d.bastion_public_ip || '';
            const jumpboxIp = d.jumpbox_public_ip || '';
            const jumpHost = bastionIp || jumpboxIp;
            let tunnelBtn = '';
            if (tsIp && jumpHost) {
                const cmd = `ssh -L 50443:${tsIp}:50443 -i ~/.ssh/id_ed25519 -o StrictHostKeyChecking=no ubuntu@${jumpHost}`;
                tunnelBtn = ` <button class="btn btn-sm btn-warning" style="margin-left: 12px; pointer-events: auto;" onclick="TOPOLOGY.close(); APP.showPage('terminal'); setTimeout(() => TERMINAL.openTunnel('REST API Tunnel', '${cmd.replace(/'/g, "\\'")}'), 500);">Open REST API Tunnel</button>`;
            }
            banner.innerHTML = `Beacons not shown — CS REST API not connected${tunnelBtn}`;
            banner.style.borderColor = '#F0CA4A';
            banner.style.pointerEvents = 'auto';
        }
    },

    // ── Side panel ──
    _showSidePanel(node) {
        const panel = this.sidePanel;
        const body = this.sidePanelBody;
        const title = this.overlay.querySelector('#topology-side-title');
        const cfg = this.NODE_TYPES[node.type] || { label: 'Node' };

        title.textContent = node.label;
        let html = '';

        // Type badge
        html += `<div class="topology-node-badge" style="background: ${cfg.color}22; color: ${cfg.color}; border: 1px solid ${cfg.color}44; margin-bottom: 12px;">${cfg.label}</div>`;

        // Common details
        html += '<div class="topology-section-title">Details</div>';
        const d = node.data || {};

        if (node.type === 'operator') {
            html += this._row('Access', d.access);
            html += this._row('Port', d.port);
            html += '<div class="topology-section-title">IP Allowlist</div>';
            // Get the management CIDRs from config
            const mgmtCidrs = this.configData?.management_cidr_blocks || this.configData?.operator_ips || [];
            if (Array.isArray(mgmtCidrs) && mgmtCidrs.length > 0) {
                mgmtCidrs.forEach(cidr => { html += this._row('Allowed', cidr); });
            } else {
                // Try to get from dashboard allowed IPs
                const dashIps = this.configData?.dashboard_allowed_ips || [];
                if (Array.isArray(dashIps) && dashIps.length > 0) {
                    dashIps.forEach(ip => { html += this._row('Allowed', ip); });
                } else {
                    html += this._row('Allowed', 'Check terraform.tfvars');
                }
            }
            html += '<div class="topology-section-title">Requirements</div>';
            html += this._row('SSH client', 'Required');
            html += this._row('Browser', 'http://localhost:5000');
            html += this._row('AWS CLI', 'Not needed');
        } else if (node.type === 'dashboard') {
            html += this._row('Public IP', d.public_ip);
            html += this._row('VPC CIDR', d.vpc_cidr);
            html += this._row('Subnet', d.subnet);
            html += this._row('Instance', d.instance_type);
            html += this._row('State', d.state);
            html += '<div class="topology-section-title">Access</div>';
            html += this._row('SSH Tunnel', d.access);
            html += this._row('Dashboard', 'http://localhost:5000');
            html += '<div class="topology-section-title">Peering</div>';
            html += this._row('Peering', 'VPC peering to deployment VPCs for direct SSH access');
        } else if (node.type === 'domain') {
            html += this._row('Domain', d.domain);
            if (d.nameservers && d.nameservers.length) {
                html += '<div class="topology-section-title">Nameservers</div>';
                d.nameservers.forEach(ns => { html += this._row('NS', ns); });
            }
        } else if (node.type === 'cloudfront') {
            html += this._row('Distribution', d.distribution_id);
            html += this._row('Domain', d.domain);
        } else if (node.type === 'redirector') {
            html += this._row('Public IP', d.public_ip);
            html += this._row('Private IP', d.private_ip);
            html += this._row('Instance', d.instance_id);
            html += this._row('State', d.state);
        } else if (node.type === 'teamserver') {
            html += this._row('Private IP', d.private_ip);
            html += this._row('Instance', d.instance_id);
            html += this._row('State', d.state);
            html += this._row('Phase', d.phase);
            if (d.cs_password) html += this._row('CS Password', d.cs_password);
            if (d.profile) html += this._row('Profile', d.profile);
        } else if (node.type === 'bastion') {
            html += this._row('Public IP', d.public_ip);
            html += this._row('Private IP', d.private_ip);
            html += this._row('Instance', d.instance_id);
            html += this._row('State', d.state);
        } else if (node.type === 'attackbox') {
            html += this._row('Private IP', d.private_ip);
            html += this._row('Instance', d.instance_id);
            html += this._row('State', d.state);
            if (d.password) html += this._row('Password', d.password);
        } else if (node.type === 'listener') {
            html += this._row('Name', d.name);
            html += this._row('Type', d.type || d.payload);
            html += this._row('Host', d.host || d.Host);
            html += this._row('Port', d.port || d.Port);
            if (d.profile) {
                html += '<div class="topology-section-title">C2 Profile</div>';
                html += this._row('Profile', d.profile);
            }
            if (d.beacon_total !== undefined) {
                html += '<div class="topology-section-title">Beacons</div>';
                html += this._row('Total', d.beacon_total);
                html += this._row('Root (direct)', d.beacon_count);
                html += this._row('Alive', d.beacon_alive);
            }
            // Show any extra listener fields from the API
            const shown = new Set(['name','type','payload','host','Host','port','Port','profile','beacon_count','beacon_alive','beacon_total']);
            Object.entries(d).forEach(([k, v]) => {
                if (!shown.has(k) && v && typeof v !== 'object') html += this._row(k, v);
            });
        } else if (node.type === 'beacon') {
            html += this._row('Beacon ID', d.bid);
            html += this._row('Host', d.computer);
            html += this._row('User', d.user);
            html += this._row('PID', d.pid);
            html += this._row('Process', d.process);
            html += this._row('Internal IP', d.internal);
            html += this._row('OS', d.os);
            html += this._row('Admin', d.isAdmin ? '★ Yes' : 'No');
            html += '<div class="topology-section-title">Timing</div>';
            const sleepSec = d.sleep ? (d.sleep >= 1000 ? (d.sleep / 1000) : d.sleep) : null;
            html += this._row('Sleep', sleepSec !== null ? sleepSec + 's' : 'Unknown');
            html += this._row('Health', d.health);
            html += this._row('Listener', d.listener);
        } else if (node.type === 'jumpbox') {
            html += this._row('Public IP', d.public_ip);
            html += this._row('Private IP', d.private_ip);
            html += this._row('Instance', d.instance_id);
            html += this._row('State', d.state);
        } else if (node.type === 's3_bucket') {
            html += this._row('Bucket', d.bucket_name);
            html += this._row('Contents', d.contents);
            html += this._row('Encryption', d.encryption);
            if (d.upload_command) {
                html += '<div class="topology-section-title">Upload Command</div>';
                html += this._row('Command', d.upload_command);
            }
        } else if (node.type === 'nat_gateway') {
            html += this._row('Purpose', d.purpose);
            html += this._row('Serves', d.serves);
            html += this._row('AWS Placement', d.actual_placement);
            html += this._row('Cost', d.cost);
            if (d.note) html += this._row('Note', d.note);
        } else if (node.type === 'goad_vm') {
            html += this._row('Private IP', d.private_ip);
            html += this._row('Instance', d.instance_id);
            html += this._row('State', d.state);
        } else {
            Object.entries(d).forEach(([k, v]) => {
                if (v) html += this._row(k, v);
            });
        }

        // Copy actions
        const copyIp = d.public_ip || d.private_ip;
        if (copyIp) {
            html += `<div class="topology-side-actions">
                <button class="btn btn-sm btn-info" onclick="navigator.clipboard.writeText('${this._esc(copyIp)}')">Copy IP</button>
            </div>`;
        }

        body.innerHTML = html;
        panel.classList.add('open');
    },

    _closeSide() {
        this.sidePanel.classList.remove('open');
        this.selectedNode = null;
        this._render();
    },

    _row(label, value) {
        if (value === null || value === undefined || value === '') return '';
        const v = String(value);
        return `<div class="topology-detail-row">
            <span class="topology-detail-label">${this._esc(label)}</span>
            <span class="topology-detail-value" onclick="navigator.clipboard.writeText('${this._esc(v)}')" title="Click to copy">${this._esc(v)}</span>
        </div>`;
    },

    // Get actual port labels between two roles from live SG rules
    _getSgLabel(sourceRole, destRole) {
        if (!this._sgRules) return null; // Fallback to static labels
        const ports = [];
        const portNames = { '22': 'SSH', '80': 'HTTP', '443': 'HTTPS', '3389': 'RDP', '50050': 'CS', '50443': 'REST', '5985': 'WinRM' };
        for (const rule of this._sgRules) {
            if (rule.source_role === sourceRole && rule.dest_role === destRole) {
                const name = portNames[rule.port] || rule.port;
                const label = `${name}/${rule.port}`;
                if (!ports.includes(label)) ports.push(label);
            }
        }
        return ports.length > 0 ? ports.join(' · ') : null;
    },

    _esc(s) {
        if (!s) return '';
        const d = document.createElement('div');
        d.textContent = String(s);
        return d.innerHTML;
    },
};


// ============================================================================
// Version modal helpers (P1 #7.6)
// ============================================================================

/**
 * Open the version modal. Idempotent. Delegates to canonical APP.modal.open
 * which handles backdrop / Esc / focus return (M-Redesign Agent 2 v2.0.0).
 */
function openVersionModal() {
    const footer = document.getElementById('app-version-footer');
    APP.modal.open('version-modal', { returnFocusTo: footer });
}

/**
 * Close the version modal. Idempotent. Delegates to canonical APP.modal.close.
 */
function closeVersionModal() {
    APP.modal.close('version-modal');
}

// ============================================================================
// APPLICATION INITIALIZATION
// ============================================================================

// === D8 Agent B — Deployments → Cleanup sub-pill ============================
// PHASE 3C — V3-native rebuild. Renders the cleanup view using the Phase 2b
// spec-list primitives + bespoke summary tiles. The original D8 detection
// logic is unchanged (still client-side from /api/deploy/resources/all-projects);
// only the rendering layer and the localStorage schema were touched.
//
// LocalStorage schema migration (Phase 3c):
//   v1 (legacy, D8):  ["eip::abc", "acm::xyz"]                  (array of strings)
//   v2 (Phase 3c):    { "eip::abc": { id, by, at }, ... }       (id-keyed map)
// `_cleanupReadKnown()` auto-migrates v1 → v2 on first read and writes the
// migrated map back. v1 entries get { by: null, at: null } so they still
// render in the marked state but with "marked by unknown" attribution.
//
// Per-row actions are still alert() stubs — destructive ops remain
// operator-driven via AWS CLI to keep this surface read-only and safe.
//
// All cleanup state + functions are namespaced under APP.cleanup so the
// global function names (loadCleanupResources, cleanupMarkKnown, etc.)
// are thin wrappers for backwards-compat with the existing onclick attrs.

const CLEANUP_KNOWN_KEY = 'cleanup.knownExternal.v1';

APP.cleanup = APP.cleanup || {
    /**
     * Read the known-external map from localStorage. Auto-migrates the
     * legacy v1 (array-of-string) format to the v2 (id-keyed map) format
     * with attribution fields. Returns an object keyed by resourceId →
     * { id, by, at } where `by` is the operator id (string|null) and
     * `at` is an ISO timestamp (string|null).
     */
    readKnown() {
        let raw;
        try { raw = localStorage.getItem(CLEANUP_KNOWN_KEY); }
        catch (_) { return {}; }
        if (!raw) return {};
        let parsed;
        try { parsed = JSON.parse(raw); } catch (_) { return {}; }

        // v1 → v2 migration: array-of-strings → id-keyed map.
        if (Array.isArray(parsed)) {
            const migrated = {};
            parsed.forEach(id => {
                if (typeof id === 'string') {
                    migrated[id] = { id, by: null, at: null };
                }
            });
            try { localStorage.setItem(CLEANUP_KNOWN_KEY, JSON.stringify(migrated)); }
            catch (_) { /* quota or disabled — silent */ }
            return migrated;
        }
        // v2 — guard against corrupt entries.
        if (parsed && typeof parsed === 'object') {
            const clean = {};
            Object.keys(parsed).forEach(k => {
                const entry = parsed[k];
                if (entry && typeof entry === 'object') {
                    clean[k] = {
                        id: entry.id || k,
                        by: entry.by || null,
                        at: entry.at || null,
                    };
                }
            });
            return clean;
        }
        return {};
    },

    /**
     * Mark a resource as known-external. Records the current operator id
     * + ISO timestamp. Idempotent — re-marking updates the timestamp.
     */
    addKnown(id) {
        if (!id) return;
        const map = APP.cleanup.readKnown();
        const opId = (APP.operator && APP.operator.current && APP.operator.current.id) || null;
        map[id] = { id, by: opId, at: new Date().toISOString() };
        try { localStorage.setItem(CLEANUP_KNOWN_KEY, JSON.stringify(map)); }
        catch (_) { /* silent */ }
    },

    /** Stable, type-prefixed resource id used for storage + DOM lookup. */
    resourceId(item, kind) {
        return [
            kind,
            item.allocation_id || item.AllocationId ||
            item.arn || item.Arn ||
            item.domain || item.DomainName ||
            item.name || item.Name ||
            item.public_ip || item.PublicIp ||
            JSON.stringify(item).slice(0, 64)
        ].join('::');
    },

    /** Lookup operator metadata (display + color) by id. Falls back gracefully. */
    operatorFor(opId) {
        if (!opId || !APP.operator || !Array.isArray(APP.operator.all)) {
            return { display: 'unknown', color: '#7A849E', id: null };
        }
        const found = APP.operator.all.find(o => o.id === opId);
        if (found) return { display: found.display || found.id, color: found.color || '#7A849E', id: found.id };
        return { display: opId, color: '#7A849E', id: opId };
    },

    /** Pretty-print an ISO timestamp using the existing relative-time util. */
    formatTime(iso) {
        if (!iso) return '';
        if (typeof _relativeTime === 'function') return _relativeTime(iso);
        try { return new Date(iso).toLocaleString(); } catch (_) { return ''; }
    },

    /** Format the small mono caps last-refreshed-at hint. */
    formatRefreshedAt(date) {
        try {
            const d = (date instanceof Date) ? date : new Date(date);
            const hh = String(d.getHours()).padStart(2, '0');
            const mm = String(d.getMinutes()).padStart(2, '0');
            const ss = String(d.getSeconds()).padStart(2, '0');
            return `LAST SCAN ${hh}:${mm}:${ss}`;
        } catch (_) { return ''; }
    },
};

// Legacy aliases preserved for any external callers that referenced the
// underscored helpers directly.
function _cleanupGetKnownExternal() {
    // Returns a Set of marked ids for code paths that only need membership.
    return new Set(Object.keys(APP.cleanup.readKnown()));
}
function _cleanupAddKnownExternal(id) { APP.cleanup.addKnown(id); }
function _cleanupResourceId(item, kind) { return APP.cleanup.resourceId(item, kind); }

async function loadCleanupResources(forceRefresh = false) {
    const list = document.getElementById('cleanup-resource-list');
    if (!list) return;
    const refreshBtn = document.getElementById('cleanup-refresh-btn');
    if (refreshBtn) refreshBtn.setAttribute('data-loading', 'true');
    if (APP && typeof APP.renderSkeleton === 'function') {
        APP.renderSkeleton('cleanup-resource-list', 'card', 3);
    }
    try {
        const url = '/api/deploy/resources/all-projects' + (forceRefresh ? '?refresh=1' : '');
        const res = await fetch(url);
        const data = await res.json();
        const orphans = _detectOrphans(data);
        const known = APP.cleanup.readKnown();

        const setText = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
        // Summary tiles ALWAYS render — 0s are still informative ("scan ran,
        // no orphans found") and prevent the "page is empty" UX complaint.
        setText('cleanup-orphan-count', orphans.total);
        setText('cleanup-eip-count', orphans.eips.length);
        setText('cleanup-acm-count', orphans.acm_certs.length);
        setText('cleanup-buckets-count', orphans.s3_buckets.length);

        // Last-refreshed-at hint
        const refreshedAt = document.getElementById('cleanup-refreshed-at');
        if (refreshedAt) {
            refreshedAt.textContent = APP.cleanup.formatRefreshedAt(new Date());
            refreshedAt.hidden = false;
        }

        if (orphans.total === 0) {
            // No orphans detected — keep the 4 summary tiles visible above
            // (set via setText) and render a rich empty-state below with:
            //   1. The "all-clear" message
            //   2. A scan-scope readout (totals before orphan filtering)
            //   3. A per-deployment summary so operators see WHAT was scanned
            //   4. A Refresh affordance in the list area itself
            list.innerHTML = _renderCleanupEmptyState(data);
            return;
        }
        list.innerHTML = _renderCleanupGroups(orphans, known);
        if (APP && typeof APP._staggerOnce === 'function') APP._staggerOnce(list);
    } catch (e) {
        list.innerHTML = '<div class="callout callout--warning">Failed to load resources. Check AWS credentials.</div>';
    } finally {
        if (refreshBtn) refreshBtn.removeAttribute('data-loading');
    }
}

/**
 * Render the "no orphans" empty-state with deployment summary.
 *
 * The user's 2026-05-19 complaint was that the Cleanup page appeared
 * blank when no orphans were found. The 4 summary tiles already render
 * (with 0s) but the main resource list area was visually empty, which
 * read as broken. This adds:
 *   - scan-scope readout (the operator sees WHAT was scanned)
 *   - per-project deployment summary (resource counts + region)
 *   - inline Refresh affordance in the list area
 */
function _renderCleanupEmptyState(data) {
    const projects = (data && Array.isArray(data.projects)) ? data.projects : [];
    const region = (data && data.region) ? data.region : '—';

    // Tally raw scan counts (before orphan filtering) so the operator can
    // see the scope, not just an empty result.
    const totalEips = ((data && data.eips) || []).length;
    const totalAcm = (((data && data.acm_certs) || []).length) + (((data && data.acm_us_east_1) || []).length);
    const totalBuckets = ((data && data.s3_buckets) || []).length;
    const totalSnaps = ((data && data.snapshots) || []).length;

    let projectsBlock = '';
    if (projects.length) {
        const rows = projects.map(p => {
            const name = escapeHtml(p.project_name || '—');
            const dtype = escapeHtml(p.deployment_type || '—');
            const projRegion = escapeHtml(p.region || region);
            const count = (p.resource_count != null) ? p.resource_count : 0;
            return `
            <div class="spec-row cleanup-summary-row" data-kind="deployment">
                <div class="spec-row__head">
                    <div class="spec-row__key">${dtype.toUpperCase()}</div>
                    <div class="spec-row__value">${name}</div>
                    <div class="cleanup-summary-row__meta">
                        <span class="cleanup-summary-row__count">${count} resources</span>
                        <span class="cleanup-summary-row__region">${projRegion}</span>
                    </div>
                </div>
            </div>`;
        }).join('');
        projectsBlock = `
            <section class="cleanup-group cleanup-empty__projects" data-group-kind="summary">
                <header class="cleanup-group__header">
                    <h4 class="cleanup-group__title">Tracked Deployments</h4>
                    <span class="cleanup-group__count">${projects.length} active</span>
                </header>
                <div class="spec-list cleanup-group__list" role="list" aria-label="Tracked deployments">
                    ${rows}
                </div>
            </section>`;
    }

    const scopeBits = [
        `${totalEips} EIPs`,
        `${totalAcm} ACM certs`,
        `${totalBuckets} S3 buckets`,
        `${totalSnaps} snapshots`,
    ];

    return `
        <div class="empty-state cleanup-empty">
            <div class="empty-state__icon"><span class="empty-state__icon-inner"></span></div>
            <h3 class="empty-state__title">No orphan resources detected</h3>
            <p class="empty-state__description">
                All AWS resources in <code>${escapeHtml(region)}</code> are tracked by an active deployment.
            </p>
            <p class="cleanup-empty__scope">
                Scan inspected ${scopeBits.map(b => `<span>${escapeHtml(b)}</span>`).join(' &middot; ')}.
            </p>
            <div class="empty-state__cta">
                <button class="spec-edit-btn" type="button" onclick="loadCleanupResources(true)">
                    <svg class="icon icon--sm" aria-hidden="true"><use href="#icon-refresh"/></svg>
                    Re-scan AWS
                </button>
            </div>
        </div>
        ${projectsBlock}
    `;
}

function _detectOrphans(data) {
    // Phase 3c: detection no longer FILTERS marked-known items — instead it
    // tags them so the renderer can display them with attribution. This
    // preserves operator audit visibility ("Alice marked this 3d ago")
    // rather than silently hiding the entry on next load.
    const orphans = {
        eips: [],
        acm_certs: [],
        s3_buckets: [],
        snapshots: [],
        workspaces: [],
        total: 0
    };

    // Unattached EIPs — floating allocation.
    //
    // 2026-05-19: An EIP attached to a NAT gateway shows `instance_id=null`
    // but has a `network_interface_id` AND a Project tag from Terraform.
    // The original rule (!instance_id) over-flagged every NAT EIP as an
    // orphan. Real orphans either have no binding at all (no instance and
    // no NIC) or have a binding but no Project tag (e.g. console-created
    // resources). Both branches are kept distinct so the rule is auditable.
    (data.eips || []).forEach(e => {
        const hasInstance = !!(e.instance_id || e.InstanceId);
        const hasNic = !!(e.network_interface_id || e.NetworkInterfaceId);
        const hasProjectTag = !!(e.project_tag || e.ProjectTag);
        const floating = !hasInstance && !hasNic;
        const untaggedBinding = (hasInstance || hasNic) && !hasProjectTag;
        if (floating || untaggedBinding) {
            const id = APP.cleanup.resourceId(e, 'eip');
            orphans.eips.push(Object.assign({ _id: id, _kind: 'eip' }, e));
        }
    });

    // ACM certs (eu-central-1 + us-east-1 from D5.0) — anything not in-use is an orphan.
    const allAcm = (data.acm_certs || []).concat(data.acm_us_east_1 || []);
    allAcm.forEach(c => {
        if (!c.in_use) {
            const id = APP.cleanup.resourceId(c, 'acm');
            orphans.acm_certs.push(Object.assign({ _id: id, _kind: 'acm' }, c));
        }
    });

    // S3 buckets — anything outside the project naming convention.
    const projectRe = /^(c2-adhoc|c2-purple|c2-full|goad-mini|goad-light|goad-sccm|goad-full|goad-nha|combined-)|redteam-dashboard-tfstate/;
    (data.s3_buckets || []).forEach(b => {
        const name = b.name || b.Name || '';
        if (!projectRe.test(name)) {
            const id = APP.cleanup.resourceId(b, 's3');
            orphans.s3_buckets.push(Object.assign({ _id: id, _kind: 's3' }, b));
        }
    });

    orphans.total = orphans.eips.length + orphans.acm_certs.length +
                    orphans.s3_buckets.length + orphans.snapshots.length +
                    orphans.workspaces.length;
    return orphans;
}

function _renderCleanupGroups(orphans, known) {
    const groups = [];
    known = known || APP.cleanup.readKnown();

    if (orphans.eips.length > 0) {
        groups.push(_renderGroup({
            title: 'Unattached Elastic IPs',
            kind: 'eip',
            items: orphans.eips,
            keyFor: (e) => 'ELASTIC IP',
            valueFor: (e) => e.public_ip || e.PublicIp || '—',
            hintFor: (e) => {
                const parts = [];
                if (e.allocation_id || e.AllocationId) parts.push(e.allocation_id || e.AllocationId);
                if (e.region) parts.push(e.region);
                return parts.join(' · ');
            },
            known,
        }));
    }
    if (orphans.acm_certs.length > 0) {
        groups.push(_renderGroup({
            title: 'Orphan ACM Certificates',
            kind: 'acm',
            items: orphans.acm_certs,
            keyFor: (c) => 'ACM CERT',
            valueFor: (c) => c.domain || c.DomainName || '—',
            hintFor: (c) => {
                const parts = [];
                if (c.region) parts.push(c.region); else parts.push('eu-central-1');
                if (c.status || c.Status) parts.push(c.status || c.Status);
                return parts.join(' · ');
            },
            known,
        }));
    }
    if (orphans.s3_buckets.length > 0) {
        groups.push(_renderGroup({
            title: 'Untagged S3 Buckets',
            kind: 's3',
            items: orphans.s3_buckets,
            keyFor: (b) => 'S3 BUCKET',
            valueFor: (b) => b.name || b.Name || '—',
            hintFor: (b) => {
                const parts = [];
                if (b.region) parts.push(b.region);
                if (b.creation_date || b.CreationDate) parts.push(b.creation_date || b.CreationDate);
                return parts.join(' · ');
            },
            known,
        }));
    }
    return groups.join('');
}

function _renderGroup(opts) {
    const { title, items, keyFor, valueFor, hintFor, known } = opts;
    const rows = items.map((item) => {
        const safeId = escapeHtml(item._id || '');
        const isMarked = !!known[item._id];
        const markedEntry = isMarked ? known[item._id] : null;
        const op = markedEntry ? APP.cleanup.operatorFor(markedEntry.by) : null;
        const rowAttrs = isMarked ? ' data-marked-known="true"' : '';

        let valueMeta = `<div class="spec-row__value">${escapeHtml(valueFor(item))}</div>`;
        if (isMarked) {
            const opColor = escapeHtml(op.color || '#7A849E');
            const opName = escapeHtml(op.display || 'unknown');
            const when = escapeHtml(APP.cleanup.formatTime(markedEntry.at));
            valueMeta = `
                <div class="cleanup-row__value-meta">
                    <div class="cleanup-row__value-meta-row">
                        <span class="spec-row__value">${escapeHtml(valueFor(item))}</span>
                        <span class="spec-pill spec-pill--draft" data-state="marked-known">
                            <span class="spec-pill__dot"></span>KNOWN
                        </span>
                    </div>
                    <span class="cleanup-row__attribution" data-attribution>
                        <span class="cleanup-row__attribution-dot" style="background: ${opColor}"></span>
                        marked by ${opName}${when ? ' · ' + when : ''}
                    </span>
                </div>`;
        }

        return `
        <div class="spec-row cleanup-row" data-resource-id="${safeId}" data-kind="${escapeHtml(item._kind || '')}"${rowAttrs}>
            <div class="spec-row__head">
                <div class="spec-row__key">${escapeHtml(keyFor(item))}</div>
                ${valueMeta}
                <div class="cleanup-row__actions">
                    <button class="spec-edit-btn cleanup-row__action"
                            type="button"
                            onclick="cleanupAdoptResource('${safeId}')"
                            aria-label="Adopt into Terraform">
                        <svg class="icon icon--sm" aria-hidden="true"><use href="#icon-link"/></svg>
                        Adopt
                    </button>
                    <button class="spec-edit-btn spec-edit-btn--danger cleanup-row__action"
                            type="button"
                            onclick="cleanupDestroyResource('${safeId}')"
                            aria-label="Destroy resource">
                        <svg class="icon icon--sm" aria-hidden="true"><use href="#icon-trash"/></svg>
                        Destroy
                    </button>
                    <button class="spec-edit-btn cleanup-row__action"
                            type="button"
                            onclick="cleanupMarkKnown('${safeId}')"
                            aria-label="Mark as known-external">
                        ${isMarked ? '' : '<svg class="icon icon--sm" aria-hidden="true"><use href="#icon-check"/></svg>'}
                        ${isMarked ? 'Re-mark' : 'Mark known'}
                    </button>
                </div>
            </div>
        </div>`;
    }).join('');
    return `
        <section class="cleanup-group" data-group-kind="${escapeHtml(opts.kind || '')}">
            <header class="cleanup-group__header">
                <h4 class="cleanup-group__title">${escapeHtml(title)}</h4>
                <span class="cleanup-group__count">${items.length} found</span>
            </header>
            <div class="spec-list cleanup-group__list" role="list" aria-label="${escapeHtml(title)}">
                ${rows}
            </div>
        </section>`;
}

function cleanupAdoptResource(_id) {
    alert('Adopt into Terraform — manual step. See docs/ for terraform import syntax for this resource type.');
}

function cleanupDestroyResource(_id) {
    alert('Destroy via AWS CLI — operator must confirm in console. No destructive backend endpoint is wired by design.');
}

function cleanupMarkKnown(id) {
    if (!id) return;
    APP.cleanup.addKnown(id);
    // Phase 3c: row stays visible with attribution. Refresh the row in-place
    // by re-fetching just the marked entry (no full re-scan needed for this
    // single state flip).
    const row = document.querySelector(`.cleanup-row[data-resource-id="${CSS.escape(id)}"]`);
    if (!row) return;
    const entry = APP.cleanup.readKnown()[id];
    if (!entry) return;
    const op = APP.cleanup.operatorFor(entry.by);
    row.setAttribute('data-marked-known', 'true');
    // Wrap the existing value into the value-meta + attribution layout.
    const head = row.querySelector('.spec-row__head');
    const value = head ? head.querySelector('.spec-row__value') : null;
    if (value && head && !head.querySelector('[data-attribution]')) {
        const valueText = value.textContent;
        const wrapper = document.createElement('div');
        wrapper.className = 'cleanup-row__value-meta';
        wrapper.innerHTML = `
            <div class="cleanup-row__value-meta-row">
                <span class="spec-row__value">${escapeHtml(valueText)}</span>
                <span class="spec-pill spec-pill--draft" data-state="marked-known">
                    <span class="spec-pill__dot"></span>KNOWN
                </span>
            </div>
            <span class="cleanup-row__attribution" data-attribution>
                <span class="cleanup-row__attribution-dot" style="background: ${escapeHtml(op.color)}"></span>
                marked by ${escapeHtml(op.display)}${entry.at ? ' · ' + escapeHtml(APP.cleanup.formatTime(entry.at)) : ''}
            </span>`;
        value.replaceWith(wrapper);
    }
    // Update the action button label.
    const markBtn = row.querySelector('button[onclick^="cleanupMarkKnown"]');
    if (markBtn) markBtn.textContent = 'Re-mark';
}
// === end D8 Agent B (Phase 3c V3-native) ====================================

// ============================================================================
// === M-Operators (Decision #23) — operator chip + menu + activity feed ====
// ============================================================================
// Backend contract (Agent A):
//   GET    /api/operators            → { success, operators, current, default }
//   POST   /api/operators            → { success, operator }
//   POST   /api/operators/switch     → { success, current }  (sets cookie)
//   GET    /api/audit?limit=&op=&action_prefix=&project=&target= → { success, entries, count }
// Frontend reuses APP.modal, APP.toast, escapeHtml; no new utilities.
// ============================================================================

APP.operator = {
    current: null,
    all: [],
    _listeners: [],
    onChange(fn) { this._listeners.push(fn); },
    _notify() {
        this._listeners.forEach(fn => { try { fn(this.current); } catch (_) { /* ignore */ } });
    },
};

// ──────────────────────────────────────────────────────────────────────
// task #33 — APP.presence: soft "who else is here" banner.
//
// Per Decision #23: NO locking, NO blocking. When two operators land on
// the same project's Configure or Manage view, both see a small banner
// "Alice is also viewing this project." That's it.
//
// Architecture
//   - Single setInterval started by APP.presence.start() on shell init.
//   - Each tick: if we're on Configure/Manage AND there's an active
//     project, POST /api/presence/heartbeat and re-render the banner
//     from response.others. Otherwise tick is a cheap no-op.
//   - The banner element is created lazily and injected at the top of
//     #subpill-pane-configure / #subpill-pane-manage (whichever is
//     visible). It's a thin info strip — never a scrim.
//   - Dismissals are remembered by the SET of operator ids in the
//     current `others` payload. If a new operator joins (id not in the
//     dismissed set) the banner reappears so the operator isn't kept in
//     the dark about a fresh collision.
// ──────────────────────────────────────────────────────────────────────
APP.presence = (function () {
    const HEARTBEAT_MS = 30000;          // 30s — matches backend freshness window
    const BANNER_ID = 'presence-banner';
    const PRESENCE_PAGES = { configure: 'subpill-pane-configure', manage: 'subpill-pane-manage' };

    let _timerId = null;
    let _dismissedSig = null;  // signature of the dismissed `others` set, e.g. "alice,bob"

    function _currentPage() {
        // Presence only fires on Configure + Manage. Both live inside the
        // 'deployments-tab' parent — read APP.currentSubPill to disambiguate.
        if (APP.currentPage !== 'deployments-tab') return null;
        const sub = APP.currentSubPill;
        if (sub && PRESENCE_PAGES[sub]) return sub;
        return null;
    }

    function _project() {
        if (!APP.activeDeployment) return null;
        // Sentinels (`__draft__`, `__all__`) are not real projects — skip
        // the heartbeat entirely so the backend doesn't get garbage.
        if (APP.activeDeployment.isDraft && APP.activeDeployment.isDraft()) return null;
        if (APP.activeDeployment.isAll && APP.activeDeployment.isAll()) return null;
        return APP.activeDeployment.current || null;
    }

    function _opLookup(id) {
        if (!id) return null;
        const all = (APP.operator && Array.isArray(APP.operator.all)) ? APP.operator.all : [];
        return all.find(o => o.id === id) || null;
    }

    function _relativeTime(iso) {
        if (!iso) return '';
        const ts = Date.parse(iso);
        if (!ts || Number.isNaN(ts)) return '';
        const delta = Math.max(0, Math.floor((Date.now() - ts) / 1000));
        if (delta < 60) return `${delta}s ago`;
        if (delta < 3600) return `${Math.floor(delta / 60)}m ago`;
        return `${Math.floor(delta / 3600)}h ago`;
    }

    function _ensureBanner(parent) {
        if (!parent) return null;
        let banner = parent.querySelector(`#${BANNER_ID}`);
        if (banner) return banner;
        banner = document.createElement('div');
        banner.id = BANNER_ID;
        banner.className = 'presence-banner';
        banner.setAttribute('role', 'status');
        banner.setAttribute('aria-live', 'polite');
        // Slot at the top of the pane, ahead of any existing children.
        parent.insertBefore(banner, parent.firstChild);
        return banner;
    }

    function _hideBanner() {
        const banner = document.getElementById(BANNER_ID);
        if (banner) banner.hidden = true;
    }

    function _signature(others) {
        return (others || []).map(o => o.operator_id).sort().join(',');
    }

    function _render(others) {
        const pageKey = _currentPage();
        if (!pageKey) { _hideBanner(); return; }
        const paneId = PRESENCE_PAGES[pageKey];
        const pane = document.getElementById(paneId);
        if (!pane) { _hideBanner(); return; }

        const sig = _signature(others);
        if (!others || others.length === 0) {
            _hideBanner();
            _dismissedSig = null;  // nothing left to dismiss — reset
            return;
        }
        // Dismissed for THIS exact set? Stay hidden. A new operator joining
        // changes the signature → banner reappears.
        if (_dismissedSig === sig) {
            _hideBanner();
            return;
        }
        _dismissedSig = null;

        const banner = _ensureBanner(pane);
        if (!banner) return;

        // Build operator chips (dot + display name) — one per other.
        const escapeAttr = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
        const chips = others.map(o => {
            const profile = _opLookup(o.operator_id);
            const color = profile ? (profile.color || '#7A849E') : '#7A849E';
            const display = profile ? (profile.display || profile.id) : o.operator_id;
            return `<span class="presence-banner__op">
                <span class="operator-dot operator-dot--sm" style="background: ${escapeAttr(color)}" aria-hidden="true"></span>
                <span class="presence-banner__op-name">${escapeAttr(display)}</span>
            </span>`;
        }).join('');

        // Sentence form: "alice and harris are also viewing" vs "alice is also viewing"
        let sentence;
        if (others.length === 1) {
            const profile = _opLookup(others[0].operator_id);
            const display = profile ? (profile.display || profile.id) : others[0].operator_id;
            sentence = `${escapeAttr(display)} is also viewing this project`;
        } else {
            const names = others.map(o => {
                const profile = _opLookup(o.operator_id);
                return profile ? (profile.display || profile.id) : o.operator_id;
            });
            const last = names.pop();
            const list = `${names.join(', ')} and ${last}`;
            sentence = `${escapeAttr(list)} are also viewing this project`;
        }
        const newest = others[0];
        const seenAgo = _relativeTime(newest.last_heartbeat);

        banner.innerHTML = `
            <span class="presence-banner__chips">${chips}</span>
            <span class="presence-banner__text">${sentence}</span>
            ${seenAgo ? `<span class="presence-banner__time"> · last seen ${escapeAttr(seenAgo)}</span>` : ''}
            <button class="presence-banner__dismiss" type="button" aria-label="Dismiss presence banner" title="Dismiss">&times;</button>
        `;
        banner.hidden = false;
        banner.dataset.signature = sig;

        const dismissBtn = banner.querySelector('.presence-banner__dismiss');
        if (dismissBtn) {
            dismissBtn.onclick = () => {
                _dismissedSig = sig;
                _hideBanner();
            };
        }
    }

    async function tick() {
        const project = _project();
        const pageKey = _currentPage();
        if (!project || !pageKey) {
            // Not on a presence-aware view → tear down any lingering banner.
            _hideBanner();
            return;
        }
        try {
            const res = await fetch('/api/presence/heartbeat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ project, page: pageKey }),
            });
            if (!res.ok) return;
            const data = await res.json();
            if (!data || data.success !== true) return;
            _render(data.others || []);
        } catch (e) {
            // Network blip — leave the banner state as-is and try again next tick.
            console.warn('Presence heartbeat failed:', e);
        }
    }

    return {
        start() {
            if (_timerId) return;
            // Tick once immediately so the banner appears within milliseconds
            // of arriving on the page, not at the 30s mark.
            tick();
            _timerId = setInterval(tick, HEARTBEAT_MS);
        },
        stop() {
            if (_timerId) { clearInterval(_timerId); _timerId = null; }
            _hideBanner();
        },
        tickNow: tick,
        // Test hook — drive a render without hitting the network.
        _renderForTesting: _render,
        _resetDismissedForTesting() { _dismissedSig = null; },
    };
})();

// Boot the presence loop once the DOM is ready. Lifecycle is idempotent —
// .start() short-circuits if a timer is already armed.
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => APP.presence.start());
} else {
    APP.presence.start();
}

// Tick on every active-deployment change OR sub-pill change so the banner
// reflects the new context within ~100ms instead of waiting for the next
// 30s mark. _initialFire guards against the fire-immediate subscribe
// behavior in APP.activeDeployment.subscribe.
if (APP.activeDeployment && typeof APP.activeDeployment.subscribe === 'function') {
    let _initialFire = true;
    APP.activeDeployment.subscribe(() => {
        if (_initialFire) { _initialFire = false; return; }
        // Reset dismissal whenever the project changes — a banner that was
        // dismissed on project A shouldn't carry over to project B.
        APP.presence._resetDismissedForTesting();
        APP.presence.tickNow();
    });
}

// ──────────────────────────────────────────────────────────────────────
// Phase 3B — Operations sub-pill namespaces. Thin wrappers on top of the
// existing BEACON / TERMINAL globals + the legacy tools-upload helpers.
// These exist so tests and future modules have a stable APP.* surface to
// hang off of (rather than reaching for the top-level globals).
// ──────────────────────────────────────────────────────────────────────
APP.beacons = APP.beacons || {
    list() { return (typeof BEACON !== 'undefined' && BEACON.cachedBeacons) ? BEACON.cachedBeacons.slice() : []; },
    select(bid, label) {
        if (typeof BEACON !== 'undefined' && typeof BEACON.selectBeacon === 'function') {
            BEACON.selectBeacon(bid, label || '');
        }
    },
    refresh() {
        if (typeof BEACON !== 'undefined' && typeof BEACON.refreshBeacons === 'function') {
            return BEACON.refreshBeacons();
        }
    },
    refreshHistory() {
        if (typeof BEACON !== 'undefined' && typeof BEACON.refreshCmdHistory === 'function') {
            return BEACON.refreshCmdHistory();
        }
    },
    init() {
        // No-op stub — kept so the activation block can call APP.beacons.init()
        // before BEACON.init() (BEACON owns the heavy connect-and-fetch path).
    },
    // 2026-05-19 — Aggregate fleet view rendered in the Beacons sub-pill
    // when APP.activeDeployment.isAll() is true. Hits GET /api/beacon/all
    // and paints a table with one row per beacon across every active C2.
    async renderFleet() {
        const host = document.getElementById('beacons-all-mode-empty');
        const scoped = document.getElementById('beacons-scoped-content');
        if (!host) return;
        // Toggle scoped content off, all-mode container on.
        if (scoped) scoped.hidden = true;
        host.hidden = false;
        host.innerHTML = `
            <div class="ops-fleet ops-fleet--beacons" role="region" aria-label="Fleet beacons">
              <div class="ops-fleet__head">
                <h3 class="ops-fleet__title empty-state__title">Fleet beacons</h3>
                <p class="ops-fleet__subtitle">Aggregated across every active C2 deployment. Click a row to focus.</p>
              </div>
              <div class="ops-fleet__error-banner" data-fleet-errors hidden></div>
              <div class="ops-fleet__body">
                <table class="ops-fleet__table" role="table">
                  <thead><tr>
                    <th>Beacon ID</th><th>Deployment</th><th>Operator</th>
                    <th>Host</th><th>PID</th><th>Last checkin</th>
                    <th><span class="t-sr">Status</span></th>
                  </tr></thead>
                  <tbody data-fleet-tbody></tbody>
                </table>
              </div>
            </div>`;
        const tbody = host.querySelector('[data-fleet-tbody]');
        const errBanner = host.querySelector('[data-fleet-errors]');
        const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
        const fmtAgo = (ts) => {
            if (!ts) return '—';
            const sec = Math.floor(Date.now() / 1000) - Number(ts);
            if (sec < 60) return `${sec}s ago`;
            if (sec < 3600) return `${Math.floor(sec / 60)}m ago`;
            if (sec < 86400) return `${Math.floor(sec / 3600)}h ago`;
            return `${Math.floor(sec / 86400)}d ago`;
        };
        try {
            const resp = await fetch('/api/beacon/all');
            const data = await resp.json();
            const beacons = Array.isArray(data?.beacons) ? data.beacons : [];
            const errors = Array.isArray(data?.errors) ? data.errors : [];
            if (errors.length && errBanner) {
                const names = errors.map(e => esc(e.deployment || '(unknown)')).join(', ');
                errBanner.textContent = `Could not poll ${errors.length} deployment${errors.length === 1 ? '' : 's'}: ${names}.`;
                errBanner.hidden = false;
            }
            if (!beacons.length) {
                // Replace the entire fleet host with the empty-state CTA.
                host.innerHTML = `
                    <div class="empty-state empty-state--all-mode">
                      <h3 class="empty-state__title">No active beacons across the fleet</h3>
                      <p class="empty-state__body">
                        Pick a c2-* or combined-* deployment from the top-bar dropdown
                        to start one.
                      </p>
                      <button type="button" class="btn btn-primary"
                              data-action="open-global-deployment-dropdown"
                              onclick="document.getElementById('global-deploy-trigger')?.click()">
                        Pick a deployment
                      </button>
                    </div>`;
                return;
            }
            tbody.innerHTML = beacons.map(b => {
                const dead = b.is_dead ? ' is-dead' : '';
                return `<tr class="ops-fleet__row${dead}" role="link" tabindex="0"
                            data-fleet-beacon-id="${esc(b.id)}"
                            data-fleet-deployment="${esc(b.deployment)}">
                          <td class="ops-fleet__cell ops-fleet__cell--mono">${esc(b.id)}</td>
                          <td class="ops-fleet__cell">${esc(b.deployment)}</td>
                          <td class="ops-fleet__cell">${esc(b.operator || '—')}</td>
                          <td class="ops-fleet__cell">${esc(b.host || '—')}</td>
                          <td class="ops-fleet__cell ops-fleet__cell--mono">${esc(b.pid != null ? b.pid : '—')}</td>
                          <td class="ops-fleet__cell">${esc(fmtAgo(b.last))}</td>
                          <td class="ops-fleet__cell">${b.is_dead ? '<span class="badge badge-warning">dead</span>' : '<span class="badge badge-success">live</span>'}</td>
                        </tr>`;
            }).join('');
            // Wire row clicks + Enter key to focus the deployment.
            tbody.querySelectorAll('.ops-fleet__row').forEach(row => {
                const onActivate = () => {
                    const dep = row.dataset.fleetDeployment;
                    const bid = row.dataset.fleetBeaconId;
                    if (!dep) return;
                    APP.activeDeployment.set(dep);
                    setTimeout(() => {
                        try { APP.beacons.select(bid); } catch (e) { /* best-effort */ }
                    }, 50);
                };
                row.addEventListener('click', onActivate);
                row.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onActivate(); }
                });
            });
        } catch (e) {
            console.error('[fleet] beacons/all fetch failed', e);
            host.innerHTML = `
                <div class="ops-fleet__error-banner" data-fleet-errors>
                  Failed to load fleet beacons: ${esc(e.message || 'network error')}.
                </div>`;
        }
    },
};

APP.terminal = APP.terminal || {
    sessions() {
        if (typeof TERMINAL === 'undefined') return [];
        return Object.entries(TERMINAL.sessions).map(([id, s]) => ({
            id, type: s.type, label: s.label, opener: s.opener || null,
            host: s.host || null,
        }));
    },
    active() {
        return (typeof TERMINAL !== 'undefined' && TERMINAL.activeId) || null;
    },
    open(kind) {
        if (typeof TERMINAL === 'undefined') return;
        if (kind === 'local' || !kind) TERMINAL.openLocal();
    },
};

// ──────────────────────────────────────────────────────────────────────
// Phase 3B.3 — APP.payloads: parameter spec-list + artifacts management.
// Reads form state (deployment, files, destination) and re-renders the
// preview pane's spec-list + artifacts list. Wired up on init by
// initPayloadsV3() which subscribes to the form controls.
// ──────────────────────────────────────────────────────────────────────
APP.payloads = APP.payloads || {
    artifacts: [],      // each: { name, size?, url?, kind? }
    _state: {},         // last-known form state for spec-list rendering

    init() {
        if (this._initialized) { this.updateSpec(); return; }
        this._initialized = true;
        // Subscribe to form changes — both selects and radio buttons.
        const wireOnce = (id, evt) => {
            const el = document.getElementById(id);
            if (el && !el._payloadsV3Wired) {
                el._payloadsV3Wired = true;
                el.addEventListener(evt, () => this.updateSpec());
            }
        };
        wireOnce('tools-project-select', 'change');
        wireOnce('tools-custom-dest', 'input');
        document.querySelectorAll('input[name="tools-dest"]').forEach(r => {
            if (!r._payloadsV3Wired) {
                r._payloadsV3Wired = true;
                r.addEventListener('change', () => this.updateSpec());
            }
        });
        this.updateSpec();
        this.renderArtifacts();
    },

    _readState() {
        const project = document.getElementById('tools-project-select')?.value || '';
        const dest = document.querySelector('input[name="tools-dest"]:checked')?.value || '';
        const custom = document.getElementById('tools-custom-dest')?.value || '';
        const stagedListEl = document.getElementById('tools-staged-list');
        const stagedCount = stagedListEl ? stagedListEl.children.length : 0;
        return {
            project: project || '(not selected)',
            destination: dest === 'custom' ? (custom || '(custom path not set)') : (dest || '(not chosen)'),
            stagedCount,
        };
    },

    updateSpec() {
        const list = document.getElementById('ops-payloads-spec-list');
        const pillLabel = document.getElementById('ops-payloads-spec-pill-label');
        const pill = document.getElementById('ops-payloads-spec-pill');
        if (!list) return;
        const s = this._readState();
        this._state = s;
        const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));

        const rows = [
            { key: 'TARGET',      value: esc(s.project), hint: 'deployment' },
            { key: 'DESTINATION', value: `<span class="spec-row__value--mono">${esc(s.destination)}</span>`, hint: 'attack box' },
            { key: 'STAGED',      value: `<span class="spec-row__value--mono">${s.stagedCount} file${s.stagedCount === 1 ? '' : 's'}</span>`, hint: s.stagedCount > 0 ? 'ready' : 'empty' },
        ];

        list.innerHTML = rows.map(r => `
            <li class="spec-row" data-readonly="true">
              <div class="spec-row__head">
                <span class="spec-row__key">${esc(r.key)}</span>
                <span class="spec-row__value">${r.value}</span>
                <span class="spec-row__hint">${esc(r.hint)}</span>
                <span aria-hidden="true"></span>
              </div>
            </li>`).join('');

        // Update pill state — DRAFT until a project is selected AND something is staged.
        if (pill && pillLabel) {
            const ready = s.project !== '(not selected)' && s.stagedCount > 0;
            pill.classList.remove('spec-pill--draft', 'spec-pill--live', 'spec-pill--error');
            if (ready) {
                pill.classList.add('spec-pill--live');
                pillLabel.textContent = 'READY';
            } else {
                pill.classList.add('spec-pill--draft');
                pillLabel.textContent = 'DRAFT';
            }
        }
    },

    addArtifact(art) {
        if (!art || !art.name) return;
        this.artifacts.unshift(art);
        this.renderArtifacts();
    },

    clearArtifacts() {
        this.artifacts = [];
        this.renderArtifacts();
    },

    renderArtifacts() {
        const card = document.getElementById('ops-payloads-artifacts-card');
        const list = document.getElementById('ops-payloads-artifacts-list');
        const count = document.getElementById('ops-payloads-artifacts-count');
        if (!list || !card) return;
        if (!this.artifacts.length) {
            card.hidden = true;
            list.innerHTML = '';
            if (count) count.textContent = '0';
            return;
        }
        card.hidden = false;
        if (count) count.textContent = String(this.artifacts.length);
        const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
        list.innerHTML = this.artifacts.map((art, i) => {
            const url = art.url ? esc(art.url) : '';
            return `
              <li class="spec-row" data-readonly="true" data-artifact-index="${i}">
                <div class="spec-row__head">
                  <span class="ops-payloads-artifact__name">${esc(art.name)}</span>
                  <span class="ops-payloads-artifact__size">${esc(art.size || '')}</span>
                  <span class="ops-payloads-artifact__actions">
                    ${url ? `<a class="ops-payloads-artifact__btn" href="${url}" download="${esc(art.name)}" title="Download">
                        <svg class="icon icon--sm" aria-hidden="true"><use href="#icon-download"/></svg>Download
                    </a>` : ''}
                    <button type="button" class="ops-payloads-artifact__btn"
                            onclick="APP.payloads._view(${i})" title="View">
                        <svg class="icon icon--sm" aria-hidden="true"><use href="#icon-eye"/></svg>View
                    </button>
                  </span>
                </div>
              </li>`;
        }).join('');
    },

    _view(i) {
        const art = this.artifacts[i];
        if (!art) return;
        if (art.url) window.open(art.url, '_blank');
        else if (typeof APP.toast === 'function') APP.toast(`Artifact: ${art.name}`, 'info');
    },

    // 2026-05-19 — Aggregate read-only payload history rendered in the
    // Payloads sub-pill when APP.activeDeployment.isAll() is true. Hits
    // GET /api/tools/payloads/all and lists every generated artifact across
    // every active deployment, newest first. Clicking the download link
    // (when present) opens the artifact URL.
    async renderFleet() {
        const host = document.getElementById('payloads-all-mode-empty');
        const scoped = document.getElementById('payloads-scoped-content');
        if (!host) return;
        if (scoped) scoped.hidden = true;
        host.hidden = false;
        const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
        const fmtTime = (ts) => {
            if (!ts) return '—';
            try { return new Date(Number(ts) * 1000).toLocaleString(); }
            catch (e) { return String(ts); }
        };
        host.innerHTML = `
            <div class="ops-fleet ops-fleet--payloads" role="region" aria-label="Fleet payload history">
              <div class="ops-fleet__banner">
                <span class="ops-fleet__banner-text">
                  Generating new payloads requires picking a specific deployment from the top-bar dropdown.
                </span>
              </div>
              <div class="ops-fleet__head">
                <h3 class="ops-fleet__title empty-state__title">Payload history</h3>
                <p class="ops-fleet__subtitle">Read-only aggregate across every active deployment, newest first.</p>
              </div>
              <div class="ops-fleet__error-banner" data-fleet-errors hidden></div>
              <div class="ops-fleet__body">
                <table class="ops-fleet__table" role="table">
                  <thead><tr>
                    <th>Payload name</th><th>Type</th><th>Deployment</th>
                    <th>Generated by</th><th>Generated at</th><th>Download</th>
                  </tr></thead>
                  <tbody data-fleet-tbody></tbody>
                </table>
              </div>
            </div>`;
        const tbody = host.querySelector('[data-fleet-tbody]');
        const errBanner = host.querySelector('[data-fleet-errors]');
        try {
            const resp = await fetch('/api/tools/payloads/all');
            const data = await resp.json();
            const payloads = Array.isArray(data?.payloads) ? data.payloads.slice() : [];
            const errors = Array.isArray(data?.errors) ? data.errors : [];
            // Sort newest first (backend already does this, but defensive).
            payloads.sort((a, b) => (Number(b.generated_at || 0) - Number(a.generated_at || 0)));
            if (errors.length && errBanner) {
                const names = errors.map(e => esc(e.deployment || '(unknown)')).join(', ');
                errBanner.textContent = `Could not poll ${errors.length} deployment${errors.length === 1 ? '' : 's'}: ${names}.`;
                errBanner.hidden = false;
            }
            if (!payloads.length) {
                host.innerHTML = `
                    <div class="empty-state empty-state--all-mode">
                      <h3 class="empty-state__title">Payloads are per-deployment</h3>
                      <p class="empty-state__body">
                        No payloads generated yet across the fleet. Pick a deployment
                        from the top-bar dropdown to stage and transfer one.
                      </p>
                      <button type="button" class="btn btn-primary"
                              data-action="open-global-deployment-dropdown"
                              onclick="document.getElementById('global-deploy-trigger')?.click()">
                        Pick a deployment
                      </button>
                    </div>`;
                return;
            }
            tbody.innerHTML = payloads.map(p => {
                const url = p.download ? esc(p.download) : '';
                const dl = url
                    ? `<a class="ops-fleet__download" href="${url}" download="${esc(p.name)}">Download</a>`
                    : '<span class="t-muted">—</span>';
                return `<tr class="ops-fleet__row ops-fleet__row--readonly"
                            data-fleet-deployment="${esc(p.deployment)}"
                            data-fleet-transfer-id="${esc(p.transfer_id || '')}">
                          <td class="ops-fleet__cell ops-fleet__cell--mono">${esc(p.name)}</td>
                          <td class="ops-fleet__cell">${esc(p.type || '—')}</td>
                          <td class="ops-fleet__cell">${esc(p.deployment)}</td>
                          <td class="ops-fleet__cell">${esc(p.generated_by || '—')}</td>
                          <td class="ops-fleet__cell">${esc(fmtTime(p.generated_at))}</td>
                          <td class="ops-fleet__cell">${dl}</td>
                        </tr>`;
            }).join('');
        } catch (e) {
            console.error('[fleet] payloads/all fetch failed', e);
            host.innerHTML = `
                <div class="ops-fleet__error-banner" data-fleet-errors>
                  Failed to load fleet payloads: ${esc(e.message || 'network error')}.
                </div>`;
        }
    },
};

async function loadOperators() {
    try {
        const res = await fetch('/api/operators');
        const data = await res.json();
        if (!data || !data.success) return;
        APP.operator.current = data.current || null;
        APP.operator.all = data.operators || [];
        renderOperatorChip();
        renderOperatorMenu();
        APP.operator._notify();
    } catch (e) {
        console.warn('Failed to load operators', e);
    }
}

function renderOperatorChip() {
    const op = APP.operator.current;
    if (!op) return;
    const dot = document.getElementById('operator-chip-dot');
    const name = document.getElementById('operator-chip-name');
    if (dot) dot.style.background = op.color || 'var(--success)';
    if (name) name.textContent = op.display || op.id || '—';
    // Keep legacy hidden mirrors in sync (topology.js + any whoami consumers)
    const ghName = document.getElementById('global-operator-name');
    if (ghName) ghName.textContent = op.display || op.id || '';
    const legacyBadge = document.getElementById('operator-badge');
    if (legacyBadge) legacyBadge.textContent = op.display || op.id || '';
}

function renderOperatorMenu() {
    const list = document.getElementById('operator-menu-list');
    if (!list) return;
    const currentId = APP.operator.current ? APP.operator.current.id : null;
    list.innerHTML = APP.operator.all.map(op => {
        const isActive = op.id === currentId ? ' is-active' : '';
        return `
            <button class="operator-menu__operator${isActive}" type="button"
                    role="menuitem"
                    onclick="switchOperator('${escapeHtml(op.id)}')">
                <span class="operator-menu__operator-dot operator-dot operator-dot--lg" style="background: ${escapeHtml(op.color || '#7A849E')}"></span>
                <span class="operator-menu__operator-name">${escapeHtml(op.display || op.id || '')}</span>
                <span class="operator-menu__operator-id">${escapeHtml(op.id || '')}</span>
            </button>`;
    }).join('');
}

async function switchOperator(opId) {
    try {
        const res = await fetch('/api/operators/switch', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: opId }),
        });
        const data = await res.json();
        if (data && data.success) {
            APP.operator.current = data.current;
            renderOperatorChip();
            renderOperatorMenu();
            APP.operator._notify();
            closeOperatorMenu();
            if (typeof APP.toast === 'function' && data.current) {
                APP.toast(`Switched to ${data.current.display || data.current.id}`, 'info');
            }
            // Refresh the activity feed so it re-attributes rows with the
            // newly-current operator's color (and picks up any audit entry
            // the backend wrote for the switch itself).
            loadDashboardActivity(true);
        }
    } catch (e) {
        console.warn('Failed to switch operator', e);
    }
}

function openOperatorMenu() {
    const menu = document.getElementById('operator-menu');
    const chip = document.getElementById('operator-chip');
    if (!menu || !chip) return;
    menu.hidden = false;
    chip.setAttribute('aria-expanded', 'true');
    // Position below the chip, right-aligned to it.
    const rect = chip.getBoundingClientRect();
    menu.style.top = (rect.bottom + 8) + 'px';
    menu.style.right = Math.max(8, window.innerWidth - rect.right) + 'px';
    document.addEventListener('click', _operatorMenuOutsideClick, true);
    document.addEventListener('keydown', _operatorMenuEsc);
}

function closeOperatorMenu() {
    const menu = document.getElementById('operator-menu');
    const chip = document.getElementById('operator-chip');
    if (!menu || !chip) return;
    if (menu.hidden) return;
    menu.hidden = true;
    chip.setAttribute('aria-expanded', 'false');
    document.removeEventListener('click', _operatorMenuOutsideClick, true);
    document.removeEventListener('keydown', _operatorMenuEsc);
}

function _operatorMenuOutsideClick(e) {
    const menu = document.getElementById('operator-menu');
    const chip = document.getElementById('operator-chip');
    if (!menu || !chip) return;
    if (!menu.contains(e.target) && !chip.contains(e.target)) closeOperatorMenu();
}
function _operatorMenuEsc(e) { if (e.key === 'Escape') closeOperatorMenu(); }

// --- Add Operator modal ---
const OPERATOR_COLORS = ['#a31621', '#3b82f6', '#0d9488', '#7c3aed', '#ea580c', '#65a30d'];
let _selectedOperatorColor = OPERATOR_COLORS[0];

function openAddOperatorModal() {
    closeOperatorMenu();
    if (!APP.modal || typeof APP.modal.open !== 'function') return;
    APP.modal.open('add-operator-modal');
    populateOperatorColorGrid();
    const idEl = document.getElementById('add-op-id');
    const displayEl = document.getElementById('add-op-display');
    const errEl = document.getElementById('add-op-error');
    if (idEl) idEl.value = '';
    if (displayEl) displayEl.value = '';
    if (errEl) errEl.style.display = 'none';
}

function populateOperatorColorGrid() {
    const grid = document.getElementById('add-op-color-grid');
    if (!grid) return;
    _selectedOperatorColor = OPERATOR_COLORS[0];
    grid.innerHTML = OPERATOR_COLORS.map((c, i) => `
        <button type="button"
                class="operator-color-swatch${i === 0 ? ' is-selected' : ''}"
                style="background: ${c}" data-color="${c}"
                onclick="selectOperatorColor('${c}', this)"
                aria-label="Color ${c}"></button>
    `).join('');
}

function selectOperatorColor(color, btn) {
    _selectedOperatorColor = color;
    document.querySelectorAll('#add-op-color-grid .operator-color-swatch').forEach(s => {
        s.classList.remove('is-selected');
    });
    if (btn) btn.classList.add('is-selected');
}

async function submitAddOperator(e) {
    e.preventDefault();
    const idEl = document.getElementById('add-op-id');
    const displayEl = document.getElementById('add-op-display');
    const errBox = document.getElementById('add-op-error');
    if (!idEl || !displayEl || !errBox) return false;
    const id = idEl.value.trim();
    const display = displayEl.value.trim();
    errBox.style.display = 'none';
    try {
        const res = await fetch('/api/operators', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id, display, color: _selectedOperatorColor }),
        });
        const data = await res.json();
        if (!data || !data.success) {
            errBox.textContent = (data && data.error) || 'Failed to add operator';
            errBox.style.display = 'block';
            return false;
        }
        APP.modal.close('add-operator-modal');
        await loadOperators();
        if (data.operator && data.operator.id) {
            await switchOperator(data.operator.id);
        }
        if (typeof APP.toast === 'function' && data.operator) {
            APP.toast(`Operator ${data.operator.display || data.operator.id} added`, 'success');
        }
    } catch (err) {
        errBox.textContent = 'Network error';
        errBox.style.display = 'block';
    }
    return false;
}

// --- Activity feed ---
async function loadDashboardActivity(forceRefresh = false) {
    const list = document.getElementById('activity-feed-list');
    if (!list) return;
    try {
        const res = await fetch('/api/audit?limit=20');
        const data = await res.json();
        const entries = (data && data.entries) || [];
        if (entries.length === 0) {
            list.innerHTML = '<li class="activity-feed__empty">No recent activity.</li>';
            return;
        }
        list.innerHTML = entries.map(e => _renderActivityRow(e)).join('');
    } catch (err) {
        list.innerHTML = '<li class="activity-feed__empty">Failed to load activity.</li>';
    }
}

function _renderActivityRow(e) {
    // Phase 3e — emit a .spec-row (read-only) composing the V3 primitive.
    // Key column: operator dot + display name. Value column: verb + target.
    // Hint column: relative time. Unknown operators fall back to muted gray.
    const op = APP.operator.all.find(o => o.id === e.op);
    const color = (op && op.color) || '#7A849E';
    const display = (op && op.display) || e.op || 'unknown';
    const verb = _activityVerb(e.action);
    const target = e.project || e.target || '';
    const time = _relativeTime(e.ts);
    const targetHtml = target
        ? `<span class="spec-row__value-target">${escapeHtml(target)}</span>`
        : '';
    return `
        <li class="spec-row" data-readonly="true" data-activity-op="${escapeHtml(e.op || '')}">
            <div class="spec-row__head">
                <span class="spec-row__key">
                    <span class="operator-dot" style="background: ${escapeHtml(color)}" aria-hidden="true"></span>
                    ${escapeHtml(display)}
                </span>
                <span class="spec-row__value">
                    <span class="spec-row__value-verb">${escapeHtml(verb)}</span>${targetHtml}
                </span>
                <span class="spec-row__hint">${escapeHtml(time)}</span>
            </div>
        </li>
    `;
}

function _activityVerb(action) {
    const map = {
        'deploy.apply': 'deployed',
        'deploy.destroy': 'destroyed',
        'deploy.plan': 'planned',
        'deploy.save_config': 'saved config for',
        'beacon.exec': 'ran a command on',
        'beacon.listener_create': 'created listener on',
        'terminal.start': 'started terminal on',
        'operator.add': 'added operator',
        'operator.remove': 'removed operator',
        'operator.switch': 'switched to',
        'cleanup.mark_known': 'marked known-external',
    };
    return map[action] || action || '';
}

function _relativeTime(iso) {
    if (!iso) return '';
    const then = new Date(iso).getTime();
    if (isNaN(then)) return '';
    const diff = Date.now() - then;
    const s = Math.max(0, Math.floor(diff / 1000));
    if (s < 60) return `${s}s ago`;
    const m = Math.floor(s / 60);
    if (m < 60) return `${m}m ago`;
    const h = Math.floor(m / 60);
    if (h < 24) return `${h}h ago`;
    const d = Math.floor(h / 24);
    return `${d}d ago`;
}

// Wire up on DOMContentLoaded — coexists with APP.init() (separate listener).
document.addEventListener('DOMContentLoaded', () => {
    loadOperators();
    const chip = document.getElementById('operator-chip');
    if (chip) {
        chip.addEventListener('click', (e) => {
            e.stopPropagation();
            const menu = document.getElementById('operator-menu');
            if (!menu) return;
            if (menu.hidden) openOperatorMenu(); else closeOperatorMenu();
        });
    }
    const addBtn = document.getElementById('operator-menu-add');
    if (addBtn) addBtn.addEventListener('click', openAddOperatorModal);
    // Manage button — opens the Manage operators modal (APP.operatorManagement).
    // Replaces the v2.3.0 placeholder toast. The module closes the dropdown
    // itself so we don't double-close here.
    const manageBtn = document.getElementById('operator-menu-manage');
    if (manageBtn) manageBtn.addEventListener('click', () => {
        if (APP.operatorManagement && typeof APP.operatorManagement.open === 'function') {
            APP.operatorManagement.open();
        } else {
            closeOperatorMenu();
        }
    });

    // Initial activity load — also loaded on every Dashboard tab activation.
    loadDashboardActivity(true);
});

// Hook into APP.navigateTo so the activity feed refreshes on Dashboard entry.
// Wrap idempotently — guarded by _mOperatorsWrapped so HMR/dup-load is safe.
if (APP.navigateTo && !APP.navigateTo._mOperatorsWrapped) {
    const _origNav = APP.navigateTo.bind(APP);
    APP.navigateTo = function (...args) {
        const result = _origNav(...args);
        // The dashboard tab is registered as 'dashboard' (data-target="dashboard");
        // the spec referenced 'dashboard-tab' for forward-compat — accept both.
        const first = args[0];
        const parent = (first && typeof first === 'object') ? first.parent : first;
        if (parent === 'dashboard' || parent === 'dashboard-tab') {
            loadDashboardActivity(true);
        }
        return result;
    };
    APP.navigateTo._mOperatorsWrapped = true;
}

// ============================================================================
// === APP.operatorManagement — Manage operators modal (Phase 3 native) =======
// ============================================================================
// Wires the dropdown "Manage…" item to a real modal that renders one
// .spec-row per operator, with inline rename / recolor / delete editors.
//
// Backend contract:
//   GET    /api/operators            → { operators: [{id, display, color,
//                                                   last_active, action_count}], current, default }
//   PATCH  /api/operators/<id>       → { operator }
//   DELETE /api/operators/<id>
//
// Protections surfaced in the UI:
//   - Cannot delete the currently-active operator (would orphan the cookie).
//   - Cannot delete the last operator (backend also enforces).
//   - Cannot delete the default operator unless another exists to promote.
//     Backend auto-promotes; the UI just confirms the next-default in copy.
// ============================================================================

APP.operatorManagement = (function () {
    const MODAL_ID = 'operator-management-modal';
    const LIST_ID = 'operator-management-list';
    let _operators = [];
    let _currentId = null;
    let _defaultId = null;
    let _editingId = null;
    let _editingColor = null;
    let _pendingDeleteId = null;

    function _relTime(iso) {
        // Shared with _relativeTime above but duplicated to keep this module
        // self-contained — _relativeTime is a module-scoped function in the
        // M-Operators block above; reuse via the closure since both live in
        // the same script bundle.
        if (typeof _relativeTime === 'function') return _relativeTime(iso);
        return '';
    }

    async function _fetchOperators() {
        const res = await fetch('/api/operators');
        const data = await res.json();
        if (!data || !data.success) throw new Error((data && data.error) || 'load failed');
        _operators = data.operators || [];
        _currentId = (data.current && data.current.id) || null;
        _defaultId = data.default || null;
        // Keep the global APP.operator cache in sync so renderOperatorMenu()
        // picks up any rename / recolor immediately without a second fetch.
        APP.operator.all = _operators;
        if (data.current) APP.operator.current = data.current;
    }

    function _renderColorGrid(currentColor) {
        return OPERATOR_COLORS.map(c => {
            const sel = (c.toLowerCase() === (currentColor || '').toLowerCase()) ? ' is-selected' : '';
            return `<button type="button" class="operator-color-swatch${sel}"
                            style="background: ${escapeHtml(c)}" data-color="${escapeHtml(c)}"
                            aria-label="Color ${escapeHtml(c)}"
                            data-mgmt-color></button>`;
        }).join('');
    }

    function _renderRow(op) {
        const isEditing = op.id === _editingId;
        const isCurrent = op.id === _currentId;
        const isDefault = op.id === _defaultId;
        const isLast = _operators.length === 1;
        const cantDelete = isCurrent || isLast;
        const deleteTip = isCurrent
            ? 'Switch to another operator before deleting this profile.'
            : (isLast ? 'Cannot delete the last operator.' : '');
        const lastActive = op.last_active ? _relTime(op.last_active) : null;
        const count = Number(op.action_count || 0);
        const countLabel = count === 1 ? '1 action' : `${count} actions`;
        const hintText = lastActive
            ? `${countLabel} · last active ${lastActive}`
            : (count > 0 ? countLabel : 'never used');

        const color = op.color || '#7A849E';
        const display = op.display || op.id || '';

        const editorColor = _editingColor || color;
        const pendingDel = (_pendingDeleteId === op.id);

        const editorMarkup = isEditing ? `
            <div class="spec-row__editor">
                <div class="spec-row__editor-field">
                    <label class="spec-row__editor-label" for="op-mgmt-display-${escapeHtml(op.id)}">Display name</label>
                    <input class="spec-row__editor-input" id="op-mgmt-display-${escapeHtml(op.id)}"
                           type="text" value="${escapeHtml(display)}"
                           data-mgmt-display autocomplete="off">
                </div>
                <div class="spec-row__editor-field">
                    <span class="spec-row__editor-label">Color</span>
                    <div class="operator-color-grid" data-mgmt-color-grid>
                        ${_renderColorGrid(editorColor)}
                    </div>
                </div>
                ${isDefault ? `
                <div class="spec-row__editor-hint operator-mgmt__hint-default">
                    Default profile. ${_operators.length > 1
                        ? 'Deleting promotes another operator to default.'
                        : 'Add another operator before deleting.'}
                </div>` : ''}
                <div class="spec-row__editor-foot">
                    <button type="button" class="spec-edit-btn spec-edit-btn--danger"
                            data-mgmt-delete
                            ${cantDelete ? 'disabled' : ''}
                            ${cantDelete ? `title="${escapeHtml(deleteTip)}"` : ''}>
                        Delete profile
                    </button>
                    <span style="flex: 1"></span>
                    <button type="button" class="spec-edit-btn" data-mgmt-cancel>Cancel</button>
                    <button type="button" class="spec-edit-btn spec-edit-btn--save" data-mgmt-save>Save</button>
                </div>
                ${pendingDel ? `
                <div class="operator-mgmt__confirm" role="alertdialog" aria-label="Confirm delete">
                    <span class="operator-mgmt__confirm-text">
                        Delete profile? Audit log entries are preserved.
                    </span>
                    <button type="button" class="spec-edit-btn" data-mgmt-delete-cancel>Cancel</button>
                    <button type="button" class="spec-edit-btn spec-edit-btn--danger-fill" data-mgmt-delete-confirm>Confirm</button>
                </div>` : ''}
            </div>
        ` : '';

        const statusBadges = [];
        if (isCurrent) statusBadges.push('<span class="spec-pill operator-mgmt__pill operator-mgmt__pill--current">Active</span>');
        if (isDefault) statusBadges.push('<span class="spec-pill operator-mgmt__pill">Default</span>');

        return `
            <div class="spec-row operator-mgmt__row" data-op-id="${escapeHtml(op.id)}"
                 ${isEditing ? 'data-editing="true"' : ''}>
                <div class="spec-row__head">
                    <span class="spec-row__key operator-mgmt__key">
                        <span class="operator-dot operator-dot--lg" style="background: ${escapeHtml(color)}" aria-hidden="true"></span>
                        <span class="operator-mgmt__display">${escapeHtml(display)}</span>
                        ${statusBadges.join('')}
                    </span>
                    <span class="spec-row__value spec-row__value--mono">${escapeHtml(op.id)}</span>
                    <span class="spec-row__hint">${escapeHtml(hintText)}</span>
                    <button type="button" class="spec-row__action" data-mgmt-edit
                            aria-label="Edit ${escapeHtml(display)}"
                            aria-expanded="${isEditing ? 'true' : 'false'}">
                        <svg class="icon" aria-hidden="true"><use href="#icon-edit-pencil"/></svg>
                    </button>
                </div>
                ${editorMarkup}
            </div>
        `;
    }

    function render() {
        const list = document.getElementById(LIST_ID);
        if (!list) return;
        list.setAttribute('data-editing', _editingId ? 'true' : 'false');
        list.innerHTML = _operators.map(_renderRow).join('');
        // Delegated events would also work, but the row count is small (<=32)
        // so per-element wiring keeps the handlers self-documenting.
        list.querySelectorAll('[data-op-id]').forEach(row => {
            const opId = row.getAttribute('data-op-id');
            const editBtn = row.querySelector('[data-mgmt-edit]');
            if (editBtn) editBtn.addEventListener('click', () => editRow(opId));
            // Swatch picker — flip the selection class without a full re-render
            // so the user's text input doesn't lose focus/value.
            const grid = row.querySelector('[data-mgmt-color-grid]');
            if (grid) {
                grid.addEventListener('click', (e) => {
                    const sw = e.target.closest('[data-mgmt-color]');
                    if (!sw) return;
                    _editingColor = sw.getAttribute('data-color');
                    grid.querySelectorAll('[data-mgmt-color]').forEach(s => s.classList.remove('is-selected'));
                    sw.classList.add('is-selected');
                });
            }
            const cancelBtn = row.querySelector('[data-mgmt-cancel]');
            if (cancelBtn) cancelBtn.addEventListener('click', () => cancelRow(opId));
            const saveBtn = row.querySelector('[data-mgmt-save]');
            if (saveBtn) saveBtn.addEventListener('click', () => saveRow(opId));
            const delBtn = row.querySelector('[data-mgmt-delete]');
            if (delBtn && !delBtn.disabled) delBtn.addEventListener('click', () => deleteRow(opId));
            const delCancel = row.querySelector('[data-mgmt-delete-cancel]');
            if (delCancel) delCancel.addEventListener('click', () => { _pendingDeleteId = null; render(); });
            const delConfirm = row.querySelector('[data-mgmt-delete-confirm]');
            if (delConfirm) delConfirm.addEventListener('click', () => confirmDelete(opId));
        });
    }

    async function open() {
        // Close the dropdown first so two popovers don't stack.
        closeOperatorMenu();
        _editingId = null;
        _editingColor = null;
        _pendingDeleteId = null;
        const list = document.getElementById(LIST_ID);
        if (list) list.innerHTML = '<div class="operator-mgmt__loading">Loading…</div>';
        APP.modal.open(MODAL_ID);
        try {
            await _fetchOperators();
            render();
            // Keep the global chip in sync — if anything changed since last load.
            renderOperatorChip();
            renderOperatorMenu();
        } catch (e) {
            if (list) list.innerHTML = `<div class="operator-mgmt__error">Failed to load operators.</div>`;
        }
    }

    function close() {
        APP.modal.close(MODAL_ID);
        _editingId = null;
        _editingColor = null;
        _pendingDeleteId = null;
    }

    function editRow(opId) {
        const op = _operators.find(o => o.id === opId);
        _editingId = opId;
        _editingColor = (op && op.color) || null;
        _pendingDeleteId = null;
        render();
    }

    function cancelRow(_opId) {
        _editingId = null;
        _editingColor = null;
        _pendingDeleteId = null;
        render();
    }

    async function saveRow(opId) {
        const row = document.querySelector(`#${LIST_ID} [data-op-id="${CSS.escape(opId)}"]`);
        if (!row) return;
        const displayEl = row.querySelector('[data-mgmt-display]');
        const newDisplay = displayEl ? displayEl.value.trim() : null;
        const op = _operators.find(o => o.id === opId);
        const payload = {};
        if (newDisplay && newDisplay !== (op && op.display)) payload.display = newDisplay;
        if (_editingColor && _editingColor !== (op && op.color)) payload.color = _editingColor;
        if (Object.keys(payload).length === 0) {
            cancelRow(opId);
            return;
        }
        try {
            const res = await fetch(`/api/operators/${encodeURIComponent(opId)}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            });
            const data = await res.json();
            if (!data || !data.success) {
                if (typeof APP.toast === 'function') APP.toast((data && data.error) || 'Update failed', 'error');
                return;
            }
            _editingId = null;
            _editingColor = null;
            await _fetchOperators();
            render();
            renderOperatorChip();
            renderOperatorMenu();
            if (typeof APP.toast === 'function') APP.toast(`Updated ${data.operator.display || data.operator.id}`, 'success');
        } catch (e) {
            if (typeof APP.toast === 'function') APP.toast('Network error', 'error');
        }
    }

    function deleteRow(opId) {
        // Stage 1 — show the inline confirm. Stage 2 is confirmDelete().
        _pendingDeleteId = opId;
        render();
    }

    async function confirmDelete(opId) {
        try {
            const res = await fetch(`/api/operators/${encodeURIComponent(opId)}`, { method: 'DELETE' });
            const data = await res.json();
            if (!data || !data.success) {
                if (typeof APP.toast === 'function') APP.toast((data && data.error) || 'Delete failed', 'error');
                _pendingDeleteId = null;
                render();
                return;
            }
            _editingId = null;
            _editingColor = null;
            _pendingDeleteId = null;
            await _fetchOperators();
            render();
            renderOperatorChip();
            renderOperatorMenu();
            if (typeof APP.toast === 'function') APP.toast(`Removed ${opId}`, 'info');
        } catch (e) {
            if (typeof APP.toast === 'function') APP.toast('Network error', 'error');
        }
    }

    function addOperator() {
        // Chain into the existing Add Operator modal — close ours first so
        // they don't stack visually.
        close();
        openAddOperatorModal();
    }

    return { open, close, editRow, saveRow, cancelRow, deleteRow, addOperator };
})();

document.addEventListener('DOMContentLoaded', () => {
    const addBtn = document.getElementById('operator-management-add');
    if (addBtn) addBtn.addEventListener('click', () => APP.operatorManagement.addOperator());
});

// === end M-Operators ========================================================

document.addEventListener('DOMContentLoaded', () => {
    APP.init();
});

// Save beacon history on page unload
window.addEventListener('beforeunload', (e) => {
    if (BEACON.selectedBid) BEACON._saveHistory(BEACON.selectedBid);

    // Warn if active terminal sessions exist (they'll be lost on refresh)
    if (Object.keys(TERMINAL.sessions).length > 0) {
        const count = Object.keys(TERMINAL.sessions).length;
        const msg = `You have ${count} active terminal session${count > 1 ? 's' : ''} (SSH connections, tunnels). Refreshing will kill all sessions and disconnect any active tunnels including the REST API tunnel.`;
        e.preventDefault();
        e.returnValue = msg;
    }
});

// ════════════════════════════════════════════════════════════════════════
// PHASE 3A — Manage sub-pill V3-native rebuild.
// Builds the hero + spec-list + actions strip at the top of the Manage
// pane, composing Phase 2B primitives. Preserves all existing data flows
// (refreshAll, loadResourceList, renderDeploymentTimeline, etc.) — only
// the top-of-pane skeleton is replaced. APP.manage.render() is called
// from APP._runSubPillInit on manage activation AND on
// APP.activeDeployment.subscribe (wired in APP.manage.init).
// ════════════════════════════════════════════════════════════════════════

APP.manage = APP.manage || {};

APP.manage._escape = function (s) {
    return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
};

/** Humanised "x minutes ago" formatter for audit timestamps (ISO 8601). */
APP.manage._timeAgo = function (iso) {
    if (!iso) return '';
    let t;
    try { t = new Date(iso).getTime(); } catch (_) { return ''; }
    if (!Number.isFinite(t)) return '';
    const diff = Math.floor((Date.now() - t) / 1000);
    if (diff < 0) return 'just now';
    if (diff < 10) return 'just now';
    if (diff < 60) return `${diff}s ago`;
    if (diff < 3600) return `${Math.floor(diff / 60)} min ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return `${Math.floor(diff / 86400)}d ago`;
};

/** Build a spec-row HTML fragment. Read-only — manage rows don't edit. */
APP.manage._renderRow = function (row) {
    const esc = APP.manage._escape;
    const valueClasses = ['spec-row__value'];
    if (row.valueMono) valueClasses.push('spec-row__value--mono');
    if (row.valueStrong) valueClasses.push('spec-row__value--strong');
    let valueHtml;
    if (row.isPill) {
        valueHtml = `<dd class="${valueClasses.join(' ')}"><span class="spec-pill"><span class="spec-pill__dot" aria-hidden="true"></span>${esc(row.value)}</span></dd>`;
    } else if (row.valueHtml) {
        valueHtml = `<dd class="${valueClasses.join(' ')}" data-manage-value="${esc(row.key)}">${row.valueHtml}</dd>`;
    } else {
        valueHtml = `<dd class="${valueClasses.join(' ')}" data-manage-value="${esc(row.key)}">${esc(row.value)}</dd>`;
    }
    const hintHtml = row.hint
        ? `<dd class="spec-row__hint" data-manage-hint="${esc(row.key)}">${esc(row.hint)}</dd>`
        : '<dd class="spec-row__hint" data-manage-hint=""></dd>';
    return `
        <div class="spec-row" data-manage-row="${esc(row.key)}" data-readonly="true">
            <div class="spec-row__head">
                <dt class="spec-row__key">${esc(row.label)}</dt>
                ${valueHtml}
                ${hintHtml}
                <span class="spec-row__action" aria-hidden="true"></span>
            </div>
        </div>
    `;
};

/** Update the .spec-pill in the eyebrow to reflect deployment state. */
APP.manage._updateStatusPill = function (state) {
    const pill = document.getElementById('manage-status-pill');
    const label = document.getElementById('manage-status-label');
    if (!pill || !label) return;
    pill.classList.remove('spec-pill--live', 'spec-pill--draft', 'spec-pill--error');
    if (state === 'live') {
        pill.classList.add('spec-pill--live');
        label.textContent = 'LIVE';
    } else if (state === 'error') {
        pill.classList.add('spec-pill--error');
        label.textContent = 'ERROR';
    } else {
        pill.classList.add('spec-pill--draft');
        label.textContent = state ? String(state).toUpperCase() : 'IDLE';
    }
};

/** Look up the most-recent deploy.* audit entry for a project. */
APP.manage._loadLastTouched = async function (projectName) {
    if (!projectName) return null;
    try {
        const r = await fetch(`/api/audit?action_prefix=deploy.&project=${encodeURIComponent(projectName)}&limit=1`);
        const d = await r.json();
        if (!d || !d.success) return null;
        const entry = (d.entries || [])[0];
        if (!entry) return null;
        return {
            operator: entry.op || 'unknown',
            ts: entry.ts || '',
            action: entry.action || '',
        };
    } catch (e) {
        console.warn('manage._loadLastTouched failed:', e);
        return null;
    }
};

/** Build the spec-list rows. */
APP.manage._buildRows = function (ctx) {
    const rows = [];
    const infra = ctx.infrastructure || {};
    const cost = ctx.cost;
    const audit = ctx.audit;
    const config = ctx.config || {};
    const outputs = ctx.outputs || {};
    const deployType = String(ctx.deploymentType || '').toLowerCase();
    const isC2OrCombined = deployType.startsWith('c2-') || deployType.startsWith('combined-');

    rows.push({
        key: 'region',
        label: 'AWS Region',
        value: config.aws_region || 'eu-central-1',
        valueMono: true,
        hint: 'primary',
    });

    if (ctx.account_id) {
        rows.push({
            key: 'account',
            label: 'AWS Account',
            value: ctx.account_id,
            valueMono: true,
            hint: 'caller identity',
        });
    }

    const totalInstances =
        (infra.summary?.c2_server_count || 0) +
        (infra.summary?.redirector_count || 0) +
        (infra.summary?.has_bastion ? 1 : 0) +
        (infra.summary?.has_attack_box ? 1 : 0);
    rows.push({
        key: 'instances',
        label: 'EC2 Instances',
        value: String(totalInstances || (ctx.instance_count ?? '—')),
        valueMono: true,
        valueStrong: true,
        hint: totalInstances ? 'all healthy' : '',
    });

    if (infra.bastion?.public_ip) {
        rows.push({
            key: 'bastion',
            label: 'Bastion',
            value: infra.bastion.public_ip,
            valueMono: true,
            hint: 'SSH 22 from your CIDR',
        });
    }
    const redirIps = infra.redirectors?.public_ips || [];
    if (redirIps.length) {
        rows.push({
            key: 'redirector_ips',
            label: 'Redirector IPs',
            value: redirIps.length === 1 ? redirIps[0] : `${redirIps.length} public IPs`,
            valueMono: true,
            hint: redirIps.length === 1 ? 'HTTPS 443' : `${redirIps.length} · HTTPS 443`,
        });
    }

    // Redirector front-domain row — the "dummy website" surfaced for operators.
    // Pulls from per-project terraform outputs (primary_domain_name /
    // redirector_domain / dns_domain) which /api/deploy/outputs exposes. Only
    // shown for C2 / combined deployments where redirectors exist. Operators
    // can open the URL directly to verify front categorization.
    const frontDomain =
        (outputs.redirector_domain && String(outputs.redirector_domain).trim()) ||
        (outputs.primary_domain_name && String(outputs.primary_domain_name).trim()) ||
        (outputs.dns_domain && String(outputs.dns_domain).trim()) ||
        '';
    if (isC2OrCombined && frontDomain) {
        const esc = APP.manage._escape;
        const safeDomain = esc(frontDomain);
        const linkHtml =
            `<a href="https://${safeDomain}" target="_blank" rel="noopener noreferrer" class="manage-front-domain">${safeDomain}</a>` +
            ` <span class="manage-front-domain__open" aria-hidden="true">Open in browser &#8599;</span>`;
        rows.push({
            key: 'redirector_domain',
            label: 'Redirector · Front Domain',
            valueHtml: linkHtml,
            valueMono: true,
            hint: 'public callback FQDN — check categorization before use',
        });
    }
    if (infra.jumpbox_public_ip) {
        rows.push({
            key: 'jumpbox',
            label: 'Jumpbox',
            value: infra.jumpbox_public_ip,
            valueMono: true,
            hint: 'SSH 22 (GOAD)',
        });
    }

    const sgs = infra.security_groups || {};
    const sgIds = Object.values(sgs).filter(Boolean);
    if (sgIds.length) {
        rows.push({
            key: 'sgs',
            label: 'Security Groups',
            value: `${sgIds.length} group${sgIds.length === 1 ? '' : 's'}`,
            valueMono: true,
            hint: 'least-privilege',
        });
    }

    if (cost != null) {
        rows.push({
            key: 'cost',
            label: 'Estimated Burn',
            value: `$${Number(cost).toFixed(2)} / mo`,
            valueMono: true,
            valueStrong: true,
            hint: 'computed',
        });
    }

    // Last-touched-by — operator attribution from audit log.
    if (audit) {
        const esc = APP.manage._escape;
        const operatorHtml = audit.operator && audit.operator !== 'unknown'
            ? `<span class="manage-attr">${esc(audit.operator)}</span>`
            : `<span class="manage-attr manage-attr--unknown">unknown operator</span>`;
        const timeAgo = APP.manage._timeAgo(audit.ts) || 'recently';
        rows.push({
            key: 'last_touched',
            label: 'Last touched by',
            valueHtml: `${operatorHtml} <span style="color: var(--text-secondary);">${esc(timeAgo)}</span>`,
            hint: audit.action ? audit.action : '',
        });
    } else if (ctx.hasDeployment) {
        rows.push({
            key: 'last_touched',
            label: 'Last touched by',
            valueHtml: `<span class="manage-attr manage-attr--unknown">no audit data</span>`,
            hint: 'no recent deploy actions',
        });
    }

    return rows;
};

/** Show a transient message in the inline output panel. */
APP.manage._setOutput = function (text, state) {
    const out = document.getElementById('manage-output');
    if (!out) return;
    if (!text) {
        out.hidden = true;
        out.textContent = '';
        out.removeAttribute('data-state');
        return;
    }
    out.hidden = false;
    out.textContent = text;
    if (state) out.setAttribute('data-state', state);
    else out.removeAttribute('data-state');
};

/** Wire the action strip — idempotent. */
APP.manage._wireActions = function () {
    const strip = document.getElementById('manage-actions');
    if (!strip || strip._manageWired) return;
    strip._manageWired = true;
    strip.addEventListener('click', async (e) => {
        const btn = e.target.closest('[data-manage-action]');
        if (!btn) return;
        const action = btn.dataset.manageAction;
        if (action === 'refresh') {
            APP.manage._setOutput('Refreshing...', 'loading');
            try {
                if (typeof refreshAll === 'function') await refreshAll();
            } catch (err) { /* surfaced via banners */ }
            await APP.manage.render();
            APP.manage._setOutput('');
        } else if (action === 'logs') {
            const section = document.getElementById('deployment-history-section');
            if (section) {
                section.style.display = 'block';
                section.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        } else if (action === 'health') {
            const project = APP.manage._currentProject();
            APP.manage._setOutput(`Running health check${project ? ' for ' + project : ''}...`, 'loading');
            try {
                const r = await fetch(`/api/deploy/infrastructure${project ? '?project=' + encodeURIComponent(project) : ''}`);
                const d = await r.json();
                if (!d.success) throw new Error(d.error || 'Health check failed');
                const lines = [];
                lines.push(`Project: ${d.project_name || '(default)'}`);
                lines.push(`Deployment mode: ${d.deployment_mode || 'unknown'}`);
                if (d.summary) {
                    lines.push(`  c2 servers:     ${d.summary.c2_server_count || 0}`);
                    lines.push(`  redirectors:    ${d.summary.redirector_count || 0}`);
                    lines.push(`  bastion:        ${d.summary.has_bastion ? 'yes' : 'no'}`);
                    lines.push(`  attack box:     ${d.summary.has_attack_box ? 'yes' : 'no'}`);
                    lines.push(`  subnet count:   ${d.summary.subnet_count || 0}`);
                }
                if (d.network?.vpc_id) lines.push(`VPC: ${d.network.vpc_id}`);
                lines.push('');
                lines.push('OK — infrastructure is responsive.');
                APP.manage._setOutput(lines.join('\n'), 'ok');
            } catch (err) {
                APP.manage._setOutput(`ERROR: ${err.message || err}`, 'error');
            }
        } else if (action === 'destroy') {
            APP.manage._confirmDestroy();
        } else if (action === 'bolton') {
            // 2026-05-19 flow-stitching — open the Bolt-ons sub-pill scoped
            // to the currently-active deployment.
            const lab = APP.manage._currentProject() || null;
            if (APP.bolton && typeof APP.bolton.open === 'function') {
                APP.bolton.open(lab);
            } else {
                // Fallback if bolton.open is not yet wired — just navigate.
                if (APP.shell && typeof APP.shell.setActiveRoute === 'function') {
                    APP.shell.setActiveRoute('deployments-tab', 'bolt-ons');
                }
                APP.navigateTo('deployments-tab', 'bolt-ons');
            }
        }
    });
};

/** Resolve the current project name. Sentinels (`__draft__`, `__all__`)
 *  are filtered out — Manage only operates on REAL deployments. The
 *  caller treats an empty string as "no real project picked" and renders
 *  the empty-state CTA instead of leaking sentinel text. */
APP.manage._currentProject = function () {
    if (APP.activeDeployment) {
        if (APP.activeDeployment.isAll && APP.activeDeployment.isAll()) return '';
        if (APP.activeDeployment.isDraft && APP.activeDeployment.isDraft()) return '';
        if (APP.activeDeployment.current) return APP.activeDeployment.current;
    }
    if (typeof getCurrentProjectName === 'function') {
        const name = getCurrentProjectName();
        // getCurrentProjectName may also return a sentinel — filter.
        if (name === '__draft__' || name === '__all__') return '';
        return name;
    }
    return '';
};

/** Confirm + invoke destroy. */
APP.manage._confirmDestroy = function () {
    const project = APP.manage._currentProject() || '(active deployment)';
    const msg = `Destroy infrastructure for "${project}"?\n\nThis is non-reversible — all EC2 instances, networking, and state will be torn down. Snapshots and Terraform state archives are kept.`;
    const proceed = () => {
        if (typeof destroyInfrastructure === 'function') {
            destroyInfrastructure(project === '(active deployment)' ? null : project);
        } else {
            console.warn('destroyInfrastructure() not available');
        }
    };
    if (window.APP && typeof window.APP.modal === 'function') {
        try {
            window.APP.modal({
                title: 'Destroy deployment',
                body: msg,
                danger: true,
                confirmLabel: 'Destroy',
                onConfirm: proceed,
            });
            return;
        } catch (_) { /* fall through */ }
    }
    if (window.confirm(msg)) proceed();
};

/**
 * 2026-05-19 audit fix — Hide / show the GOAD Lab section based on the active
 * deployment's type. The section only makes sense for goad-* or combined-*
 * deployments; for every other case (including "no deployment selected"),
 * it stays hidden.
 *
 * Sibling concern: populateGoadSection() (refreshDeployments → loadGoadStatus)
 * also flips display based on the /api/goad/status payload. This guard is the
 * authoritative override — it hard-hides when the active project isn't a
 * GOAD-bearing type, so the operator never sees the "Vulnerable Active
 * Directory environment for testing." copy on a C2-only project.
 */
APP.manage._evaluateGoadSection = function (deployType) {
    const section = document.getElementById('goad-lab-section');
    if (!section) return;
    const t = String(deployType || '').toLowerCase();
    const isGoadOrCombined = t.startsWith('goad-') || t.startsWith('combined-');
    if (!isGoadOrCombined) {
        section.style.display = 'none';
        const provSection = document.getElementById('goad-provision-section');
        if (provSection) provSection.style.display = 'none';
        return;
    }
    // GOAD-bearing project — populateGoadSection (loadGoadStatus) is the
    // source of truth for whether the project actually has provisioned GOAD
    // infrastructure. Trigger a refresh so the section reflects the live
    // state of the currently-active project, not whatever was visible last.
    if (typeof loadGoadStatus === 'function') {
        try { loadGoadStatus(); } catch (_) { /* surfaced via populate */ }
    }
};

/**
 * 2026-05-19 audit fix — Scope the resource-list-section + deployment timeline
 * to the active project. The full inventory + history still loads in the
 * background (refreshAll() still triggers the underlying fetches), but the
 * visible rows are filtered to entries tagged with the active project so
 * operators don't see every deployment in the account on the Manage page.
 */
APP.manage._scopeProjectViews = function (projectName) {
    const tableBody = document.getElementById('resource-table-body');
    const scopeDiv = document.getElementById('resource-scope-info');
    if (tableBody && typeof window.allResources !== 'undefined' && Array.isArray(window.allResources)) {
        if (!projectName) {
            tableBody.innerHTML = `<div class="resource-list-v3__empty">Pick a deployment from the top bar to manage it.</div>`;
            if (scopeDiv) scopeDiv.innerHTML = '<span class="t-muted">No deployment selected &mdash; full inventory hidden.</span>';
        } else {
            const scoped = window.allResources.filter(r => r.project === projectName);
            if (scoped.length === 0) {
                tableBody.innerHTML = `<div class="resource-list-v3__empty">No live resources tagged <code>${APP.manage._escape(projectName)}</code>.</div>`;
            } else if (typeof renderResourceTable === 'function') {
                renderResourceTable(scoped);
            }
            if (scopeDiv) {
                scopeDiv.innerHTML = `<span class="spec-pill spec-pill--live"><span class="spec-pill__dot" aria-hidden="true"></span>SCOPED</span> &nbsp;Showing resources tagged <strong>${APP.manage._escape(projectName)}</strong>`;
            }
        }
    }

    // Timeline filter — read by _renderDeploymentTimelineNow.
    APP.manage._timelineFilter = projectName || null;
    if (typeof renderDeploymentTimeline === 'function') {
        try { renderDeploymentTimeline(); } catch (_) { /* render guards on its own */ }
    }
};

/** Pull live data + render the hero / spec-list. Re-entrant. */
APP.manage.render = async function () {
    const view = document.getElementById('manage-view');
    const heroName = document.getElementById('manage-hero-name');
    const heroType = document.getElementById('manage-hero-type');
    const heroState = document.getElementById('manage-hero-state');
    const specList = document.getElementById('manage-spec-list');
    if (!view || !specList) return;

    APP.manage._wireActions();

    const project = APP.manage._currentProject();
    if (!project) {
        view.style.display = 'block';
        if (heroName) heroName.textContent = '(no deployment selected)';
        if (heroType) heroType.textContent = '—';
        if (heroState) heroState.textContent = '';
        APP.manage._updateStatusPill('idle');
        specList.innerHTML = `
            <div class="manage-empty">
                <p class="manage-empty__title">No deployment selected</p>
                <p class="manage-empty__body">Pick a deployment from the top-bar selector to manage it, or deploy a new one from the Deploy sub-pill.</p>
            </div>
        `;
        APP.manage._evaluateGoadSection('');
        APP.manage._scopeProjectViews(null);
        return;
    }

    view.style.display = 'block';
    if (heroName) heroName.textContent = project;
    if (heroState) heroState.textContent = '';
    if (heroType) heroType.textContent = 'loading…';

    const [infraRes, statusRes, costRes, auditEntry, configRes, outputsRes] = await Promise.all([
        fetch(`/api/deploy/infrastructure?project=${encodeURIComponent(project)}`).then(r => r.json()).catch(() => ({ success: false })),
        fetch(`/api/deploy/status?project=${encodeURIComponent(project)}`).then(r => r.json()).catch(() => ({ success: false })),
        fetch('/api/costs/aggregate').then(r => r.json()).catch(() => ({ success: false })),
        APP.manage._loadLastTouched(project),
        fetch('/api/config').then(r => r.json()).catch(() => ({ success: false })),
        fetch(`/api/deploy/outputs?project=${encodeURIComponent(project)}`).then(r => r.json()).catch(() => ({ success: false })),
    ]);

    const hasDeployment = !!(infraRes && infraRes.has_deployment);
    const config = (configRes && configRes.config) || {};
    const outputs = (outputsRes && outputsRes.success && outputsRes.outputs) ? outputsRes.outputs : {};
    // deployment_type resolution order: per-project status (most authoritative) →
    // terraform output → infra deployment_mode → global config (fallback).
    const deployType =
        (statusRes?.status?.deployment_type) ||
        (outputs.deployment_type) ||
        (infraRes && infraRes.deployment_mode) ||
        config.deployment_type ||
        '';
    const deployConfig = (typeof DEPLOYMENT_CONFIGS !== 'undefined') ? DEPLOYMENT_CONFIGS[deployType] : null;

    if (heroType) heroType.textContent = deployConfig?.title || deployType || '—';
    if (heroState) {
        if (hasDeployment) heroState.textContent = 'live infrastructure';
        else heroState.textContent = 'no live infrastructure';
    }

    if (statusRes?.status?.deployed) APP.manage._updateStatusPill('live');
    else if (statusRes?.status?.last_error) APP.manage._updateStatusPill('error');
    else if (hasDeployment) APP.manage._updateStatusPill('live');
    else APP.manage._updateStatusPill('idle');

    let projectCost = null;
    if (costRes?.success && Array.isArray(costRes.deployments)) {
        const entry = costRes.deployments.find(d => d.project_name === project);
        if (entry && Number.isFinite(entry.monthly)) projectCost = entry.monthly;
    }

    const rows = APP.manage._buildRows({
        infrastructure: infraRes || {},
        cost: projectCost,
        audit: auditEntry,
        config: config,
        outputs: outputs,
        deploymentType: deployType,
        account_id: infraRes?.account_id || '',
        instance_states: {},
        hasDeployment: hasDeployment,
    });

    specList.innerHTML = rows.map(APP.manage._renderRow).join('');

    // Reactive show/hide of the GOAD section + scoped resource / history views.
    APP.manage._evaluateGoadSection(deployType);
    APP.manage._scopeProjectViews(project);
};

/** Init hook — idempotent. */
APP.manage.init = function () {
    if (APP.manage._initDone) return;
    APP.manage._initDone = true;
    APP.manage._wireActions();
    if (APP.activeDeployment && typeof APP.activeDeployment.subscribe === 'function') {
        APP.activeDeployment.subscribe(() => {
            const pane = document.getElementById('subpill-pane-manage');
            if (!pane || pane.hidden) return;
            // 2026-05-19 (deployments nav restructure) — In All mode the
            // scoped manage view is hidden; render the fleet table instead.
            if (APP.activeDeployment.isAll && APP.activeDeployment.isAll()) {
                if (APP.manageFleet && typeof APP.manageFleet.render === 'function') {
                    APP.manageFleet.render();
                }
                return;
            }
            APP.manage.render();
        });
    }
};

// Wire on DOMContentLoaded so APP.activeDeployment subscriber is in place
// before any subpill activation. Idempotent with the in-init hook below.
if (typeof window !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            try { APP.manage.init(); } catch (e) { console.warn('APP.manage.init failed:', e); }
        });
    } else {
        try { APP.manage.init(); } catch (e) { console.warn('APP.manage.init failed:', e); }
    }
}
// === end PHASE 3A Manage sub-pill =====================================

// ============================================================================
// 2026-05-19 (deployments nav restructure) — APP.manageFleet
//
// Renders the All-mode fleet table in the Manage sub-pill. Columns:
//   Project (mono) · Type · Status · Resources · Cost · Operator · Last touched · →
// Row click → APP.activeDeployment.set(projectName) which causes the
// per-deployment Manage view to reappear via the existing subscriber wiring.
// ============================================================================
APP.manageFleet = APP.manageFleet || {
    _esc(v) {
        return String(v == null ? '' : v).replace(/[&<>"']/g, m => (
            { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]
        ));
    },
    _fmtAgo(ts) {
        if (!ts) return '—';
        let sec;
        if (typeof ts === 'number') {
            sec = Math.floor(Date.now() / 1000) - Number(ts);
        } else {
            const t = Date.parse(ts);
            if (Number.isNaN(t)) return '—';
            sec = Math.floor((Date.now() - t) / 1000);
        }
        if (sec < 60) return `${sec}s ago`;
        if (sec < 3600) return `${Math.floor(sec / 60)}m ago`;
        if (sec < 86400) return `${Math.floor(sec / 3600)}h ago`;
        return `${Math.floor(sec / 86400)}d ago`;
    },
    async render() {
        const host = document.getElementById('manage-all-mode');
        if (!host) return;
        const esc = this._esc;
        const fmtAgo = this._fmtAgo;

        host.innerHTML = `
            <div class="manage-fleet" role="region" aria-label="Fleet deployments">
              <div class="manage-fleet__head">
                <h3 class="manage-fleet__title empty-state__title">All deployments</h3>
                <p class="manage-fleet__subtitle">Click a row to focus a project. Use the top-bar selector to leave All mode.</p>
              </div>
              <div class="manage-fleet__error-banner" data-fleet-errors hidden></div>
              <div class="manage-fleet__body">
                <table class="manage-fleet__table" role="table">
                  <thead><tr>
                    <th>Project</th>
                    <th>Type</th>
                    <th>Status</th>
                    <th>Resources</th>
                    <th>Cost</th>
                    <th>Operator</th>
                    <th>Last touched</th>
                    <th aria-label="Open"></th>
                  </tr></thead>
                  <tbody data-fleet-tbody>
                    <tr><td colspan="8" class="manage-fleet__cell--empty">Loading deployments…</td></tr>
                  </tbody>
                </table>
              </div>
            </div>`;
        const tbody = host.querySelector('[data-fleet-tbody]');
        const errBanner = host.querySelector('[data-fleet-errors]');

        let deployments = [];
        let costs = {};
        try {
            const [activeRes, costRes] = await Promise.all([
                fetch('/api/deploy/active').then(r => r.json()).catch(() => ({})),
                fetch('/api/costs/aggregate').then(r => r.json()).catch(() => ({})),
            ]);
            const raw = Array.isArray(activeRes)
                ? activeRes
                : (Array.isArray(activeRes?.deployments) ? activeRes.deployments
                   : (Array.isArray(activeRes?.active_deployments) ? activeRes.active_deployments : []));
            deployments = raw.map(d => ({
                ...d,
                project_name: d.project_name || d._filename || d.name || 'unknown',
            }));
            if (costRes && Array.isArray(costRes.deployments)) {
                costRes.deployments.forEach(c => {
                    if (c && c.project_name) costs[c.project_name] = c.monthly;
                });
            }
        } catch (e) {
            if (errBanner) {
                errBanner.textContent = `Failed to load fleet: ${esc(e.message || 'network error')}`;
                errBanner.hidden = false;
            }
        }

        if (!deployments.length) {
            tbody.innerHTML = `
                <tr><td colspan="8" class="manage-fleet__cell--empty">
                    No active deployments — click <strong>+ New</strong> in the top bar to start one.
                </td></tr>`;
            return;
        }

        tbody.innerHTML = deployments.map(d => {
            const name = d.project_name;
            const type = d.deployment_type || d.deployment_mode || '—';
            const status = (d.status || 'unknown').toLowerCase();
            const statusLabel = status === 'success' ? 'live' : status;
            const resourceCount = Array.isArray(d.resources)
                ? d.resources.length
                : (typeof d.resource_count === 'number' ? d.resource_count : '—');
            const cost = costs[name];
            const costLabel = (cost != null && Number.isFinite(cost)) ? `$${cost.toFixed(0)}/mo` : '—';
            const op = d.operator || d.owner || '—';
            const lastTouched = d.last_touched || d.updated_at || d.timestamp || d.completed_at;
            return `<tr class="manage-fleet__row" role="link" tabindex="0"
                        data-fleet-project="${esc(name)}">
                      <td class="manage-fleet__cell manage-fleet__cell--mono manage-fleet__name">${esc(name)}</td>
                      <td class="manage-fleet__cell">${esc(type)}</td>
                      <td class="manage-fleet__cell">
                        <span class="spec-pill spec-pill--${status === 'success' ? 'live' : 'draft'}">
                          <span class="spec-pill__dot" aria-hidden="true"></span>${esc(statusLabel)}
                        </span>
                      </td>
                      <td class="manage-fleet__cell manage-fleet__cell--mono">${esc(resourceCount)}</td>
                      <td class="manage-fleet__cell manage-fleet__cell--mono">${esc(costLabel)}</td>
                      <td class="manage-fleet__cell">${esc(op)}</td>
                      <td class="manage-fleet__cell">${esc(fmtAgo(lastTouched))}</td>
                      <td class="manage-fleet__cell manage-fleet__arrow" aria-hidden="true">›</td>
                    </tr>`;
        }).join('');

        tbody.querySelectorAll('.manage-fleet__row').forEach(row => {
            const activate = () => {
                const project = row.dataset.fleetProject;
                if (!project) return;
                APP.activeDeployment.set(project);
            };
            row.addEventListener('click', activate);
            row.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); activate(); }
            });
        });
    },
};

// ============================================================================
// 2026-05-19 (deployments nav restructure) — APP.manageDrawer
//
// Right-side scrim takeover for "Edit configuration" of the active project.
// Loads via GET /api/config (backend does not yet support ?project= filter
// at the route level, so the drawer scopes by name in the form metadata;
// the POST writes the active terraform.tfvars). Apply hands off to the
// existing startDeployment() flow.
// ============================================================================
APP.manageDrawer = APP.manageDrawer || {
    _project: null,
    _config: null,
    _wired: false,

    _esc(v) {
        return String(v == null ? '' : v).replace(/[&<>"']/g, m => (
            { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]
        ));
    },

    _wire() {
        if (this._wired) return;
        this._wired = true;
        const scrim = document.getElementById('manage-drawer-scrim');
        const card = document.getElementById('manage-drawer-card');
        if (!scrim || !card) return;
        // Backdrop click on scrim (outside card) closes.
        scrim.addEventListener('click', (e) => {
            if (e.target === scrim) this.close();
        });
        // Any [data-drawer-dismiss] closes.
        scrim.querySelectorAll('[data-drawer-dismiss]').forEach(btn => {
            btn.addEventListener('click', () => this.close());
        });
        // Save commits the form values via POST /api/config.
        scrim.querySelectorAll('[data-drawer-save]').forEach(btn => {
            btn.addEventListener('click', () => this._save());
        });
        // Apply hands off to startDeployment().
        scrim.querySelectorAll('[data-drawer-apply]').forEach(btn => {
            btn.addEventListener('click', () => this._apply());
        });
        // ESC closes (only when drawer is open).
        document.addEventListener('keydown', (e) => {
            if (e.key !== 'Escape') return;
            if (scrim.getAttribute('data-open') === 'true') {
                e.preventDefault();
                this.close();
            }
        });
    },

    async open(projectName) {
        this._wire();
        const scrim = document.getElementById('manage-drawer-scrim');
        const card = document.getElementById('manage-drawer-card');
        const body = document.getElementById('manage-drawer-body');
        const titleProject = scrim?.querySelector('[data-drawer-project]');
        if (!scrim || !card || !body) return;
        // 2026-05-19 — filter sentinel values defensively so `__draft__`
        // or `__all__` never leaks into the drawer title even if a caller
        // bypassed the guard at the dispatcher.
        let resolved = projectName || (APP.activeDeployment.current || '');
        if (resolved === APP.activeDeployment.DRAFT_SENTINEL ||
            resolved === APP.activeDeployment.ALL_SENTINEL) {
            resolved = '';
        }
        this._project = resolved;
        if (titleProject) {
            titleProject.textContent = APP.activeDeployment.displayName(this._project) || '—';
        }
        body.innerHTML = '<p class="t-muted">Loading…</p>';
        scrim.hidden = false;
        card.hidden = false;
        // Force reflow before flipping data-open so transitions play.
        // eslint-disable-next-line no-unused-expressions
        scrim.offsetHeight;
        scrim.setAttribute('data-open', 'true');
        card.setAttribute('data-open', 'true');

        // GET /api/config?project=<name> — backend now honors the
        // ?project= filter (sanitizes the name + resolves to
        // configs/<name>.tfvars, falling back to the global tfvars).
        try {
            const url = `/api/config/?project=${encodeURIComponent(this._project)}`;
            const resp = await fetch(url);
            const data = await resp.json();
            if (!data || !data.success) throw new Error(data?.error || 'Failed to load config');
            this._config = data.config || {};
            this._renderForm(body, this._config);
        } catch (e) {
            body.innerHTML = `<p class="message error">Failed to load configuration: ${this._esc(e.message || e)}</p>`;
        }
    },

    close() {
        const scrim = document.getElementById('manage-drawer-scrim');
        const card = document.getElementById('manage-drawer-card');
        if (!scrim || !card) return;
        scrim.setAttribute('data-open', 'false');
        card.setAttribute('data-open', 'false');
        setTimeout(() => {
            if (scrim.getAttribute('data-open') !== 'true') {
                scrim.hidden = true;
                card.hidden = true;
            }
        }, 220);
    },

    _renderForm(body, config) {
        const esc = this._esc;
        const isSecret = (k) => /password|secret|key|token/i.test(k);
        // Sort keys: identity first, then alphabetical.
        const priority = ['project_name', 'deployment_type', 'environment', 'aws_region',
                          'primary_domain', 'admin_email'];
        const keys = Object.keys(config);
        keys.sort((a, b) => {
            const ai = priority.indexOf(a);
            const bi = priority.indexOf(b);
            if (ai !== -1 && bi !== -1) return ai - bi;
            if (ai !== -1) return -1;
            if (bi !== -1) return 1;
            return a.localeCompare(b);
        });
        const rows = keys.map(k => {
            const v = config[k];
            const display = (v == null) ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
            const inputType = isSecret(k) ? 'password' : 'text';
            const valueAttr = isSecret(k) ? '' : ` value="${esc(display)}"`;
            const placeholder = isSecret(k) ? `placeholder="leave blank to keep existing"` : '';
            return `<label class="manage-drawer__field">
                      <span class="manage-drawer__field-label">${esc(k)}</span>
                      <input type="${inputType}" class="form-input manage-drawer__input"
                             data-config-key="${esc(k)}"${valueAttr} ${placeholder} autocomplete="off">
                    </label>`;
        }).join('');
        body.innerHTML = `
            <div class="manage-drawer__form" data-drawer-form>
                <p class="t-muted manage-drawer__hint">
                    Editing terraform.tfvars for <strong>${esc(this._project || '—')}</strong>.
                    Save writes to disk; Apply runs <code>terraform apply</code>.
                </p>
                ${rows || '<p class="t-muted">No configuration loaded.</p>'}
            </div>`;
    },

    _readForm() {
        const body = document.getElementById('manage-drawer-body');
        if (!body) return null;
        const config = { ...(this._config || {}) };
        body.querySelectorAll('[data-config-key]').forEach(inp => {
            const k = inp.dataset.configKey;
            const v = inp.value;
            // For secret fields: if blank, preserve existing (don't clobber).
            const isSecret = inp.type === 'password';
            if (isSecret && v === '') return;
            config[k] = v;
        });
        return config;
    },

    async _save() {
        const body = document.getElementById('manage-drawer-body');
        const config = this._readForm();
        if (!config) return;
        try {
            const url = `/api/config/?project=${encodeURIComponent(this._project || '')}`;
            const resp = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ config }),
            });
            const data = await resp.json();
            if (!resp.ok || !data.success) {
                const errs = (data && data.errors) ? '\n' + (Array.isArray(data.errors) ? data.errors.join('\n') : data.errors) : '';
                throw new Error((data && data.error) ? data.error + errs : 'Save failed');
            }
            this._config = config;
            if (typeof showSuccess === 'function') showSuccess('Configuration saved');
            this.close();
            // Refresh the Manage view since we wrote new config.
            if (APP.manage && typeof APP.manage.render === 'function') {
                APP.manage.render();
            }
        } catch (e) {
            if (body) {
                const banner = document.createElement('p');
                banner.className = 'message error';
                banner.textContent = `Save failed: ${e.message || e}`;
                body.prepend(banner);
            } else {
                window.alert(`Save failed: ${e.message || e}`);
            }
        }
    },

    async _apply() {
        // Save first, then hand off to startDeployment() which runs terraform.
        const ok = await this._saveAndStay();
        if (!ok) return;
        this.close();
        if (typeof startDeployment === 'function') {
            try { startDeployment(); } catch (e) { console.error('startDeployment failed', e); }
        } else {
            // Fallback: navigate to Deploy sub-pill so the operator can apply manually.
            APP.subPills.setActive('deploy');
        }
    },

    async _saveAndStay() {
        const config = this._readForm();
        if (!config) return false;
        try {
            const url = `/api/config/?project=${encodeURIComponent(this._project || '')}`;
            const resp = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ config }),
            });
            const data = await resp.json();
            if (!resp.ok || !data.success) {
                throw new Error((data && data.error) || 'Save failed');
            }
            this._config = config;
            return true;
        } catch (e) {
            window.alert(`Save failed: ${e.message || e}`);
            return false;
        }
    },
};

// Wire the manage-actions toolbar's "Edit configuration" entry (if rendered)
// + a fallback: any element in Manage with data-action="edit-config" opens
// the drawer. The actions strip's existing logs/health buttons remain.
if (typeof document !== 'undefined') {
    document.addEventListener('click', (e) => {
        const trigger = e.target.closest('[data-action="manage-edit-config"]');
        if (!trigger) return;
        e.preventDefault();
        const project = APP.activeDeployment.current;
        if (!project || project === APP.activeDeployment.ALL_SENTINEL || project === APP.activeDeployment.DRAFT_SENTINEL) {
            return;
        }
        APP.manageDrawer.open(project);
    });
}


// ============================================================================
// v3 PALETTE (Agent B, 2026-05-18)
//
// Global ⌘K (Ctrl-K) command palette. Indexes the backend's
// /api/palette/index surface (routes, actions, deployments, operators,
// audit entries, bolt-on vulns, settings sections, …) and presents a
// fuzzy-matched, keyboard-navigable list overlay.
//
// Design notes:
//   - The full index is fetched on FIRST open and cached for the
//     remainder of the session. A second open re-uses the cache. The
//     palette is cheap to rebuild server-side, so we don't aggressively
//     invalidate; APP.palette.refresh() is provided for callers who
//     change palette-relevant state (operator switch, new deployment).
//   - Item dispatch goes through _dispatchTarget which understands two
//     shapes:
//         { page: '<name>', subpill?: '<name>', anchor?: '<id>' }
//             → APP.navigateTo() + post-render scroll if anchor supplied
//         { action: '<verb>', ...params }
//             → switch over known APP.* / DOM hooks
//   - Selections POST to /api/palette/select so the operator's
//     recently-used list is server-side (per-operator, persisted).
//   - Sibling agents C / D may extend the action verb list, but the
//     palette itself does not import from their namespaces — every
//     dispatch goes through a single switch keyed on target.action.
// ============================================================================

APP.palette = {
    // Cached index from /api/palette/index. Populated on first open.
    index: [],
    recentlyUsed: [],
    _loaded: false,
    _loading: null,        // pending fetch promise (debounce concurrent opens)
    _open: false,
    _previousFocus: null,
    _activeIndex: 0,
    _visibleItems: [],     // currently-rendered (filtered) item list
    _lastQuery: '',

    /**
     * Wire the trigger button + global ⌘K / Ctrl-K keybinding. Idempotent.
     */
    init() {
        if (this._wired) return;
        this._wired = true;

        const trigger = document.getElementById('palette-trigger');
        if (trigger) {
            trigger.addEventListener('click', () => this.open());
        }

        // Close handlers — wired once on the static shell.
        document.querySelectorAll('[data-palette-close]').forEach((el) => {
            el.addEventListener('click', () => this.close());
        });

        // Search input — re-filter on every keystroke.
        const input = document.getElementById('palette-input');
        if (input) {
            input.addEventListener('input', () => this._onInput());
            input.addEventListener('keydown', (e) => this._onKey(e));
        }

        // Global keybinding. preventDefault stops the browser's "find" /
        // "history" defaults. We toggle so a second press dismisses.
        document.addEventListener('keydown', (e) => {
            const key = (e.key || '').toLowerCase();
            if ((e.metaKey || e.ctrlKey) && key === 'k') {
                e.preventDefault();
                if (this._open) this.close();
                else this.open();
            }
        });
    },

    /**
     * Open the palette overlay. Lazy-loads the index on first call.
     */
    open() {
        if (this._open) return;
        const overlay = document.getElementById('palette-overlay');
        if (!overlay) return;
        this._previousFocus = document.activeElement;
        overlay.hidden = false;
        this._open = true;

        // Clear input + selection from the prior session so the operator
        // always starts from a clean RECENT view.
        const input = document.getElementById('palette-input');
        if (input) {
            input.value = '';
            this._lastQuery = '';
        }
        this._activeIndex = 0;

        // Load (or use cached) index, then paint.
        this._ensureIndex().then(() => {
            this._render();
            // Focus the input AFTER paint so the operator can immediately type.
            if (input) input.focus();
        }).catch((err) => {
            console.warn('palette: index load failed', err);
            this._renderError(err);
            if (input) input.focus();
        });
    },

    /**
     * Close the palette overlay and restore prior focus.
     */
    close() {
        if (!this._open) return;
        const overlay = document.getElementById('palette-overlay');
        if (overlay) overlay.hidden = true;
        this._open = false;
        // Restore focus to whoever had it before open() (typically the
        // top-bar trigger; could also be a deep-page element if the
        // operator hit ⌘K from anywhere).
        if (this._previousFocus && typeof this._previousFocus.focus === 'function') {
            try { this._previousFocus.focus(); } catch (_) {}
        }
        this._previousFocus = null;
    },

    /**
     * Force-reload the index (e.g., after operator switch / new deployment).
     */
    refresh() {
        this._loaded = false;
        this._loading = null;
        if (this._open) {
            this._ensureIndex().then(() => this._render());
        }
    },

    /**
     * Fetch + cache the index. Returns the cached promise if a fetch is
     * already in flight.
     */
    _ensureIndex() {
        if (this._loaded) return Promise.resolve();
        if (this._loading) return this._loading;
        this._loading = fetch('/api/palette/index')
            .then((r) => {
                if (!r.ok) throw new Error('palette index HTTP ' + r.status);
                return r.json();
            })
            .then((data) => {
                this.index = Array.isArray(data.items) ? data.items : [];
                this.recentlyUsed = Array.isArray(data.recently_used)
                    ? data.recently_used : [];
                this._loaded = true;
                this._loading = null;
            })
            .catch((err) => {
                this._loading = null;
                throw err;
            });
        return this._loading;
    },

    /**
     * Fuzzy-match scorer. Splits the query into whitespace terms; each
     * item is scored across label / subtitle / keywords. The final score
     * is the sum across terms minus a small length penalty so short,
     * specific items rank above long, generic ones at the same hit type.
     *
     * Hit weights (per term):
     *   exact label match  → 10000
     *   label prefix       →  1000
     *   label substring    →   100
     *   subtitle substring →    10
     *   keyword substring  →     5
     *   misses             →     0 (entire item is dropped if total = 0)
     */
    search(query) {
        const q = (query || '').trim().toLowerCase();
        if (!q) return this.index.slice();

        const terms = q.split(/\s+/).filter(Boolean);
        const scored = [];
        for (const item of this.index) {
            const label = (item.label || '').toLowerCase();
            const subtitle = (item.subtitle || '').toLowerCase();
            const keywords = Array.isArray(item.keywords) ? item.keywords : [];

            let score = 0;
            let matchedTerms = 0;
            for (const term of terms) {
                let termScore = 0;
                if (label === term) termScore = 10000;
                else if (label.startsWith(term)) termScore = 1000;
                else if (label.includes(term)) termScore = 100;
                else if (subtitle.includes(term)) termScore = 10;
                else {
                    for (const kw of keywords) {
                        if (typeof kw === 'string' && kw.toLowerCase().includes(term)) {
                            termScore = 5;
                            break;
                        }
                    }
                }
                if (termScore > 0) matchedTerms++;
                score += termScore;
            }
            // Require all terms to hit somewhere — partial matches drop.
            if (matchedTerms !== terms.length || score === 0) continue;

            // Penalize longer labels marginally so short ones win on ties.
            const lenPenalty = Math.min(label.length, 80) * 0.1;
            scored.push({ item, score: score - lenPenalty });
        }
        scored.sort((a, b) => b.score - a.score);
        return scored.map((s) => s.item);
    },

    /**
     * Filter on input; re-paint. Resets active selection to row 0 so the
     * Enter key always reads the top match after typing.
     */
    _onInput() {
        const input = document.getElementById('palette-input');
        if (!input) return;
        this._lastQuery = input.value;
        this._activeIndex = 0;
        this._render();
    },

    /**
     * Keyboard navigation inside the palette.
     */
    _onKey(e) {
        if (!this._open) return;
        switch (e.key) {
            case 'Escape':
                e.preventDefault();
                this.close();
                return;
            case 'ArrowDown':
                e.preventDefault();
                this._move(1);
                return;
            case 'ArrowUp':
                e.preventDefault();
                this._move(-1);
                return;
            case 'Enter':
                e.preventDefault();
                if (this._visibleItems.length > 0) {
                    const idx = Math.max(0, Math.min(this._activeIndex,
                        this._visibleItems.length - 1));
                    this.selectItem(this._visibleItems[idx]);
                }
                return;
            default:
                return;
        }
    },

    _move(delta) {
        if (this._visibleItems.length === 0) return;
        const n = this._visibleItems.length;
        this._activeIndex = (this._activeIndex + delta + n) % n;
        this._highlight();
    },

    _highlight() {
        const rows = document.querySelectorAll('#palette-results .palette-overlay__row');
        rows.forEach((row, i) => {
            row.classList.toggle('is-active', i === this._activeIndex);
            if (i === this._activeIndex) {
                row.scrollIntoView({ block: 'nearest' });
            }
        });
    },

    /**
     * Paint the results sections. Two phases:
     *   - Empty query → RECENT (resolved from MRU id list) + full index
     *     bucketed by kind, in the canonical ROUTES → ACTIONS → … order.
     *   - Non-empty query → flat TOP RESULTS section, capped at 30.
     */
    _render() {
        const container = document.getElementById('palette-results');
        if (!container) return;

        const q = (this._lastQuery || '').trim();
        let sections;
        if (q) {
            const results = this.search(q).slice(0, 30);
            sections = [{ label: 'TOP RESULTS', items: results }];
            this._visibleItems = results.slice();
        } else {
            sections = this._buildEmptySections();
            this._visibleItems = sections.reduce((acc, s) =>
                acc.concat(s.items), []);
        }

        if (this._visibleItems.length === 0) {
            container.innerHTML = '<div class="palette-overlay__empty">No matches.</div>';
            return;
        }

        // Bound the active index to the visible list.
        if (this._activeIndex >= this._visibleItems.length) {
            this._activeIndex = 0;
        }

        let html = '';
        let runningIndex = 0;
        for (const section of sections) {
            if (section.items.length === 0) continue;
            html += `<div class="palette-overlay__section-label">${this._esc(section.label)}</div>`;
            for (const item of section.items) {
                html += this._renderRow(item, runningIndex === this._activeIndex);
                runningIndex++;
            }
        }
        container.innerHTML = html;

        // Wire row click handlers + hover-to-active.
        const rows = container.querySelectorAll('.palette-overlay__row');
        rows.forEach((row, i) => {
            row.addEventListener('mouseenter', () => {
                this._activeIndex = i;
                this._highlight();
            });
            row.addEventListener('click', () => {
                if (this._visibleItems[i]) {
                    this.selectItem(this._visibleItems[i]);
                }
            });
        });
    },

    _renderRow(item, isActive) {
        const kind = String(item.kind || '').toUpperCase();
        const label = this._esc(item.label || '');
        const subtitle = this._esc(item.subtitle || '');
        const dot = item.color
            ? `<span class="palette-overlay__row-dot" style="color: ${this._esc(item.color)}"></span>`
            : '';
        return (
            `<div class="palette-overlay__row${isActive ? ' is-active' : ''}"` +
            ` role="option" aria-selected="${isActive ? 'true' : 'false'}"` +
            ` data-palette-id="${this._esc(item.id || '')}">` +
                `<span class="palette-overlay__row-kind">${this._esc(kind)}</span>` +
                dot +
                `<span class="palette-overlay__row-body">` +
                    `<span class="palette-overlay__row-label">${label}</span>` +
                    (subtitle
                        ? `<span class="palette-overlay__row-subtitle">${subtitle}</span>`
                        : '') +
                `</span>` +
                `<span class="palette-overlay__row-kbd">&crarr;</span>` +
            `</div>`
        );
    },

    /**
     * Group the full index into RECENT + by-kind sections for the empty-
     * search state.
     */
    _buildEmptySections() {
        const indexById = new Map();
        for (const it of this.index) indexById.set(it.id, it);

        const recents = (this.recentlyUsed || [])
            .map((id) => indexById.get(id))
            .filter(Boolean)
            .slice(0, 8);
        const recentIds = new Set(recents.map((r) => r.id));

        const buckets = {
            route: [], action: [], deployment: [], beacon: [], session: [],
            operator: [], 'audit-entry': [], vuln: [], setting: [],
        };
        for (const item of this.index) {
            if (recentIds.has(item.id)) continue;
            const kind = item.kind || 'other';
            if (buckets[kind]) buckets[kind].push(item);
            else (buckets._other = buckets._other || []).push(item);
        }

        const sections = [
            { label: 'RECENT', items: recents },
            { label: 'ROUTES', items: buckets.route },
            { label: 'ACTIONS', items: buckets.action },
            { label: 'DEPLOYMENTS', items: buckets.deployment },
            { label: 'OPERATORS', items: buckets.operator },
            { label: 'BEACONS', items: buckets.beacon },
            { label: 'SESSIONS', items: buckets.session },
            { label: 'VULNERABILITIES', items: buckets.vuln },
            { label: 'AUDIT', items: buckets['audit-entry'].slice(0, 10) },
        ];
        if (buckets._other) {
            sections.push({ label: 'OTHER', items: buckets._other });
        }
        return sections;
    },

    _renderError(err) {
        const container = document.getElementById('palette-results');
        if (!container) return;
        container.innerHTML =
            '<div class="palette-overlay__empty">' +
            'Failed to load palette index — ' + this._esc(String(err && err.message || err)) +
            '</div>';
        this._visibleItems = [];
    },

    _esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    },

    /**
     * Record the selection server-side (best-effort), then dispatch the
     * item's target. We don't await the POST — operators expect the UI
     * to react instantly. The MRU is reconciled on next open via refresh.
     */
    selectItem(item) {
        if (!item || !item.id) return;
        fetch('/api/palette/select', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: item.id }),
        }).then(() => {
            // Invalidate the cache so the next open shows updated RECENT.
            this._loaded = false;
        }).catch(() => {});

        this.close();
        this._dispatchTarget(item.target || {});
    },

    /**
     * Map the item's `target` blob to an APP-level action. Two shapes:
     *   { action: '<verb>', ... }  — verb switch
     *   { page, subpill?, anchor? } — navigateTo + optional anchor scroll
     */
    _dispatchTarget(target) {
        if (!target || typeof target !== 'object') return;

        // Action verbs first.
        if (target.action) {
            switch (target.action) {
                case 'journey.open':
                    if (APP.journey && typeof APP.journey.open === 'function') {
                        APP.journey.open();
                    } else if (typeof APP.startNewDeployment === 'function') {
                        APP.startNewDeployment();
                    }
                    return;
                case 'theme.toggle':
                    if (typeof APP.toggleTheme === 'function') APP.toggleTheme();
                    return;
                case 'operator.switch':
                    if (target.id) {
                        fetch('/api/operators/switch', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ id: target.id }),
                        }).then(() => window.location.reload()).catch(() => {});
                    }
                    return;
                case 'operator.add': {
                    const btn = document.getElementById('operator-menu-add');
                    if (btn) btn.click();
                    return;
                }
                case 'operator.manage':
                    if (APP.operatorManagement
                        && typeof APP.operatorManagement.open === 'function') {
                        APP.operatorManagement.open();
                    } else {
                        const btn = document.getElementById('operator-menu-manage');
                        if (btn) btn.click();
                    }
                    return;
                case 'architecture.open':
                    if (typeof APP.openArchitectureModal === 'function') {
                        APP.openArchitectureModal();
                    }
                    return;
                case 'version.open':
                    if (typeof window.openVersionModal === 'function') {
                        window.openVersionModal();
                    }
                    return;
                case 'changelog.open':
                    window.open('/changelog', '_blank', 'noopener');
                    return;
                case 'aws.check':
                    APP.navigateTo('settings');
                    setTimeout(() => this._scrollToAnchor('settings-prereqs'), 200);
                    return;
                case 'health.run':
                    APP.navigateTo('deployments-tab', 'manage');
                    if (typeof APP.toast === 'function') {
                        APP.toast('Open Manage and click "Health check" on the project', 'info');
                    }
                    return;
                case 'app.refresh':
                    window.location.reload();
                    return;
                case 'deploy.apply':
                case 'deploy.plan':
                case 'deploy.destroy':
                case 'deploy.purge':
                case 'deploy.cancel':
                case 'config.save':
                    // These currently live as buttons on the relevant sub-pill.
                    // Navigate the operator there; the page chrome surfaces the
                    // matching action button. Keyboard-driven invocation can
                    // graduate to direct dispatch in a follow-up.
                    APP.navigateTo('deployments-tab',
                        target.action === 'config.save' ? 'configure' :
                        target.action === 'deploy.plan' ? 'deploy' :
                        target.action === 'deploy.destroy' ? 'cleanup' :
                        target.action === 'deploy.purge' ? 'cleanup' :
                        target.action === 'deploy.cancel' ? 'deploy' : 'deploy');
                    return;
                case 'elastic.update': {
                    const btn = document.getElementById('btn-update-elastic-rules');
                    APP.navigateTo('dashboard');
                    setTimeout(() => {
                        const b = document.getElementById('btn-update-elastic-rules');
                        if (b && typeof b.click === 'function') b.click();
                    }, 200);
                    return;
                }
                default:
                    console.warn('palette: unknown action', target.action);
                    return;
            }
        }

        // Navigation targets: page + optional subpill + optional anchor.
        if (target.page) {
            APP.navigateTo(target.page, target.subpill || null);
            if (target.anchor) {
                setTimeout(() => this._scrollToAnchor(target.anchor), 200);
            }
            return;
        }
    },

    _scrollToAnchor(anchorId) {
        const el = document.getElementById(anchorId);
        if (el && typeof el.scrollIntoView === 'function') {
            el.scrollIntoView({ block: 'start', behavior: 'smooth' });
        }
    },
};

// Wire on DOMContentLoaded; idempotent if called later. The palette is
// passive until the operator hits ⌘K or clicks the trigger, so we don't
// load the index proactively (saves one round-trip on every page load).
if (typeof window !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            try { APP.palette.init(); } catch (e) {
                console.warn('APP.palette.init failed:', e);
            }
        });
    } else {
        try { APP.palette.init(); } catch (e) {
            console.warn('APP.palette.init failed:', e);
        }
    }
}

// ============================================================================
// v3 BOLT-ON LIVE (Agent D) — Deployments → Bolt-ons sub-pill controller.
//
// Wires the live UI to /api/bolton/* (Agent B+C backend, surface reconciled
// here). Mirrors webapp/frontend/preview/page-bolton-target.html with REAL
// data. Mounts on _runSubPillInit('deployments-tab', 'bolt-ons').
//
// Surface:
//   APP.bolton.init()            — first-time wiring + initial host list load
//   APP.bolton.loadHosts(lab)    — refresh host dropdown
//   APP.bolton.selectHost(lab,h) — fetch facts + catalog, render rows
//   APP.bolton.applyFilter(s)    — re-render rows per active chip selections
//   APP.bolton.install(v, h)     — dispatch + open progress overlay
//   APP.bolton.uninstall(v, h)   — same
//   APP.bolton.patch(v, h)       — same
//   APP.bolton.patchRevert(v, h) — same
//   APP.bolton.invokeAgent(j)    — dispatch agent intervention on a stuck job
//
// Audit attribution flows through the existing g.operator middleware on the
// route layer — every dispatch action lands in audit.log under the operator
// id from the dashboard_operator cookie.
// ============================================================================
APP.bolton = APP.bolton || {
    state: {
        lab: null,
        host: null,
        hosts: [],
        facts: null,
        catalog: null,           // last /catalog response
        rows: [],                // full row list (with state + category + coverage)
        filters: { category: 'all', state: 'all', coverage: 'all' },
        activeJob: null,
    },
    _initialized: false,

    /** First-time wiring. Idempotent — safe to call on every sub-pill switch. */
    init() {
        const root = document.querySelector('[data-bolton-root]');
        if (!root) return;
        if (!this._initialized) {
            this._initialized = true;
            this._wireSelector();
            this._wireFilters();
            this._wireRefresh();
            this._wireSectionToggles();
        }
        // Resolve active lab — fall back to currentDeploymentProject.
        // If state.lab was preset by APP.bolton.open(), keep it.
        const lab = this.state.lab || this._activeLab();
        if (lab && lab !== this.state.lab) {
            this.state.lab = lab;
            this.loadHosts(lab);
        } else if (this.state.lab) {
            this.loadHosts(this.state.lab);
            // If host was preset (e.g. via APP.bolton.open(lab, host)), select it
            // once hosts finish loading.
            if (this.state.host) {
                const targetHost = this.state.host;
                setTimeout(() => {
                    const sel = document.getElementById('bolton-host-select');
                    if (sel && Array.from(sel.options).some(o => o.value === targetHost)) {
                        sel.value = targetHost;
                        this.selectHost(this.state.lab, targetHost);
                    }
                }, 200);
            }
        }
    },

    /**
     * 2026-05-19 flow-stitching — Public entry point for opening the Bolt-ons
     * sub-pill with a pre-set lab (and optional host). Called from:
     *   - Manage's "Bolt-on vulnerability" button (lab = current project)
     *   - Command palette (lab + host from a structured palette target)
     *
     * Side-effects:
     *   1. Stores lab + host in state so init() picks them up.
     *   2. Navigates to Deployments → Bolt-ons sub-pill (rail handles routing).
     *   3. init() runs via _runSubPillInit, then loadHosts + selectHost fire.
     */
    open(lab, host) {
        if (lab) this.state.lab = lab;
        if (host) this.state.host = host;
        else this.state.host = null;
        // Sync the global active-deployment selector so the rest of the
        // dashboard reflects the lab the operator just bolted onto.
        try {
            if (lab && APP.activeDeployment && typeof APP.activeDeployment.set === 'function') {
                APP.activeDeployment.set(lab);
            }
        } catch (_) { /* noop */ }
        // Navigate via APP.navigateTo so the URL + breadcrumb stay coherent.
        try {
            APP.navigateTo('deployments-tab', 'bolt-ons');
        } catch (_) {
            // Fallback path that mirrors what navigateTo would have done.
            if (APP.shell && typeof APP.shell.setActiveRoute === 'function') {
                APP.shell.setActiveRoute('deployments-tab', 'bolt-ons');
            }
        }
    },

    /** Resolve the active lab id from APP state. */
    _activeLab() {
        try {
            if (typeof window.currentDeploymentProject === 'string' && window.currentDeploymentProject) {
                return window.currentDeploymentProject;
            }
            if (APP.activeDeployment && typeof APP.activeDeployment.get === 'function') {
                const v = APP.activeDeployment.get();
                if (v) return v;
            }
        } catch (_) { /* ignore */ }
        return 'default';
    },

    _wireSelector() {
        const sel = document.getElementById('bolton-host-select');
        if (!sel || sel._boltonWired) return;
        sel._boltonWired = true;
        sel.addEventListener('change', () => {
            const host = sel.value;
            if (!host) return;
            this.selectHost(this.state.lab, host);
        });
    },

    _wireFilters() {
        document.querySelectorAll('#bolton-filters .bt-chip').forEach((chip) => {
            if (chip._boltonWired) return;
            chip._boltonWired = true;
            chip.addEventListener('click', () => {
                const group = chip.dataset.group;
                const value = chip.dataset.value;
                if (!group) return;
                // Update active class within the same group.
                document.querySelectorAll(`#bolton-filters .bt-chip[data-group="${group}"]`).forEach(c => {
                    c.classList.toggle('is-active', c === chip);
                });
                this.state.filters[group] = value;
                this.applyFilter(this.state.filters);
            });
        });
    },

    _wireRefresh() {
        const btn = document.getElementById('bolton-refresh-facts');
        if (!btn || btn._boltonWired) return;
        btn._boltonWired = true;
        btn.addEventListener('click', () => {
            if (!this.state.lab || !this.state.host) return;
            btn.disabled = true;
            btn.textContent = 'Refreshing…';
            fetch(`/api/bolton/labs/${encodeURIComponent(this.state.lab)}/hosts/${encodeURIComponent(this.state.host)}/facts/refresh`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ deep_probe: false }),
            }).then(r => r.json()).then(() => {
                this.selectHost(this.state.lab, this.state.host);
            }).catch((e) => {
                console.warn('[bolton] facts/refresh failed:', e);
            }).finally(() => {
                btn.disabled = false;
                btn.textContent = 'Refresh facts';
            });
        });
    },

    _wireSectionToggles() {
        document.querySelectorAll('#bolton-sections .bt-section__header').forEach((hdr) => {
            if (hdr._boltonWired) return;
            hdr._boltonWired = true;
            hdr.addEventListener('click', () => {
                const section = hdr.closest('.bt-section');
                if (!section) return;
                const open = section.dataset.open === 'true';
                section.dataset.open = open ? 'false' : 'true';
                hdr.setAttribute('aria-expanded', open ? 'false' : 'true');
            });
        });
    },

    /** Populate the host selector for `lab` from /api/bolton/labs/<lab>/hosts. */
    loadHosts(lab) {
        if (!lab) return;
        const sel = document.getElementById('bolton-host-select');
        if (!sel) return;
        sel.innerHTML = '<option value="">Loading hosts…</option>';
        fetch(`/api/bolton/labs/${encodeURIComponent(lab)}/hosts`)
            .then(r => r.json())
            .then(body => {
                if (!body || body.success === false) throw new Error('hosts API returned !success');
                const hosts = body.hosts || [];
                this.state.hosts = hosts;
                if (!hosts.length) {
                    sel.innerHTML = '<option value="">— no hosts in this lab —</option>';
                    return;
                }
                sel.innerHTML = '<option value="">— select a host —</option>' +
                    hosts.map(h => {
                        const name = h.name || h.host_id || '?';
                        const role = h.role ? ` · ${h.role}` : '';
                        return `<option value="${name}">${name}${role}</option>`;
                    }).join('');
            })
            .catch(err => {
                console.warn('[bolton] loadHosts failed:', err);
                sel.innerHTML = '<option value="">— failed to load hosts —</option>';
            });
    },

    /** Fetch host facts + catalog and render. */
    selectHost(lab, host) {
        if (!lab || !host) return;
        this.state.lab = lab;
        this.state.host = host;
        const placeholder = document.getElementById('bolton-empty-state');
        if (placeholder) placeholder.hidden = true;

        const factsP = fetch(`/api/bolton/labs/${encodeURIComponent(lab)}/hosts/${encodeURIComponent(host)}/facts`)
            .then(r => r.ok ? r.json() : { success: false });
        const catalogP = fetch(`/api/bolton/labs/${encodeURIComponent(lab)}/hosts/${encodeURIComponent(host)}/catalog`)
            .then(r => r.ok ? r.json() : { success: false });

        Promise.all([factsP, catalogP]).then(([facts, catalog]) => {
            this.state.facts = facts || null;
            this.state.catalog = catalog || null;
            this._renderHero(facts);
            this._renderSummary(catalog);
            this._renderCategoryChips(catalog);
            this.state.rows = this._buildRows(catalog);
            this.applyFilter(this.state.filters);
            ['bolton-hero', 'bolton-summary', 'bolton-filters', 'bolton-sections'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.hidden = false;
            });
        }).catch(err => {
            console.warn('[bolton] selectHost failed:', err);
        });
    },

    _renderHero(facts) {
        if (!facts) return;
        const kicker = document.getElementById('bolton-hero-kicker');
        const title = document.getElementById('bolton-hero-title');
        const sub = document.getElementById('bolton-hero-sub');
        if (kicker) kicker.textContent = (facts.host || facts.host_id || '').toUpperCase();
        const osLabel = `${(facts.os_family || '').replace(/\b\w/g, c => c.toUpperCase())} ${facts.os_version || ''}`.trim();
        const roleLabel = (facts.role || '').replace(/_/g, ' ');
        if (title) title.textContent = `${osLabel}${roleLabel ? ' · ' + roleLabel : ''}`;
        if (sub) {
            const collected = facts.gathered_at ? new Date(facts.gathered_at).toLocaleString() : '—';
            const stale = facts.stale ? ' · stale cache' : '';
            sub.textContent = `Facts gathered ${collected}${stale}`;
        }
    },

    _renderSummary(catalog) {
        if (!catalog) return;
        const counts = catalog.counts_by_state || {};
        const installedTotal = (counts.ALREADY_INSTALLED || 0);
        const patchedTotal = (counts.PATCHED || 0);
        const availableTotal = (counts.INSTALLABLE || 0);
        const noCoverage = (this.state.rows || []).filter(r => r.coverage === 'no-rule').length;
        const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = String(val); };
        set('bolton-stat-installed', installedTotal);
        set('bolton-stat-patched', patchedTotal);
        set('bolton-stat-no-coverage', noCoverage);
        set('bolton-stat-available', availableTotal);
    },

    _renderCategoryChips(catalog) {
        // Rebuild the category chip row from the unique categories in the catalog.
        if (!catalog || !Array.isArray(catalog.vulns)) return;
        const wrap = document.querySelector('#bolton-filters [data-chip-group="category"]');
        if (!wrap) return;
        const cats = new Set();
        catalog.vulns.forEach(v => { if (v.category) cats.add(v.category); });
        const sorted = [...cats].sort();
        // Preserve the All chip; reset the rest.
        wrap.innerHTML = '<button class="bt-chip is-active" data-group="category" data-value="all" type="button">All</button>';
        sorted.forEach(c => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'bt-chip';
            b.dataset.group = 'category';
            b.dataset.value = c;
            b.textContent = c;
            wrap.appendChild(b);
        });
        // Re-wire chips that were dynamically added.
        this._wireFilters();
    },

    _buildRows(catalog) {
        const vulns = (catalog && catalog.vulns) || [];
        return vulns.map(v => ({
            id: v.id,
            name: v.name,
            category: v.category,
            state: v.state || 'INSTALLABLE',
            coverage: (v.coverage_status || 'no-rule').toLowerCase().replace(/_/g, '-'),
            reason: v.reason,
            blocking: !!v.blocking,
            mitre: v.mitre_technique,
            rollback_supported: !!v.rollback_supported,
            estimated_time_seconds: v.estimated_time_seconds,
        }));
    },

    applyFilter(f) {
        const rows = this.state.rows || [];
        const visible = rows.filter(r => {
            if (f.category && f.category !== 'all' && r.category !== f.category) return false;
            if (f.state && f.state !== 'all' && r.state !== f.state) return false;
            if (f.coverage && f.coverage !== 'all' && r.coverage !== f.coverage) return false;
            return true;
        });
        this._renderSections(visible);
        const count = document.getElementById('bolton-active-count');
        if (count) count.textContent = `${visible.length} of ${rows.length} bolt-ons shown`;
    },

    _sectionFor(row) {
        const s = (row.state || '').toUpperCase();
        if (s === 'ALREADY_INSTALLED') return 'installed';
        if (s === 'INSTALLABLE')       return 'available';
        if (s === 'PATCHED')           return 'patched';
        if (s === 'CONFLICTS_WITH_INSTALLED') return 'conflicts';
        if (s.startsWith('INCOMPATIBLE') || s === 'MISSING_PREREQ' || s === 'MISSING_SOFTWARE') return 'incompatible';
        return 'available';
    },

    _coveragePillClass(cov) {
        if (cov === 'covered') return 'spec-pill--success';
        if (cov === 'partial' || cov === 'rule-stale' || cov === 'stale') return 'spec-pill--warn';
        if (cov === 'no-rule') return 'spec-pill--no-detect';
        return 'spec-pill--warn';
    },

    _renderSections(rows) {
        const buckets = {
            installed: [], available: [], incompatible: [], conflicts: [],
            'already-elsewhere': [], patched: [],
        };
        rows.forEach(r => { buckets[this._sectionFor(r)].push(r); });
        const escapeHtml = (s) => String(s || '').replace(/[&<>\"']/g, c => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
        })[c]);
        Object.entries(buckets).forEach(([section, list]) => {
            const target = document.querySelector(`#bolton-sections [data-rows="${section}"]`);
            if (!target) return;
            const countEl = document.querySelector(`#bolton-sections [data-count="${section}"]`);
            if (countEl) countEl.textContent = String(list.length);
            if (!list.length) {
                target.innerHTML = `<p style="padding:12px 14px;color:var(--text-secondary);font-size:12.5px;margin:0">No bolt-ons in this section for the current filters.</p>`;
                return;
            }
            target.innerHTML = list.map(r => {
                const covPill = `<span class="spec-pill ${this._coveragePillClass(r.coverage)}" style="font-size:9.5px">${escapeHtml(r.coverage)}</span>`;
                const mitre = r.mitre ? `<span class="spec-pill spec-pill--ttp">${escapeHtml(r.mitre)}</span>` : '';
                const cat = r.category ? `<span class="spec-pill spec-pill--cat">${escapeHtml(r.category)}</span>` : '';
                const actions = this._actionsForRow(r);
                const hint = r.reason
                    ? escapeHtml(r.reason)
                    : (r.estimated_time_seconds ? `Est. install time: ~${r.estimated_time_seconds}s` : '');
                return `
                <div class="spec-row bt-row" data-state="${escapeHtml(r.state)}" data-cat="${escapeHtml(r.category || '')}" data-cov="${escapeHtml(r.coverage)}" data-vuln-id="${escapeHtml(r.id)}">
                    <div class="spec-row__head">
                        <div class="bt-row__lead">
                            <div class="bt-row__eyebrow">${cat}${mitre}${covPill}</div>
                        </div>
                        <div class="bt-row__lead">
                            <div class="bt-row__title">${escapeHtml(r.name || r.id)}</div>
                            <div class="bt-row__hint">${hint}</div>
                        </div>
                        <div class="bt-row__actions">${actions}</div>
                    </div>
                </div>`;
            }).join('');
            // Wire action buttons.
            target.querySelectorAll('[data-bolton-action]').forEach(btn => {
                if (btn._boltonWired) return;
                btn._boltonWired = true;
                btn.addEventListener('click', () => {
                    const action = btn.dataset.boltonAction;
                    const vid = btn.dataset.vulnId;
                    if (!action || !vid) return;
                    APP.bolton[action] && APP.bolton[action](vid, APP.bolton.state.host);
                });
            });
            // Task 51 Item 2 — wire "Why?" / "View conflict" buttons to the
            // tooltip. These were previously inert <span title="…"> shells;
            // they now open a Phase 2b-styled popover with state + reason +
            // suggested action pulled straight from the catalog row data.
            target.querySelectorAll('[data-bolton-why]').forEach(btn => {
                if (btn._boltonWhyWired) return;
                btn._boltonWhyWired = true;
                btn.addEventListener('click', (ev) => {
                    ev.preventDefault();
                    ev.stopPropagation();
                    APP.bolton._openWhyTooltip(btn);
                });
            });
        });
    },

    _actionsForRow(r) {
        const id = r.id;
        const btn = (lbl, act, cls = '') => `<button class="spec-edit-btn ${cls}" type="button" data-bolton-action="${act}" data-vuln-id="${id}">${lbl}</button>`;
        const s = (r.state || '').toUpperCase();
        if (s === 'ALREADY_INSTALLED') {
            return [
                btn('Patch', 'patch', 'spec-edit-btn--save'),
                btn('Uninstall', 'uninstall'),
            ].join('');
        }
        if (s === 'PATCHED') {
            const out = [];
            if (r.rollback_supported) out.push(btn('Patch revert', 'patchRevert', 'spec-edit-btn--save'));
            out.push(btn('Uninstall', 'uninstall'));
            return out.join('');
        }
        if (s === 'INSTALLABLE') {
            return btn('Install', 'install', 'spec-edit-btn--save');
        }
        // Task 51 Item 2 — Why? / View conflict now render as real <button>s
        // wired to a click handler that opens a positioned tooltip showing
        // the compatibility state, reason string, and suggested action.
        const escAttr = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        const reason = escAttr(r.reason || '');
        const sug = escAttr(r.suggested_action || '');
        const state = escAttr(r.state || '');
        if (s === 'CONFLICTS_WITH_INSTALLED') {
            return `<button type="button" class="bt-row__why" data-bolton-why data-vuln-id="${id}" data-state="${state}" data-reason="${reason}" data-suggested="${sug}">View conflict</button>`;
        }
        // INCOMPATIBLE_* / MISSING_*
        return `<button type="button" class="bt-row__why" data-bolton-why data-vuln-id="${id}" data-state="${state}" data-reason="${reason}" data-suggested="${sug}">Why?</button>`;
    },

    /**
     * Task 51 Item 2 — open a small popover anchored below the Why? button.
     * Shows compatibility state, reason, and optional suggested action.
     * Outside-click + Escape close it. Position via getBoundingClientRect()
     * + position:fixed, mirroring the deployment-menu pattern elsewhere in
     * app.js. Idempotent: an existing tooltip is replaced.
     */
    _openWhyTooltip(triggerBtn) {
        // Close any existing tooltip first.
        this._closeWhyTooltip();
        if (!triggerBtn) return;
        const state = triggerBtn.dataset.state || '';
        const reason = triggerBtn.dataset.reason || '';
        const sug = triggerBtn.dataset.suggested || '';
        const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        const tooltip = document.createElement('div');
        tooltip.className = 'bolton-why-tooltip';
        tooltip.setAttribute('role', 'tooltip');
        tooltip.dataset.boltonWhyTooltip = '1';
        tooltip.innerHTML = `
            <div class="bolton-why-tooltip__head">
                <span class="bolton-why-tooltip__eyebrow">${esc(state || 'Why?')}</span>
                <button type="button" class="bolton-why-tooltip__close" aria-label="Close">
                    <svg class="icon" aria-hidden="true"><use href="#icon-x"/></svg>
                </button>
            </div>
            <div class="bolton-why-tooltip__body">
                ${reason ? `<p class="bolton-why-tooltip__reason">${esc(reason)}</p>` : '<p class="bolton-why-tooltip__reason"><em>No reason supplied by the catalog.</em></p>'}
                ${sug ? `<div class="bolton-why-tooltip__suggested"><span class="bolton-why-tooltip__suggested-label">Suggested action</span><p>${esc(sug)}</p></div>` : ''}
            </div>
        `;
        document.body.appendChild(tooltip);

        // Anchor below the trigger, clamped to viewport. Width caps at 320px.
        const rect = triggerBtn.getBoundingClientRect();
        const ttRect = tooltip.getBoundingClientRect();
        const maxW = 320;
        const margin = 8;
        let left = rect.left;
        if (left + maxW > window.innerWidth - margin) {
            left = Math.max(margin, window.innerWidth - maxW - margin);
        }
        let top = rect.bottom + 6;
        if (top + ttRect.height > window.innerHeight - margin) {
            // Flip above the trigger if there's no room below.
            top = Math.max(margin, rect.top - ttRect.height - 6);
        }
        tooltip.style.left = `${Math.round(left)}px`;
        tooltip.style.top = `${Math.round(top)}px`;

        // Wire close + outside-click + Escape (capture so the row's row-edit
        // delegate doesn't preempt).
        const closeBtn = tooltip.querySelector('.bolton-why-tooltip__close');
        if (closeBtn) closeBtn.addEventListener('click', () => this._closeWhyTooltip());
        this._whyTooltipEl = tooltip;
        this._whyTooltipTrigger = triggerBtn;
        this._whyOutsideHandler = (ev) => {
            if (!this._whyTooltipEl) return;
            if (ev.target.closest('.bolton-why-tooltip')) return;
            if (ev.target.closest('[data-bolton-why]')) return;
            this._closeWhyTooltip();
        };
        this._whyEscHandler = (ev) => {
            if (ev.key === 'Escape') this._closeWhyTooltip();
        };
        // Defer so the click that opened it doesn't immediately close it.
        setTimeout(() => {
            document.addEventListener('click', this._whyOutsideHandler, true);
            document.addEventListener('keydown', this._whyEscHandler, true);
        }, 0);
    },

    _closeWhyTooltip() {
        if (this._whyTooltipEl && this._whyTooltipEl.parentNode) {
            this._whyTooltipEl.parentNode.removeChild(this._whyTooltipEl);
        }
        this._whyTooltipEl = null;
        this._whyTooltipTrigger = null;
        if (this._whyOutsideHandler) {
            document.removeEventListener('click', this._whyOutsideHandler, true);
            this._whyOutsideHandler = null;
        }
        if (this._whyEscHandler) {
            document.removeEventListener('keydown', this._whyEscHandler, true);
            this._whyEscHandler = null;
        }
    },

    /** Dispatch helpers — all four operations share an envelope. */
    _dispatchOp(op, vulnId, host, body) {
        const lab = this.state.lab;
        if (!lab || !host || !vulnId) return;
        const url = `/api/bolton/labs/${encodeURIComponent(lab)}/hosts/${encodeURIComponent(host)}/${op}/${encodeURIComponent(vulnId)}`;
        this._openProgress(op, vulnId, host);
        fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body || {}),
        }).then(r => r.json()).then(payload => {
            if (!payload || payload.success === false) {
                this._setProgressStatus(payload && payload.error || 'dispatch failed');
                return;
            }
            this.state.activeJob = payload.job_id;
            this._pollJob(payload.job_id);
        }).catch(err => {
            this._setProgressStatus(String(err));
        });
    },

    install(vulnId, host)      { this._dispatchOp('install',       vulnId, host, { run_probe: true }); },
    uninstall(vulnId, host)    { this._dispatchOp('uninstall',     vulnId, host, {}); },
    patch(vulnId, host)        { this._dispatchOp('patch',         vulnId, host, { run_probe: false }); },
    patchRevert(vulnId, host)  { this._dispatchOp('patch-revert',  vulnId, host, {}); },

    // ──────────────────────────────────────────────────────────────────
    // Phase 3a — agentic fallback. Invoked when a job hits STUCK.
    // The agent service returns an AgentProposal we render inline; the
    // operator approves (→ retry) or rejects (→ no state change).
    // ──────────────────────────────────────────────────────────────────

    /** Show the agent invocation panel for a stuck job. Idempotent.
     *
     * task #52: before showing the "Invoke agent" button, we fetch
     * /api/health/agent — if ANTHROPIC_API_KEY is unset OR the anthropic
     * SDK is missing, we render the button disabled with an explainer +
     * a deep-link to Settings → Prereqs. This prevents the operator from
     * discovering the 503 response only after clicking through. */
    _showAgentPanel(jobId) {
        const body = document.getElementById('bolton-progress-body');
        if (!body) return;
        if (document.querySelector('.bolton-agent-panel')) return;  // already there
        const html = `
            <div class="bolton-agent-panel" data-job-id="${jobId}">
              <div class="bolton-agent-panel__header">
                <h4 style="margin:0;font-size:13px;color:var(--text-primary)">Job stuck — invoke agent?</h4>
                <p style="margin:4px 0 12px;color:var(--text-secondary);font-size:12px">
                  Claude will read the failure context + last 200 log lines and propose a remediation.
                  Read-only diagnostics only; you approve before any retry runs.
                </p>
              </div>
              <div class="bolton-agent-panel__body">
                <button class="btn btn-primary" data-bolton-agent-action="invoke">Invoke agent</button>
                <button class="btn btn-secondary" data-bolton-agent-action="dismiss">Dismiss</button>
              </div>
              <div class="bolton-agent-panel__unavailable" hidden>
                <div class="callout callout--warning" data-bolton-agent-unavailable="true" style="margin:0">
                    <strong data-agent-unavailable-headline></strong>
                    <p style="margin:6px 0 0;font-size:12px;color:inherit" data-agent-unavailable-body></p>
                    <p style="margin:8px 0 0;font-size:12px">
                        <a href="#settings-prereqs"
                           class="btn btn-link"
                           data-bolton-agent-action="goto-settings"
                           style="padding:0;background:transparent;border:none;color:var(--info-text);text-decoration:underline">
                            Go to Settings &rarr;
                        </a>
                    </p>
                </div>
              </div>
              <div class="bolton-agent-panel__proposal" hidden>
                <hr style="margin:12px 0;border:none;border-top:1px solid var(--border-default)">
                <p class="bolton-agent-panel__diagnosis" style="margin:0 0 8px;color:var(--text-primary);font-size:13px"></p>
                <p class="bolton-agent-panel__reasoning" style="margin:0 0 8px;color:var(--text-secondary);font-size:12px"></p>
                <details style="margin:0 0 12px">
                  <summary style="cursor:pointer;color:var(--text-secondary);font-size:12px">Tool calls</summary>
                  <ul class="bolton-agent-panel__tool-calls" style="margin:8px 0 0;padding-left:18px;font-size:12px"></ul>
                </details>
                <div class="bolton-agent-panel__action">
                  <button class="btn btn-primary" data-bolton-agent-action="approve">Approve retry</button>
                  <button class="btn btn-secondary" data-bolton-agent-action="reject">Reject</button>
                </div>
              </div>
            </div>
        `;
        body.insertAdjacentHTML('beforeend', html);
        const panel = body.querySelector('.bolton-agent-panel');
        panel.addEventListener('click', (ev) => {
            const target = ev.target.closest('[data-bolton-agent-action]');
            if (!target) return;
            const act = target.dataset.boltonAgentAction;
            if (act === 'invoke') {
                if (target.disabled || target.getAttribute('aria-disabled') === 'true') {
                    ev.preventDefault();
                    return;
                }
                this._invokeAgent(jobId, panel);
            } else if (act === 'dismiss') {
                panel.remove();
            } else if (act === 'approve') {
                this._approveAgentProposal(jobId, panel);
            } else if (act === 'reject') {
                this._rejectAgentProposal(jobId, panel);
            } else if (act === 'goto-settings') {
                ev.preventDefault();
                this._navigateToAgentSettings();
            }
        });

        // task #52 — gate the invoke button on agent health. Default to
        // permissive (button enabled) so a transient fetch failure doesn't
        // strand the operator; only DISABLE on confirmed not-configured.
        this._gateInvokeAgentButton(panel);
    },

    /** task #52 — fetch /api/health/agent and disable the invoke button
     * if the agent fallback is not configured. Called from _showAgentPanel. */
    _gateInvokeAgentButton(panel) {
        if (typeof fetchAgentHealth !== 'function') return;
        fetchAgentHealth(true).then((health) => {
            if (!health) return;  // fetch failed — leave button as-is
            const invokeBtn = panel.querySelector('[data-bolton-agent-action="invoke"]');
            const unavail = panel.querySelector('.bolton-agent-panel__unavailable');
            const headlineEl = panel.querySelector('[data-agent-unavailable-headline]');
            const bodyEl = panel.querySelector('[data-agent-unavailable-body]');
            const usable = !!health.configured && !!health.anthropic_sdk_installed;
            if (usable) return;  // green path — nothing to do, button stays enabled
            if (invokeBtn) {
                invokeBtn.disabled = true;
                invokeBtn.setAttribute('aria-disabled', 'true');
                invokeBtn.classList.add('is-disabled');
                invokeBtn.title = 'Agent fallback unavailable — configure in Settings';
            }
            if (unavail) unavail.hidden = false;
            if (headlineEl) {
                headlineEl.textContent = health.anthropic_sdk_installed
                    ? 'Agent fallback unavailable'
                    : 'Anthropic SDK missing';
            }
            if (bodyEl) {
                bodyEl.innerHTML = health.anthropic_sdk_installed
                    ? '<code>ANTHROPIC_API_KEY</code> not set in dashboard environment. Configure in Settings &rarr; AWS &amp; SSH Prerequisites.'
                    : 'The <code>anthropic</code> Python SDK is not installed in the dashboard environment. Configure in Settings &rarr; AWS &amp; SSH Prerequisites.';
            }
        });
    },

    /** task #52 — navigate from the bolt-on overlay to Settings → Prereqs.
     * Closes any open overlays first so the Settings anchor scroll lands. */
    _navigateToAgentSettings() {
        try {
            if (APP.overlay && typeof APP.overlay.closeAll === 'function') {
                APP.overlay.closeAll();
            }
            const fallback = document.getElementById('bolton-progress-fallback');
            if (fallback) fallback.remove();
            if (APP.shell && typeof APP.shell.setActiveRoute === 'function') {
                APP.shell.setActiveRoute('settings');
            } else if (typeof APP.navigateTo === 'function') {
                APP.navigateTo('settings');
            }
            setTimeout(() => {
                const target = document.getElementById('settings-prereqs');
                if (target && typeof target.scrollIntoView === 'function') {
                    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
                // Refresh the agent check now that the operator is here
                // — they may have just rotated the key.
                if (typeof loadSettingsAgentCheck === 'function') loadSettingsAgentCheck();
            }, 220);
        } catch (e) {
            // Last-ditch: location hash fallback so we don't strand the
            // operator on a broken navigation path.
            window.location.hash = '#settings-prereqs';
        }
    },

    /** Public: dispatch the agent intervention for a stuck job. */
    invokeAgent(jobId) {
        const panel = document.querySelector(`.bolton-agent-panel[data-job-id="${jobId}"]`);
        if (panel) {
            this._invokeAgent(jobId, panel);
        } else {
            this._showAgentPanel(jobId);
        }
    },

    /** Internal: POST /agent-intervene, render the returned proposal. */
    _invokeAgent(jobId, panel) {
        const invokeBtn = panel.querySelector('[data-bolton-agent-action="invoke"]');
        if (invokeBtn) {
            invokeBtn.disabled = true;
            invokeBtn.textContent = 'Diagnosing…';
        }
        fetch(`/api/bolton/jobs/${encodeURIComponent(jobId)}/agent-intervene`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({}),
        }).then(r => r.json().then(body => ({ ok: r.ok, status: r.status, body })))
        .then(({ ok, status, body }) => {
            if (!ok || !body || body.success === false) {
                const msg = (body && body.error) || `agent invocation failed (HTTP ${status})`;
                this._setProgressStatus(`[agent] ${msg}`);
                if (invokeBtn) { invokeBtn.disabled = false; invokeBtn.textContent = 'Retry invoke'; }
                return;
            }
            this._renderAgentProposal(panel, body.proposal || {});
        }).catch(err => {
            this._setProgressStatus(`[agent] ${String(err)}`);
            if (invokeBtn) { invokeBtn.disabled = false; invokeBtn.textContent = 'Retry invoke'; }
        });
    },

    _renderAgentProposal(panel, proposal) {
        panel.dataset.proposal = JSON.stringify(proposal);
        const propEl = panel.querySelector('.bolton-agent-panel__proposal');
        const diagEl = panel.querySelector('.bolton-agent-panel__diagnosis');
        const reasonEl = panel.querySelector('.bolton-agent-panel__reasoning');
        const toolsEl = panel.querySelector('.bolton-agent-panel__tool-calls');
        const approveBtn = panel.querySelector('[data-bolton-agent-action="approve"]');
        const invokeBody = panel.querySelector('.bolton-agent-panel__body');
        if (invokeBody) invokeBody.hidden = true;
        if (diagEl) diagEl.textContent = proposal.diagnosis || '(no diagnosis returned)';
        if (reasonEl) {
            const action = proposal.proposed_action || 'mark_failed';
            const detail = action === 'request_operator_input' && proposal.operator_question
                ? ` — Question: ${proposal.operator_question}`
                : '';
            reasonEl.textContent = `Proposed action: ${action}${detail}. ${proposal.reasoning || ''}`;
        }
        if (toolsEl) {
            toolsEl.innerHTML = '';
            (proposal.diagnostic_outputs || []).forEach(d => {
                const li = document.createElement('li');
                const ok = d.ok ? 'ok' : 'err';
                li.innerHTML = `<code>${d.tool}</code> [${ok}] — ${(d.command || '').slice(0, 120)}`;
                toolsEl.appendChild(li);
            });
        }
        if (approveBtn) {
            // Only enable approve when the agent actually proposed a retry.
            const canApprove = proposal.proposed_action === 'retry_with_inputs';
            approveBtn.disabled = !canApprove;
            approveBtn.title = canApprove ? '' : 'Agent did not propose a retry — nothing to approve';
        }
        if (propEl) propEl.hidden = false;
    },

    _approveAgentProposal(jobId, panel) {
        let proposal = {};
        try { proposal = JSON.parse(panel.dataset.proposal || '{}'); } catch (_) {}
        const modifications = proposal.retry_inputs || {};
        fetch(`/api/bolton/jobs/${encodeURIComponent(jobId)}/agent-approve`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ proposal_id: jobId, modifications }),
        }).then(r => r.json()).then(body => {
            if (!body || body.success === false) {
                this._setProgressStatus(`[agent] approve failed: ${body && body.error}`);
                return;
            }
            this._setProgressStatus(`[agent] retry dispatched as ${body.new_job_id}`);
            panel.remove();
            if (body.new_job_id) {
                this.state.activeJob = body.new_job_id;
                this._pollJob(body.new_job_id);
            }
        }).catch(err => this._setProgressStatus(`[agent] ${String(err)}`));
    },

    _rejectAgentProposal(jobId, panel) {
        fetch(`/api/bolton/jobs/${encodeURIComponent(jobId)}/agent-reject`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ proposal_id: jobId, reason: 'operator rejected' }),
        }).then(r => r.json()).then(() => {
            this._setProgressStatus('[agent] proposal rejected — job stays in STUCK');
            panel.remove();
        }).catch(err => this._setProgressStatus(`[agent] ${String(err)}`));
    },

    /** Open the progress overlay using Agent C's APP.overlay if available;
     * fall back to a minimal inline progress panel when it's not. */
    _openProgress(op, vulnId, host) {
        const title = `${op[0].toUpperCase() + op.slice(1)} · ${vulnId}`;
        const body = `<div id="bolton-progress-body">
            <p style="margin:0 0 12px;color:var(--text-secondary);font-size:13px">
                Dispatching <strong>${op}</strong> for <code>${vulnId}</code> on host <strong>${host}</strong>…
            </p>
            <div class="bi-log" id="bolton-progress-log" role="log" aria-live="polite"></div>
        </div>`;
        if (APP.overlay && typeof APP.overlay.open === 'function') {
            // Agent C signature: open(id, content, opts)
            APP.overlay.open('bolton-progress', body, { title, eyebrow: 'Bolt-on operation' });
            return;
        }
        // Fallback: append a lightweight scrim takeover to the document body.
        let host_el = document.getElementById('bolton-progress-fallback');
        if (!host_el) {
            host_el = document.createElement('div');
            host_el.id = 'bolton-progress-fallback';
            host_el.innerHTML = `
                <div class="scrim-takeover" data-open="true"></div>
                <div class="takeover-card bi-card" data-open="true" role="dialog" aria-modal="true">
                    <div class="bi-card__head">
                        <div class="bi-card__head-row">
                            <div>
                                <div class="bi-card__eyebrow">Bolt-on operation</div>
                                <h3 class="bi-card__title" id="bolton-progress-title">${title}</h3>
                            </div>
                            <button class="bi-card__close" type="button" id="bolton-progress-close" aria-label="Close">✕</button>
                        </div>
                    </div>
                    <div class="bi-card__body">${body}</div>
                </div>`;
            document.body.appendChild(host_el);
            const close = document.getElementById('bolton-progress-close');
            if (close) close.addEventListener('click', () => host_el.remove());
        } else {
            const t = document.getElementById('bolton-progress-title');
            if (t) t.textContent = title;
            const bb = document.getElementById('bolton-progress-body');
            if (bb) bb.outerHTML = body;
        }
    },

    _setProgressStatus(msg) {
        const log = document.getElementById('bolton-progress-log');
        if (!log) return;
        const line = document.createElement('div');
        line.className = 'bi-log__line';
        line.textContent = msg;
        log.appendChild(line);
    },

    _pollJob(jobId, attempts = 0) {
        if (!jobId || attempts > 60) return;
        fetch(`/api/bolton/jobs/${encodeURIComponent(jobId)}`)
            .then(r => r.json())
            .then(payload => {
                if (!payload || payload.success === false) {
                    this._setProgressStatus(payload && payload.error || 'job query failed');
                    return;
                }
                const status = String(payload.status || '').toUpperCase();
                this._setProgressStatus(`[${status}] ${payload.log_tail ? payload.log_tail.slice(-200) : ''}`);
                if (['SUCCEEDED', 'FAILED', 'STUCK', 'AS_PATCHED_BUT_VULN'].includes(status)) {
                    // Phase 3a — stuck jobs get the agent invocation panel.
                    if (status === 'STUCK') {
                        try { this._showAgentPanel(jobId); } catch (_) { /* noop */ }
                    }
                    if (this.state.host && this.state.lab) {
                        this.selectHost(this.state.lab, this.state.host);
                    }
                    return;
                }
                setTimeout(() => this._pollJob(jobId, attempts + 1), 1000);
            })
            .catch(() => setTimeout(() => this._pollJob(jobId, attempts + 1), 2000));
    },
};

if (typeof window !== 'undefined') {
    window.APP = window.APP || APP;
}

// === end v3 PALETTE (Agent B) =============================================

// ============================================================================
// v3 OVERLAY STACK (Agent C, 2026-05-18) — Dashboard-widget-as-OS overlays
// ============================================================================
//
// APP.overlay is the dashboard-overlay machinery. Dashboard widgets open as
// stacked, scrim-backed takeovers WITHOUT leaving the page (per the project
// scaffold memory: "Widget clicks on the Dashboard → overlays (not
// navigation)"). The overlay stack is separate from APP.modal (which keeps
// owning singleton modals like architecture / version / session-logs) and
// from APP.journey (Phase 2b's New Deployment takeover, also unchanged).
//
// Layering rules:
//   - First open: dashboard content blurs + dims (body[data-overlay-depth="1"]).
//   - Subsequent opens stack with +10 z-index each, increasing blur.
//   - After 3 layers deep, the topmost overlay surfaces a prominent
//     "Promote to full page" CTA (the z-index salad becomes unpleasant).
//   - Escape closes one layer at a time; scrim click closes the topmost.
//
// API surface:
//   APP.overlay.open(id, content, {title, eyebrow, promoteHref, wide,
//                                  promoteLabel}) → handle (with .update())
//   APP.overlay.close(id)        — close a specific overlay by id
//   APP.overlay.closeTop()       — close the topmost overlay
//   APP.overlay.closeAll()       — unwind the whole stack
//   APP.overlay.isOpen(id)       — bool: is this overlay on the stack?
//   APP.overlay.promote(id)      — close + navigate via APP.shell
//
// Dashboard widget content renderers live below as renderOverlay_<kind>()
// helpers. They return DocumentFragment / HTMLElement / HTML string and
// pull from the existing API endpoints (no new backend code).
// ============================================================================

(function () {
    'use strict';

    if (!window.APP) window.APP = {};

    // Z-index baseline. Phase 2b's --z-takeover is 200 (for journey + modal).
    // APP.overlay sits ABOVE the journey when both are open. Baseline 1000
    // puts us comfortably above palette (Agent B, ~900) + existing modals.
    const Z_BASE = 1000;
    const Z_STEP = 10;
    const PROMOTE_THRESHOLD = 3;   // after 3 layers, surface promote CTA prominently

    // --- DOM helpers -------------------------------------------------------

    function _root() {
        let root = document.getElementById('app-overlay-root');
        if (!root) {
            // Defensive create — the body-level mount slot should always be
            // present (it lives in index.html) but in test harnesses that
            // dynamically replace the body we re-create it.
            root = document.createElement('div');
            root.id = 'app-overlay-root';
            document.body.appendChild(root);
        }
        return root;
    }

    function _setBodyDepth(n) {
        if (n <= 0) {
            document.body.removeAttribute('data-overlay-depth');
        } else {
            document.body.setAttribute('data-overlay-depth', String(n));
        }
    }

    function _focusableIn(el) {
        if (!el) return null;
        return el.querySelector(
            'button:not([disabled]), [href], input:not([disabled]), ' +
            'select:not([disabled]), textarea:not([disabled]), ' +
            '[tabindex]:not([tabindex="-1"])'
        );
    }

    // --- Overlay stack -----------------------------------------------------

    const APP_overlay = {
        _stack: [],   // [{id, element, scrim, card, previousFocus, options}]

        open(id, content, opts) {
            opts = opts || {};
            if (this.isOpen(id)) {
                const existing = this._stack.find(o => o.id === id);
                if (existing && existing.body) _renderContent(existing.body, content);
                return _handle(this, existing);
            }

            const depth = this._stack.length + 1;
            const zIndex = Z_BASE + (depth - 1) * Z_STEP;

            const overlayEl = document.createElement('div');
            overlayEl.className = 'app-overlay';
            overlayEl.setAttribute('data-overlay-id', id);
            overlayEl.setAttribute('data-overlay-depth', String(depth));
            overlayEl.style.zIndex = String(zIndex);

            const scrim = document.createElement('div');
            scrim.className = 'app-overlay__scrim';
            scrim.setAttribute('data-overlay-scrim', '');
            scrim.style.zIndex = String(zIndex);

            const card = document.createElement('div');
            card.className = 'app-overlay__card' + (opts.wide ? ' app-overlay__card--wide' : '');
            card.setAttribute('role', 'dialog');
            card.setAttribute('aria-modal', 'true');
            card.setAttribute('aria-labelledby', `overlay-title-${_safeIdSuffix(id)}`);
            card.style.zIndex = String(zIndex + 1);

            // Header.
            const header = document.createElement('header');
            header.className = 'app-overlay__header';
            const headLeft = document.createElement('div');
            headLeft.className = 'app-overlay__header-text';
            if (opts.eyebrow) {
                const eyebrow = document.createElement('span');
                eyebrow.className = 'app-overlay__eyebrow';
                eyebrow.textContent = opts.eyebrow;
                headLeft.appendChild(eyebrow);
            }
            const title = document.createElement('h2');
            title.id = `overlay-title-${_safeIdSuffix(id)}`;
            title.className = 'app-overlay__title';
            title.textContent = opts.title || id;
            headLeft.appendChild(title);
            header.appendChild(headLeft);

            const headRight = document.createElement('div');
            headRight.className = 'app-overlay__header-actions';
            if (opts.promoteHref) {
                const promoteBtn = document.createElement('button');
                promoteBtn.type = 'button';
                promoteBtn.className = 'app-overlay__promote';
                promoteBtn.setAttribute('data-v3-overlay-promote', '');
                promoteBtn.textContent = opts.promoteLabel || 'Open in full page →';
                promoteBtn.addEventListener('click', () => { APP_overlay.promote(id); });
                if (depth >= PROMOTE_THRESHOLD) {
                    promoteBtn.classList.add('app-overlay__promote--prominent');
                    promoteBtn.title = 'Stack is getting deep — full-page recommended.';
                }
                headRight.appendChild(promoteBtn);
            }
            const closeBtn = document.createElement('button');
            closeBtn.type = 'button';
            closeBtn.className = 'app-overlay__close';
            closeBtn.setAttribute('aria-label', 'Close overlay');
            closeBtn.innerHTML = '&times;';
            closeBtn.addEventListener('click', () => APP_overlay.close(id));
            headRight.appendChild(closeBtn);
            header.appendChild(headRight);

            const body = document.createElement('div');
            body.className = 'app-overlay__body';
            _renderContent(body, content);

            card.appendChild(header);
            card.appendChild(body);
            overlayEl.appendChild(scrim);
            overlayEl.appendChild(card);

            _root().appendChild(overlayEl);

            const entry = {
                id, element: overlayEl, scrim, card, body, header,
                options: opts, previousFocus: document.activeElement,
            };
            this._stack.push(entry);
            _setBodyDepth(this._stack.length);

            if (depth >= PROMOTE_THRESHOLD && opts.promoteHref) {
                console.warn(`[APP.overlay] Stack is ${depth} deep for "${id}" — surfacing promote CTA prominently. Consider full-page navigation.`);
            }

            scrim.addEventListener('click', () => {
                if (APP_overlay._stack.length > 0 &&
                    APP_overlay._stack[APP_overlay._stack.length - 1].id === id) {
                    APP_overlay.close(id);
                }
            });

            requestAnimationFrame(() => { overlayEl.classList.add('is-open'); });

            setTimeout(() => {
                const focusable = _focusableIn(body) || closeBtn;
                if (focusable) try { focusable.focus(); } catch (_) { /* ignore */ }
            }, 50);

            return _handle(this, entry);
        },

        close(id) {
            const idx = this._stack.findIndex(o => o.id === id);
            if (idx === -1) return;
            const entry = this._stack[idx];
            if (entry.options && typeof entry.options.onClose === 'function') {
                try { entry.options.onClose(entry); } catch (e) { console.warn('overlay onClose threw:', e); }
            }
            entry.element.classList.remove('is-open');
            entry.element.classList.add('is-closing');
            this._stack.splice(idx, 1);
            _setBodyDepth(this._stack.length);

            setTimeout(() => {
                if (entry.element && entry.element.parentNode) {
                    entry.element.parentNode.removeChild(entry.element);
                }
            }, 220);

            if (this._stack.length > 0) {
                const top = this._stack[this._stack.length - 1];
                const f = _focusableIn(top.body);
                if (f) try { f.focus(); } catch (_) { /* ignore */ }
            } else if (entry.previousFocus && typeof entry.previousFocus.focus === 'function') {
                try { entry.previousFocus.focus(); } catch (_) { /* ignore */ }
            }
        },

        closeTop() {
            if (this._stack.length === 0) return;
            const top = this._stack[this._stack.length - 1];
            this.close(top.id);
        },

        closeAll() {
            const ids = this._stack.slice().reverse().map(o => o.id);
            ids.forEach(id => this.close(id));
        },

        isOpen(id) {
            return this._stack.some(o => o.id === id);
        },

        promote(id) {
            const entry = this._stack.find(o => o.id === id);
            if (!entry) return;
            const href = entry.options && entry.options.promoteHref;
            this.close(id);
            if (!href) return;
            // promoteHref is one of:
            //   'beacons'                    → APP.navigateTo('beacons')
            //   {parent: 'X', subPill: 'Y'}  → APP.navigateTo(parent, subPill)
            //   '/some-url' or '#anchor'     → location.href = ...
            if (typeof href === 'object' && href.parent) {
                if (APP.navigateTo) APP.navigateTo(href.parent, href.subPill || undefined);
            } else if (typeof href === 'string' && href.indexOf('://') === -1 && href.indexOf('/') === -1 && href.charAt(0) !== '#') {
                if (APP.navigateTo) APP.navigateTo(href);
            } else if (typeof href === 'string') {
                location.href = href;
            }
        },
    };

    APP.overlay = APP_overlay;

    function _renderContent(host, content) {
        while (host.firstChild) host.removeChild(host.firstChild);
        if (content == null) return;
        if (typeof content === 'string') {
            host.innerHTML = content;
        } else if (content instanceof Node) {
            host.appendChild(content);
        } else if (typeof content === 'object' && typeof content.toString === 'function') {
            host.innerHTML = String(content);
        }
    }

    function _safeIdSuffix(id) {
        return String(id).replace(/[^a-z0-9_-]/gi, '-');
    }

    function _handle(overlay, entry) {
        return {
            id: entry.id,
            update(newContent) {
                if (entry.body) _renderContent(entry.body, newContent);
            },
            close() { overlay.close(entry.id); },
        };
    }

    // --- Global Escape handler — pops one layer at a time -----------------

    document.addEventListener('keydown', function (e) {
        if (e.key !== 'Escape') return;
        if (APP_overlay._stack.length === 0) return;
        const top = APP_overlay._stack[APP_overlay._stack.length - 1];
        const dirtyForm = top.body && top.body.querySelector('form[data-overlay-dirty="true"]');
        if (dirtyForm) {
            if (!window.confirm('Discard unsaved changes?')) return;
        }
        e.preventDefault();
        e.stopPropagation();
        APP_overlay.closeTop();
    }, true);

    // ====================================================================
    // === Dashboard widget content renderers + click conversion ==========
    // ====================================================================

    const _esc = (typeof escapeHtml === 'function') ? escapeHtml : (s => String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;'));

    function _emptyHost(message) {
        const wrap = document.createElement('div');
        wrap.className = 'app-overlay__empty';
        wrap.innerHTML = `<p class="t-muted" style="margin: 0;">${_esc(message)}</p>`;
        return wrap;
    }

    function _loadingHost(message) {
        const wrap = document.createElement('div');
        wrap.className = 'app-overlay__loading';
        wrap.innerHTML = `<p class="t-muted" style="margin: 0;">${_esc(message || 'Loading…')}</p>`;
        return wrap;
    }

    // ── 1. Active Beacons overlay ──────────────────────────────────────
    async function renderOverlay_Beacons() {
        const host = document.createElement('div');
        host.appendChild(_loadingHost('Loading beacons…'));
        try {
            let beacons = [];
            if (typeof BEACON !== 'undefined' && Array.isArray(BEACON.cachedBeacons) && BEACON.cachedBeacons.length > 0) {
                beacons = BEACON.cachedBeacons.slice();
            } else {
                try {
                    const res = await fetch('/api/beacon');
                    if (res.ok) {
                        const data = await res.json();
                        beacons = Array.isArray(data) ? data : (data.beacons || data.data || []);
                    }
                } catch (e) { /* fall through to empty */ }
            }
            while (host.firstChild) host.removeChild(host.firstChild);
            if (!beacons || beacons.length === 0) {
                host.appendChild(_emptyHost('No active beacons. They appear here as soon as a target calls back.'));
                return host;
            }
            const list = document.createElement('dl');
            list.className = 'spec-list app-overlay__beacons-list';
            list.innerHTML = beacons.map(b => {
                const bid = b.id || b.beacon_id || b.uid || '';
                const hostName = b.computer || b.hostname || b.host || '—';
                const user = b.user || b.username || '—';
                const proc = b.process || b.proc || b.pname || '—';
                const last = b.last || b.last_checkin || b.lastSeen || '';
                const owner = b.driven_by || b.operator || b.owner || '';
                let ownerHtml = '';
                if (owner && APP.operator && Array.isArray(APP.operator.all)) {
                    const op = APP.operator.all.find(o => o.id === owner || o.display === owner);
                    const color = (op && op.color) || '#7A849E';
                    ownerHtml = `<span class="operator-dot operator-dot--sm" style="background: ${_esc(color)}" aria-hidden="true"></span><span class="t-muted" style="margin-left: 4px; font-size: 11px;">${_esc(owner)}</span>`;
                }
                return `
                    <div class="spec-row" data-readonly="true" data-v3-beacon-row="${_esc(bid)}" role="button" tabindex="0">
                        <div class="spec-row__head">
                            <span class="spec-row__key">${_esc(hostName)}</span>
                            <span class="spec-row__value">
                                ${_esc(user)} · ${_esc(proc)}
                                ${ownerHtml ? '<span style="margin-left: 12px;">' + ownerHtml + '</span>' : ''}
                            </span>
                            <span class="spec-row__hint">
                                <span class="spec-pill spec-pill--live"><span class="spec-pill__dot"></span>${_esc(last || 'live')}</span>
                            </span>
                        </div>
                    </div>
                `;
            }).join('');
            host.appendChild(list);

            list.addEventListener('click', (e) => {
                const row = e.target.closest('[data-v3-beacon-row]');
                if (!row) return;
                const bid = row.getAttribute('data-v3-beacon-row');
                APP.overlay.open(
                    'beacon-detail:' + bid,
                    _renderBeaconDetailContent(bid, beacons.find(b => (b.id || b.beacon_id || b.uid) === bid)),
                    {
                        eyebrow: 'Beacon',
                        title: bid || 'Beacon detail',
                        promoteHref: { parent: 'operations-tab', subPill: 'beacons' },
                        promoteLabel: 'Open in Beacons →',
                    }
                );
            });
            list.addEventListener('keydown', (e) => {
                if (e.key !== 'Enter' && e.key !== ' ') return;
                const row = e.target.closest('[data-v3-beacon-row]');
                if (!row) return;
                e.preventDefault();
                row.click();
            });
            return host;
        } catch (e) {
            console.warn('renderOverlay_Beacons failed:', e);
            while (host.firstChild) host.removeChild(host.firstChild);
            host.appendChild(_emptyHost('Unable to load beacons.'));
            return host;
        }
    }

    function _renderBeaconDetailContent(bid, beacon) {
        const wrap = document.createElement('div');
        if (!beacon) {
            wrap.innerHTML = `<p class="t-muted">No detail available for beacon ${_esc(bid)}.</p>`;
            return wrap;
        }
        const rows = [
            ['Host', beacon.computer || beacon.hostname || beacon.host || '—'],
            ['User', beacon.user || beacon.username || '—'],
            ['Process', beacon.process || beacon.proc || beacon.pname || '—'],
            ['PID', beacon.pid || '—'],
            ['Architecture', beacon.arch || beacon.architecture || '—'],
            ['Internal IP', beacon.internal || beacon.internal_ip || beacon.ip || '—'],
            ['External IP', beacon.external || beacon.external_ip || '—'],
            ['Last Seen', beacon.last || beacon.last_checkin || beacon.lastSeen || '—'],
            ['Sleep', beacon.sleep != null ? String(beacon.sleep) + 's' : '—'],
            ['Driven by', beacon.driven_by || beacon.operator || beacon.owner || '—'],
        ];
        wrap.innerHTML = `<dl class="spec-list">${rows.map(([k, v]) => `
            <div class="spec-row" data-readonly="true">
                <div class="spec-row__head">
                    <span class="spec-row__key">${_esc(k)}</span>
                    <span class="spec-row__value">${_esc(v)}</span>
                </div>
            </div>
        `).join('')}</dl>`;
        return wrap;
    }

    // ── 2. Recent Activity overlay (full audit log) ───────────────────
    async function renderOverlay_Activity() {
        const host = document.createElement('div');
        host.appendChild(_loadingHost('Loading audit log…'));
        try {
            const res = await fetch('/api/audit?limit=200');
            const data = await res.json();
            const entries = (data && data.entries) || [];
            while (host.firstChild) host.removeChild(host.firstChild);

            const filterBar = document.createElement('div');
            filterBar.className = 'app-overlay__filter-bar';
            filterBar.innerHTML = `
                <input type="search"
                       class="app-overlay__filter-search"
                       placeholder="Filter by operator, action, or target…"
                       data-v3-audit-search
                       aria-label="Filter audit log">
                <button type="button" class="app-overlay__filter-export" data-v3-audit-export>Export CSV</button>
            `;
            host.appendChild(filterBar);

            if (entries.length === 0) {
                host.appendChild(_emptyHost('No activity in the audit log yet.'));
                return host;
            }

            const list = document.createElement('ul');
            list.className = 'spec-list app-overlay__activity-list';
            list.setAttribute('data-v3-audit-list', '');
            list.innerHTML = entries.map(e => (typeof _renderActivityRow === 'function')
                ? _renderActivityRow(e)
                : _fallbackActivityRow(e)).join('');
            host.appendChild(list);

            const search = filterBar.querySelector('[data-v3-audit-search]');
            search.addEventListener('input', () => {
                const q = search.value.toLowerCase();
                Array.from(list.children).forEach(li => {
                    const text = li.textContent.toLowerCase();
                    li.style.display = text.indexOf(q) === -1 ? 'none' : '';
                });
            });
            const exportBtn = filterBar.querySelector('[data-v3-audit-export]');
            exportBtn.addEventListener('click', () => _exportAuditCsv(entries));

            return host;
        } catch (e) {
            console.warn('renderOverlay_Activity failed:', e);
            while (host.firstChild) host.removeChild(host.firstChild);
            host.appendChild(_emptyHost('Unable to load audit log.'));
            return host;
        }
    }

    function _fallbackActivityRow(e) {
        return `<li class="spec-row" data-readonly="true">
            <div class="spec-row__head">
                <span class="spec-row__key">${_esc(e.op || '?')}</span>
                <span class="spec-row__value">${_esc(e.action || '')} ${_esc(e.project || e.target || '')}</span>
                <span class="spec-row__hint">${_esc(e.ts || '')}</span>
            </div>
        </li>`;
    }

    function _exportAuditCsv(entries) {
        const header = ['ts', 'op', 'action', 'project', 'target'];
        const lines = [header.join(',')];
        entries.forEach(e => {
            lines.push(header.map(k => {
                const v = String(e[k] == null ? '' : e[k]).replace(/"/g, '""');
                return /[,"\n]/.test(v) ? `"${v}"` : v;
            }).join(','));
        });
        const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit-${new Date().toISOString().slice(0, 10)}.csv`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    // ── 3. Per-deployment Manage overlay ──────────────────────────────
    async function renderOverlay_Deployment(name) {
        const host = document.createElement('div');
        host.appendChild(_loadingHost('Loading deployment…'));
        try {
            const res = await fetch(`/api/deploy/status?project=${encodeURIComponent(name)}`);
            const data = await res.json();
            const status = (data && data.status) || {};
            while (host.firstChild) host.removeChild(host.firstChild);

            const rows = [
                ['Project', name],
                ['Deployment Type', status.deployment_type || '—'],
                ['Status', status.status || status.state || '—'],
                ['Region', status.region || '—'],
                ['Instances', status.instance_count != null ? String(status.instance_count) : '—'],
                ['Created', status.created_at || status.created || '—'],
                ['Last touched by', status.last_modified_by || status.owner || status.operator || '—'],
                ['Last touched', status.last_modified_at || status.modified_at || '—'],
            ];
            const list = document.createElement('dl');
            list.className = 'spec-list';
            list.innerHTML = rows.map(([k, v]) => `
                <div class="spec-row" data-readonly="true">
                    <div class="spec-row__head">
                        <span class="spec-row__key">${_esc(k)}</span>
                        <span class="spec-row__value">${_esc(v)}</span>
                    </div>
                </div>
            `).join('');
            host.appendChild(list);

            const actions = document.createElement('div');
            actions.className = 'app-overlay__footer-actions';
            actions.innerHTML = `
                <button type="button" class="btn btn-secondary btn-sm" data-v3-set-active="${_esc(name)}">Set as active</button>
                <button type="button" class="btn btn-primary btn-sm" data-v3-open-manage="${_esc(name)}">Open Manage page →</button>
            `;
            host.appendChild(actions);

            actions.addEventListener('click', (e) => {
                const setBtn = e.target.closest('[data-v3-set-active]');
                const openBtn = e.target.closest('[data-v3-open-manage]');
                if (setBtn && APP.activeDeployment) {
                    APP.activeDeployment.set(setBtn.getAttribute('data-v3-set-active'));
                    if (APP.toast) APP.toast('Active deployment switched', 'info');
                }
                if (openBtn) {
                    APP.overlay.close('deployment:' + openBtn.getAttribute('data-v3-open-manage'));
                    if (APP.activeDeployment) APP.activeDeployment.set(openBtn.getAttribute('data-v3-open-manage'));
                    if (APP.navigateTo) APP.navigateTo('deployments-tab', 'manage');
                }
            });

            return host;
        } catch (e) {
            console.warn('renderOverlay_Deployment failed:', e);
            while (host.firstChild) host.removeChild(host.firstChild);
            host.appendChild(_emptyHost('Unable to load deployment metadata.'));
            return host;
        }
    }

    // ── 4. Cost Tracker overlay ───────────────────────────────────────
    async function renderOverlay_Cost() {
        const host = document.createElement('div');
        host.appendChild(_loadingHost('Loading cost data…'));
        try {
            const [summaryRes, projRes, settingsRes] = await Promise.all([
                fetch('/api/costs/summary').catch(() => null),
                fetch('/api/costs/projects').catch(() => null),
                fetch('/api/costs/settings').catch(() => null),
            ]);
            const summary = (summaryRes && summaryRes.ok) ? await summaryRes.json() : {};
            const projects = (projRes && projRes.ok) ? await projRes.json() : { projects: [] };
            const settings = (settingsRes && settingsRes.ok) ? await settingsRes.json() : {};

            while (host.firstChild) host.removeChild(host.firstChild);

            const hero = document.createElement('div');
            hero.className = 'app-overlay__cost-hero';
            const total = (summary && (summary.monthly_total || summary.total)) || 0;
            const budget = (settings && settings.monthly_budget) || 0;
            hero.innerHTML = `
                <div class="app-overlay__cost-hero-num">$${_esc(Math.round(total))}<span class="app-overlay__cost-hero-unit">/mo</span></div>
                <div class="app-overlay__cost-hero-sub">${budget ? 'Budget: $' + _esc(budget) + '/mo' : 'No budget set'}</div>
            `;
            host.appendChild(hero);

            const projects_list = (projects && projects.projects) || [];
            if (projects_list.length > 0) {
                const list = document.createElement('dl');
                list.className = 'spec-list';
                list.innerHTML = projects_list.map(p => `
                    <div class="spec-row" data-readonly="true">
                        <div class="spec-row__head">
                            <span class="spec-row__key">${_esc(p.project || p.name || '—')}</span>
                            <span class="spec-row__value">${_esc(p.instance_count || 0)} instances</span>
                            <span class="spec-row__hint">$${_esc(Math.round(p.monthly_cost || p.cost || 0))}/mo</span>
                        </div>
                    </div>
                `).join('');
                host.appendChild(list);
            } else {
                host.appendChild(_emptyHost('No per-project cost data yet.'));
            }

            const footer = document.createElement('div');
            footer.className = 'app-overlay__footer-actions';
            footer.innerHTML = `
                <label class="t-muted" style="font-size: 11.5px;">Monthly budget
                    <input type="number" min="0" step="10" value="${_esc(budget || 0)}" data-v3-cost-budget style="width: 100px; margin-left: 8px; padding: 4px 8px;">
                </label>
                <button type="button" class="btn btn-primary btn-sm" data-v3-cost-save>Save budget</button>
            `;
            host.appendChild(footer);

            footer.addEventListener('click', async (e) => {
                if (!e.target.closest('[data-v3-cost-save]')) return;
                const input = footer.querySelector('[data-v3-cost-budget]');
                const value = parseFloat(input.value);
                try {
                    await fetch('/api/costs/settings', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ monthly_budget: value }),
                    });
                    if (APP.toast) APP.toast('Budget saved', 'success');
                } catch (err) {
                    if (APP.toast) APP.toast('Failed to save budget', 'error');
                }
            });

            return host;
        } catch (e) {
            console.warn('renderOverlay_Cost failed:', e);
            while (host.firstChild) host.removeChild(host.firstChild);
            host.appendChild(_emptyHost('Unable to load cost data.'));
            return host;
        }
    }

    // ── 5. Failed Deployments overlay ─────────────────────────────────
    async function renderOverlay_Failed() {
        const host = document.createElement('div');
        host.appendChild(_loadingHost('Loading failed deployments…'));
        try {
            const res = await fetch('/api/deploy/active');
            const data = await res.json();
            const failed = ((data && data.deployments) || []).filter(d => d.status === 'error' || d.status === 'failed');
            while (host.firstChild) host.removeChild(host.firstChild);
            if (failed.length === 0) {
                host.appendChild(_emptyHost('No failed deployments.'));
                return host;
            }
            const list = document.createElement('dl');
            list.className = 'spec-list';
            list.innerHTML = failed.map(d => {
                const name = d._filename || d.project_name || 'unknown';
                return `
                    <div class="spec-row" data-readonly="true">
                        <div class="spec-row__head">
                            <span class="spec-row__key">${_esc(name)}</span>
                            <span class="spec-row__value">${_esc(d.deployment_type || '—')}</span>
                            <span class="spec-row__hint">
                                <button type="button" class="btn btn-secondary btn-sm" data-v3-retry="${_esc(name)}">Retry</button>
                                <button type="button" class="btn btn-danger btn-sm" data-v3-destroy="${_esc(name)}">Destroy</button>
                            </span>
                        </div>
                    </div>
                `;
            }).join('');
            host.appendChild(list);

            list.addEventListener('click', (e) => {
                const retry = e.target.closest('[data-v3-retry]');
                const destroy = e.target.closest('[data-v3-destroy]');
                if (retry) {
                    const name = retry.getAttribute('data-v3-retry');
                    APP.overlay.close('failed-deployments');
                    if (APP.activeDeployment) APP.activeDeployment.set(name);
                    if (APP.navigateTo) APP.navigateTo('deployments-tab', 'deploy');
                }
                if (destroy) {
                    const name = destroy.getAttribute('data-v3-destroy');
                    APP.overlay.close('failed-deployments');
                    if (APP.activeDeployment) APP.activeDeployment.set(name);
                    if (APP.navigateTo) APP.navigateTo('deployments-tab', 'cleanup');
                }
            });
            return host;
        } catch (e) {
            console.warn('renderOverlay_Failed failed:', e);
            while (host.firstChild) host.removeChild(host.firstChild);
            host.appendChild(_emptyHost('Unable to load deployments.'));
            return host;
        }
    }

    // ── 6. AWS Prereqs checker overlay ────────────────────────────────
    async function renderOverlay_Prereqs() {
        const host = document.createElement('div');
        host.appendChild(_loadingHost('Running prerequisite checks…'));
        try {
            const [credsRes, sshRes, permsRes] = await Promise.all([
                fetch('/api/aws/credentials').catch(() => null),
                fetch('/api/aws/ssh-key').catch(() => null),
                fetch('/api/aws/permissions').catch(() => null),
            ]);
            const creds = (credsRes && credsRes.ok) ? await credsRes.json() : { success: false };
            const ssh = (sshRes && sshRes.ok) ? await sshRes.json() : { success: false };
            const perms = (permsRes && permsRes.ok) ? await permsRes.json() : { success: false };

            while (host.firstChild) host.removeChild(host.firstChild);

            function _pill(ok) {
                return ok
                    ? `<span class="spec-pill spec-pill--live"><span class="spec-pill__dot"></span>OK</span>`
                    : `<span class="spec-pill spec-pill--error"><span class="spec-pill__dot"></span>FAIL</span>`;
            }
            const rows = [
                ['AWS Credentials', creds.success === true || creds.ok === true, creds.identity || creds.error || ''],
                ['SSH Key', ssh.success === true || ssh.ok === true, ssh.path || ssh.error || ''],
                ['IAM Permissions', perms.success === true || perms.ok === true, perms.message || perms.error || ''],
            ];
            const list = document.createElement('dl');
            list.className = 'spec-list';
            list.innerHTML = rows.map(([k, ok, detail]) => `
                <div class="spec-row" data-readonly="true">
                    <div class="spec-row__head">
                        <span class="spec-row__key">${_esc(k)}</span>
                        <span class="spec-row__value">${_esc(detail)}</span>
                        <span class="spec-row__hint">${_pill(ok)}</span>
                    </div>
                </div>
            `).join('');
            host.appendChild(list);

            const allOk = rows.every(r => r[1]);
            if (allOk) {
                try { localStorage.setItem('prereqs-verified-at', String(Date.now())); } catch (_) { /* ignore */ }
                if (typeof _refreshPrereqsBanner === 'function') _refreshPrereqsBanner();
            }

            const footer = document.createElement('div');
            footer.className = 'app-overlay__footer-actions';
            footer.innerHTML = `<button type="button" class="btn btn-secondary btn-sm" data-v3-prereqs-rerun>Re-run checks</button>`;
            host.appendChild(footer);

            footer.addEventListener('click', async (e) => {
                if (!e.target.closest('[data-v3-prereqs-rerun]')) return;
                const handle = APP.overlay._stack.find(o => o.id === 'prereqs');
                if (handle) _renderContent(handle.body, _loadingHost('Re-running prereq checks…'));
                const next = await renderOverlay_Prereqs();
                if (handle) _renderContent(handle.body, next);
            });

            return host;
        } catch (e) {
            console.warn('renderOverlay_Prereqs failed:', e);
            while (host.firstChild) host.removeChild(host.firstChild);
            host.appendChild(_emptyHost('Unable to run prerequisite checks.'));
            return host;
        }
    }

    // ── 8. Elastic Detection Rules browser overlay ───────────────────
    function renderOverlay_Elastic() {
        const host = document.createElement('div');
        if (typeof ELASTIC_RULES === 'undefined' || !ELASTIC_RULES) {
            host.appendChild(_emptyHost('Elastic rules not loaded. Run "Update Rules" to fetch them.'));
            return host;
        }

        const allRules = [];
        const commands = ELASTIC_RULES.commands || {};
        Object.keys(commands).forEach(cmd => {
            (commands[cmd] || []).forEach(rule => {
                allRules.push({ ...rule, command: cmd });
            });
        });
        if (allRules.length === 0) {
            host.appendChild(_emptyHost('No rules in the index.'));
            return host;
        }

        const filter = document.createElement('div');
        filter.className = 'app-overlay__filter-bar';
        filter.innerHTML = `
            <input type="search"
                   class="app-overlay__filter-search"
                   placeholder="Filter ${allRules.length} rules…"
                   data-v3-rule-search
                   aria-label="Filter detection rules">
        `;
        host.appendChild(filter);

        const list = document.createElement('dl');
        list.className = 'spec-list app-overlay__rules-list';
        list.innerHTML = allRules.slice(0, 100).map(r => `
            <div class="spec-row" data-readonly="true" data-v3-rule-search-text="${_esc((r.name + ' ' + (r.command || '') + ' ' + (r.mitre_technique || '') + ' ' + (r.mitre_technique_name || '')).toLowerCase())}">
                <div class="spec-row__head">
                    <span class="spec-row__key">${_esc(r.name || 'unnamed')}</span>
                    <span class="spec-row__value">
                        <span class="t-muted" style="font-size: 11px;">${_esc(r.command || '')}</span>
                        ${r.mitre_technique ? ' · <code>' + _esc(r.mitre_technique) + '</code>' : ''}
                    </span>
                    <span class="spec-row__hint">
                        <span class="spec-pill spec-pill--${r.severity === 'critical' ? 'error' : (r.severity === 'high' ? 'error' : 'draft')}"><span class="spec-pill__dot"></span>${_esc(r.severity || '?')}</span>
                    </span>
                </div>
            </div>
        `).join('');
        host.appendChild(list);

        const search = filter.querySelector('[data-v3-rule-search]');
        search.addEventListener('input', () => {
            const q = search.value.toLowerCase();
            Array.from(list.children).forEach(li => {
                const text = li.getAttribute('data-v3-rule-search-text') || '';
                li.style.display = text.indexOf(q) === -1 ? 'none' : '';
            });
        });

        if (allRules.length > 100) {
            const more = document.createElement('p');
            more.className = 't-muted';
            more.style.cssText = 'margin: 12px 0 0; font-size: 11px;';
            more.textContent = `Showing first 100 of ${allRules.length}. Filter to narrow down.`;
            host.appendChild(more);
        }
        return host;
    }

    // ── Public openers — used by the click delegation below + callers ──
    APP.overlay.openBeacons = function () {
        const handle = APP.overlay.open('beacons', _loadingHost('Loading beacons…'), {
            eyebrow: 'Operations',
            title: 'Active Beacons',
            promoteHref: { parent: 'operations-tab', subPill: 'beacons' },
            promoteLabel: 'Open in Beacons →',
            wide: true,
        });
        renderOverlay_Beacons().then(node => handle.update(node));
        return handle;
    };
    APP.overlay.openActivity = function () {
        const handle = APP.overlay.open('activity', _loadingHost('Loading audit log…'), {
            eyebrow: 'Audit',
            title: 'Recent Activity',
            wide: true,
        });
        renderOverlay_Activity().then(node => handle.update(node));
        return handle;
    };
    APP.overlay.openDeployment = function (name) {
        const handle = APP.overlay.open('deployment:' + name, _loadingHost('Loading…'), {
            eyebrow: 'Deployment',
            title: name,
            promoteHref: { parent: 'deployments-tab', subPill: 'manage' },
            promoteLabel: 'Open in Manage →',
        });
        renderOverlay_Deployment(name).then(node => handle.update(node));
        return handle;
    };
    APP.overlay.openCost = function () {
        const handle = APP.overlay.open('cost', _loadingHost('Loading cost data…'), {
            eyebrow: 'Cost',
            title: 'Cost Tracker',
            promoteHref: 'settings',
            promoteLabel: 'Open in Settings →',
            wide: true,
        });
        renderOverlay_Cost().then(node => handle.update(node));
        return handle;
    };
    APP.overlay.openFailed = function () {
        const handle = APP.overlay.open('failed-deployments', _loadingHost('Loading…'), {
            eyebrow: 'Deployments',
            title: 'Failed Deployments',
            promoteHref: { parent: 'deployments-tab', subPill: 'manage' },
            promoteLabel: 'Open in Manage →',
        });
        renderOverlay_Failed().then(node => handle.update(node));
        return handle;
    };
    APP.overlay.openPrereqs = function () {
        const handle = APP.overlay.open('prereqs', _loadingHost('Running prereqs…'), {
            eyebrow: 'Setup',
            title: 'AWS & SSH Prerequisites',
            promoteHref: 'settings',
            promoteLabel: 'Open in Settings →',
        });
        renderOverlay_Prereqs().then(node => handle.update(node));
        return handle;
    };
    APP.overlay.openElastic = function () {
        // No promote target until Agent D wires Settings → Detection rules.
        const handle = APP.overlay.open('elastic', renderOverlay_Elastic(), {
            eyebrow: 'SIEM',
            title: 'Elastic Detection Rules',
            wide: true,
        });
        return handle;
    };

    // --- Delegated click handler — widget clicks → overlay opens -------
    function _wireDashboard() {
        const dash = document.querySelector('[data-page="dashboard"]');
        if (!dash || dash._v3OverlayWired) return;
        dash._v3OverlayWired = true;

        dash.addEventListener('click', (e) => {
            const depCard = e.target.closest('[data-v3-deployment-card]');
            if (depCard) {
                e.preventDefault();
                APP.overlay.openDeployment(depCard.getAttribute('data-v3-deployment-card'));
                return;
            }
            const link = e.target.closest('[data-v3-widget-link]');
            if (link) {
                e.preventDefault();
                e.stopPropagation();
                _openByKind(link.getAttribute('data-v3-widget-link'));
                return;
            }
            const widget = e.target.closest('[data-v3-widget]');
            if (!widget) return;
            // Architecture keeps its own onclick (APP.modal) so we skip here.
            const kind = widget.getAttribute('data-v3-widget');
            if (kind === 'architecture') return;
            e.preventDefault();
            _openByKind(kind);
        });

        dash.addEventListener('keydown', (e) => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            const widget = e.target.closest('[data-v3-widget]');
            if (!widget) return;
            if (widget.getAttribute('data-v3-widget') === 'architecture') return;
            e.preventDefault();
            _openByKind(widget.getAttribute('data-v3-widget'));
        });
    }

    function _openByKind(kind) {
        switch (kind) {
            case 'beacons':     APP.overlay.openBeacons(); break;
            case 'activity':    APP.overlay.openActivity(); break;
            case 'deployments': APP.overlay.openFailed(); break;
            case 'cost':        APP.overlay.openCost(); break;
            case 'failed':      APP.overlay.openFailed(); break;
            case 'prereqs':     APP.overlay.openPrereqs(); break;
            case 'elastic':     APP.overlay.openElastic(); break;
            default: console.warn('[APP.overlay] unknown widget kind:', kind);
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _wireDashboard);
    } else {
        _wireDashboard();
    }
})();
// === end v3 OVERLAY STACK (Agent C) ====================================
